// 文法詳解 N4(老師口吻,scripts/gen-grammar-detail.mjs 產生、build-grammar-detail.mjs 合併;改風格改 scripts/grammar-detail-samples.js 再重產)。
// key=文法 id;value=HTML(渲染時 .gd-jp 日文過 furiganaHTML→furigana+即點即查;中文解說不動)。
window.GRAMMAR_DETAIL = window.GRAMMAR_DETAIL || {};
Object.assign(window.GRAMMAR_DETAIL, {
  "n4-30": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>這三個就是中文的「<b>幫</b>」。你幫別人做事用<b>てあげる</b>，別人幫你做事用<b>てくれる</b>，你得到別人的幫忙用<b>てもらう</b>。方向跟送東西的あげる・くれる・もらう一模一樣，只是送出去的不是禮物，而是「幫忙做一件事」。</div><div class='gd-h'>怎麼接</div><div class='gd-sec'>動詞先變成て形，後面再接あげる／くれる／もらう。<br><span class='gd-pair'><span class='gd-jp'>貸す</span> → <span class='gd-jp'>貸して</span> → <span class='gd-jp'>貸してあげる</span></span><br><span class='gd-pair'><span class='gd-jp'>作る</span> → <span class='gd-jp'>作って</span> → <span class='gd-jp'>作ってくれる</span></span><br><span class='gd-pair'><span class='gd-jp'>撮る</span> → <span class='gd-jp'>撮って</span> → <span class='gd-jp'>撮ってもらう</span></span><br>要講得禮貌，就說あげます、くれます、もらいます。</div><div class='gd-h'>什麼時候用</div><div class='gd-sec'><span class='gd-tag'>我幫別人</span><b>てあげる</b>。樣子是「我は 對方に ～てあげる」。</div><div class='gd-ex-line'>・<span class='gd-jp'>妹に本を読んであげました。</span>（我唸書給妹妹聽）</div><div class='gd-ex-line'>・<span class='gd-jp'>友だちに傘を貸してあげた。</span>（我把傘借給朋友）</div><div class='gd-sec'><span class='gd-tag'>別人幫我</span><b>てくれる</b>。樣子是「對方が ～てくれる」。「給我」通常不用說出來，因為くれる本身就代表「往我這邊來」。家人也算「我這邊」的人。</div><div class='gd-ex-line'>・<span class='gd-jp'>母がお弁当を作ってくれた。</span>（媽媽幫我做了便當）</div><div class='gd-ex-line'>・<span class='gd-jp'>友だちが駅まで送ってくれました。</span>（朋友送我到車站）</div><div class='gd-sec'><span class='gd-tag'>我得到幫忙</span><b>てもらう</b>。樣子是「我は 對方に ～てもらう」，這裡的「に」意思是「<b>從誰那裡</b>」得到幫忙。</div><div class='gd-ex-line'>・<span class='gd-jp'>友だちに写真を撮ってもらいました。</span>（我請朋友幫我拍了照）</div><div class='gd-ex-line'>・<span class='gd-jp'>美容院で髪を切ってもらいました。</span>（我去美容院剪了頭髮）</div><div class='gd-sec'>頭髮是設計師剪的，不是自己剪，所以日文很自然會用てもらう。</div><div class='gd-h'>最常聽到的樣子</div><div class='gd-sec'><span class='gd-tag'>拜託別人</span>想請人幫忙，可以直接問「你可以幫我～嗎？」</div><div class='gd-ex-line'>・<span class='gd-jp'>ちょっと手伝ってくれない？</span>（可以幫我一下嗎？：對朋友）</div><div class='gd-ex-line'>・<span class='gd-jp'>このペンを貸してもらえませんか。</span>（可以借我這支筆嗎？：禮貌）</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・くれる只能往「我（這邊）」來。我幫別人一定是あげる，不能說「私が友だちに貸してくれた」。<br>・もらう的「に」不是「給」：<span class='gd-jp'>友だちに手伝ってもらった</span>是「朋友幫我」，不是「我幫朋友」。照中文直覺很容易讀反。<br>・對象要用哪個助詞，看原本的動詞，不一定是に。「幫媽媽拿行李」是<span class='gd-jp'>母の荷物を持ってあげた</span>，說成「母に持ってあげた」不自然。<br>・中文說「朋友教我日文」，日文如果只說<span class='gd-jp'>友だちが日本語を教えた</span>，聽起來像在講別人的事，也少了感謝的感覺。別人為你做的事，日本人幾乎都會加てくれる：<span class='gd-jp'>友だちが日本語を教えてくれた</span>。<br>・てあげる帶有「我特地幫你」的味道。對老師、主管說「持ってあげましょうか」很失禮，要說<span class='gd-jp'>お持ちしましょうか</span>。跟別人說「我幫了他」也要小心，聽起來可能像在邀功。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'>てくれる和てもらう常常在講同一件事，只是主角不同：<br><span class='gd-jp'>友だちが手伝ってくれた。</span>（朋友幫了我）主角是朋友，重點在「他人真好」。<br><span class='gd-jp'>友だちに手伝ってもらった。</span>（我請朋友幫了忙）主角是我，重點在「我得到幫忙」。<br>大部分情況兩個都能用。不過如果是對方<b>主動的好意</b>，用くれる最自然：<span class='gd-jp'>頼んでいないのに、友だちが手伝ってくれた。</span>（我沒拜託，朋友就主動來幫我了）<br>如果是<b>自己去拜託、花錢請人做</b>，比較常用もらう：<span class='gd-jp'>店の人に包んでもらいました。</span>（我請店員幫我包起來）</div><div class='gd-warn'>判斷小訣竅：我幫別人用あげる；主詞是對方、後面接が，用くれる；主詞是我、對方後面接に，用もらう。</div><div class='gd-h'>學會之後可以接著學</div><div class='gd-sec'>對老師、長輩要換成敬語版：<br><span class='gd-jp'>先生が教えてくださいました。</span>（老師教了我）<br><span class='gd-jp'>先生に教えていただきました。</span>（我承蒙老師指導）<br>拜託人的時候，「〜てもらえませんか」再更客氣一點，就是「〜ていただけませんか」。這些可以跟尊敬語、謙譲語一起學。</div>",
  "n4-17": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「〜ために」就是中文的<b>「為了～」</b>。前面放你想達成的目標，後面放你為了它<b>刻意去做的事</b>。例如「為了買車，我在存錢」，日文就是：<span class='gd-jp'>車を買うために、お金をためています。</span></div><div class='gd-h'>怎麼接</div><div class='gd-sec'><b>動詞</b>：直接用辭書形（字典上查到的原形）＋ために。<br><span class='gd-pair'><span class='gd-jp'>買う</span> → <span class='gd-jp'>買うために</span></span><span class='gd-pair'><span class='gd-jp'>勉強する</span> → <span class='gd-jp'>勉強するために</span></span><br><b>名詞</b>：中間要加一個「の」。<br><span class='gd-pair'><span class='gd-jp'>家族</span> → <span class='gd-jp'>家族のために</span></span><span class='gd-pair'><span class='gd-jp'>健康</span> → <span class='gd-jp'>健康のために</span></span></div><div class='gd-h'>什麼時候用</div><div class='gd-sec'><span class='gd-tag'>為了做到某件事</span>前面是動詞，講你想完成的目標。</div><div class='gd-ex-line'>・<span class='gd-jp'>日本語を勉強するために、日本へ来ました。</span>（為了學日文來到日本）</div><div class='gd-ex-line'>・<span class='gd-jp'>資格試験に合格するために、毎日図書館へ通っています。</span>（為了通過證照考試，每天都去圖書館）</div><div class='gd-sec'><span class='gd-tag'>為了某人、某件事好</span>前面是名詞，意思是「為了它著想」。</div><div class='gd-ex-line'>・<span class='gd-jp'>家族のために、頑張って働いています。</span>（為了家人努力工作）</div><div class='gd-ex-line'>・<span class='gd-jp'>健康のために、毎朝走っています。</span>（為了健康，每天早上跑步）</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・名詞後面一定要有の：<span class='gd-jp'>家族ために</span>是錯的，要說<span class='gd-jp'>家族のために</span>。<br>・ために前面<b>永遠是辭書形</b>，整句講過去的事也一樣：<span class='gd-jp'>切符を買うために、早く家を出ました。</span>（為了買票，很早就出門了）不會說成買ったために。<br>・前後通常是<b>同一個人</b>：我為了我的目標，自己去做某件事。如果是「為了讓孩子能上大學」，這種是別人要做到的事，改用ように：<span class='gd-jp'>子どもが大学に行けるように、働いています。</span>（為了讓孩子能上大學而工作）<br>・前面不放「能～」的說法（可能形）：<span class='gd-jp'>日本語が話せるために</span>不自然，要說<span class='gd-jp'>日本語が話せるように</span>。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'><b>ために vs ように（目的）</b><br>兩個都可以翻成「為了」，差在前面那個字長什麼樣子。</div><div class='gd-ex-line'>・<span class='gd-jp'>日本語の新聞を読むために、漢字を勉強しています。</span>（為了讀日文報紙，在學漢字）</div><div class='gd-ex-line'>・<span class='gd-jp'>日本語の新聞が読めるように、漢字を勉強しています。</span>（為了能看懂日文報紙，在學漢字）</div><div class='gd-sec'>ために前面是「<b>去做</b>某件事」（<span class='gd-jp'>読む</span>）；ように前面是「<b>能～</b>」或「變成某種狀態」（<span class='gd-jp'>読める</span>）。</div><div class='gd-sec'><b>ために（目的） vs ために（原因）</b><br>寫法完全一樣，但也可以表示「因為」。</div><div class='gd-ex-line'>・<span class='gd-jp'>健康のために、野菜を食べています。</span>（為了健康而吃蔬菜）</div><div class='gd-ex-line'>・<span class='gd-jp'>雨のために、試合が中止になりました。</span>（因為下雨，比賽取消了）</div><div class='gd-sec'>後面是你<b>主動去做</b>的事，就是「為了」；後面是<b>已經發生、沒得選</b>的結果，就是「因為」。表示原因的用法比較正式，平常說「因為」多半用<span class='gd-jp'>から</span>、<span class='gd-jp'>ので</span>。</div><div class='gd-warn'>判斷小訣竅：前面是「做～」用ために，前面是「能～」用ように；後面是自己刻意去做的事，ために就是「為了」，後面是發生的結果，ために就是「因為」。</div><div class='gd-h'>學會之後可以接著學</div><div class='gd-sec'>把ために換成「ための＋名詞」，意思是「為了～的…」：<span class='gd-jp'>留学のためのお金をためています。</span>（我在存留學要用的錢）</div>",
  "n4-18": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「〜ために」放在原因後面，意思是<b>「由於～」「因為～的關係」</b>。它比較正式、客觀，就像捷運廣播「由於號誌故障，列車將延誤」那種口氣。新聞、公告，或跟客人、主管說明狀況時很常見。</div><div class='gd-h'>什麼時候用</div><div class='gd-sec'><span class='gd-tag'>新聞・公告</span>交代發生了什麼事，造成什麼結果。</div><div class='gd-ex-line'>・<span class='gd-jp'>大雪のために、新幹線が止まりました。</span>（由於大雪，新幹線停駛了）</div><div class='gd-sec'><span class='gd-tag'>正式說明</span>跟老師、主管、客人解釋為什麼出狀況，聽起來客觀，不像在找藉口。</div><div class='gd-ex-line'>・<span class='gd-jp'>電車が遅れたために、授業に間に合いませんでした。</span>（因為電車誤點，我沒趕上課）</div><div class='gd-sec'>後面的結果大多是<b>已經發生、自己控制不了</b>的事，而且常常是不好的事，像是停駛、延誤、取消。</div><div class='gd-h'>怎麼接</div><div class='gd-sec'>ために前面放「原因」，各種詞都能接。要特別記的是：名詞要多加「の」，な形容詞要多加「な」。<br>動詞た形：<span class='gd-pair'><span class='gd-jp'>起きた</span> → <span class='gd-jp'>起きたために</span></span><br>動詞ない形：<span class='gd-pair'><span class='gd-jp'>足りない</span> → <span class='gd-jp'>足りないために</span></span><br>正在進行（ている）：<span class='gd-pair'><span class='gd-jp'>工事をしている</span> → <span class='gd-jp'>工事をしているために</span></span><br>表示狀態的動詞（ある、いる、できる）：<span class='gd-pair'><span class='gd-jp'>用事がある</span> → <span class='gd-jp'>用事があるために</span></span><br>い形容詞直接接：<span class='gd-pair'><span class='gd-jp'>狭い</span> → <span class='gd-jp'>狭いために</span></span><br>な形容詞加な：<span class='gd-pair'><span class='gd-jp'>不便</span> → <span class='gd-jp'>不便なために</span></span><br>名詞加の：<span class='gd-pair'><span class='gd-jp'>大雪</span> → <span class='gd-jp'>大雪のために</span></span></div><div class='gd-ex-line'>・<span class='gd-jp'>道が狭いために、大きい車は通れません。</span>（因為路很窄，大車過不去）</div><div class='gd-ex-line'>・<span class='gd-jp'>用事があるために、会議に出られません。</span>（因為有事，我沒辦法參加會議）</div><div class='gd-h'>最常聽到的樣子</div><div class='gd-sec'><span class='gd-tag'>のため</span>公告、廣播常把「に」省掉，變成「〜のため」「〜ため」。意思一樣，聽起來更正式。</div><div class='gd-ex-line'>・<span class='gd-jp'>工事中のため、この道は通れません。</span>（施工中，此路不通）</div><div class='gd-ex-line'>・<span class='gd-jp'>台風のため、明日の授業は休みです。</span>（因為颱風，明天停課）</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・名詞後面一定要加「の」：要說<span class='gd-jp'>大雪のために</span>，不能說大雪ために。な形容詞要加「な」：<span class='gd-jp'>不便なために</span>。<br>・後面不能接「～てください」「～ましょう」這種請對方做事或揪人的句子。<br>×<span class='gd-jp'>雨のために、傘を持っていってください。</span><br>○<span class='gd-jp'>雨なので、傘を持っていってください。</span>（因為下雨，請帶傘去）<br>・語氣很硬。跟朋友聊天說<span class='gd-jp'>雨のために行かない</span>，會像在念新聞稿。朋友之間用「から」就好。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'><b>ために（目的）vs ために（原因）</b>：這是同一個詞，要看前面接什麼來判斷。</div><div class='gd-ex-line'>・<span class='gd-jp'>日本へ行くために、お金をためています。</span>（為了去日本，我在存錢：目的）</div><div class='gd-ex-line'>・<span class='gd-jp'>雪が降ったために、電車が遅れました。</span>（因為下雪，電車誤點了：原因）</div><div class='gd-sec'>「名詞＋のために」兩種意思都有，要看那個名詞是你想達成的目標，還是已經發生的事件：</div><div class='gd-ex-line'>・<span class='gd-jp'>健康のために、毎朝走っています。</span>（為了健康，我每天早上跑步）</div><div class='gd-ex-line'>・<span class='gd-jp'>病気のために、学校を休みました。</span>（因為生病，我請假沒去學校）</div><div class='gd-warn'>判斷小訣竅：看ために前面。如果是自己能控制、想去達成的動作（例如<span class='gd-jp'>合格する</span>、<span class='gd-jp'>買う</span>的辭書形），就是「為了」。如果是た形或なかった、ている，或<span class='gd-jp'>ある</span>、<span class='gd-jp'>いる</span>、<span class='gd-jp'>できる</span>這類狀態動詞、形容詞，或<span class='gd-jp'>台風</span>、<span class='gd-jp'>病気</span>、<span class='gd-jp'>事故</span>這種表示事件或狀態的名詞，就是「因為」。<br>ない形要特別注意：接自己能控制的動作時，常常是「為了不～」，像<span class='gd-jp'>遅れないために、早く家を出ます</span>（為了不遲到，我提早出門）。接<span class='gd-jp'>足りない</span>、<span class='gd-jp'>わからない</span>這類自己控制不了的狀態時，才是「因為」。</div><div class='gd-sec'><b>ために vs から／ので</b>：同樣是「下雨，比賽取消」，看場合選說法。</div><div class='gd-ex-line'>・<span class='gd-jp'>雨だから、試合は中止だって。</span>（因為下雨，聽說比賽取消了：朋友聊天）</div><div class='gd-ex-line'>・<span class='gd-jp'>雨なので、試合は中止です。</span>（因為下雨，比賽取消：有禮貌的說明）</div><div class='gd-ex-line'>・<span class='gd-jp'>大雨のため、試合は中止になりました。</span>（由於大雨，比賽取消：公告、新聞）</div><div class='gd-warn'>判斷小訣竅：跟朋友講用「から」，客氣說明用「ので」，新聞、公告、正式文件才用「ため（に）」。後面要請對方做事時，用ので或から，不要用ために。</div>",
  "n4-19": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「<span class='gd-jp'>〜ように</span>」就是中文的<b>「為了能～」「為了不要～」</b>。重點是你想要的那個結果<b>你自己說了不算</b>，只能先做準備。像「為了不睡過頭，設兩個鬧鐘」：會不會睡過頭你控制不了，但鬧鐘你可以設。</div><div class='gd-h'>怎麼接</div><div class='gd-sec'>前半句放「希望變成的樣子」，後半句放「你為它做的事」。<br><b>希望「能～」</b>：可能形＋ように。可能形就是「能～、會～」的形，例如<span class='gd-pair'><span class='gd-jp'>話す</span> → <span class='gd-jp'>話せる</span></span>（能講）。<br><span class='gd-pair'><span class='gd-jp'>話せる</span> → <span class='gd-jp'>話せるように</span></span>（為了能講）<br><b>希望「不要～」</b>：ない形＋ように<br><span class='gd-pair'><span class='gd-jp'>忘れない</span> → <span class='gd-jp'>忘れないように</span></span>（為了不要忘記）<br><b>本來就不是自己能決定的動詞</b>（<span class='gd-jp'>わかる</span>、<span class='gd-jp'>治る</span>、<span class='gd-jp'>聞こえる</span>、<span class='gd-jp'>〜になる</span>）：直接用辭書形＋ように<br><span class='gd-pair'><span class='gd-jp'>治る</span> → <span class='gd-jp'>治るように</span></span>（為了能好起來）</div><div class='gd-h'>什麼時候用</div><div class='gd-sec'><span class='gd-tag'>為了能做到</span>想培養出某種能力。</div><div class='gd-ex-line'>・<span class='gd-jp'>日本語が話せるように、毎日練習しています。</span>（為了能講日文，我每天練習）</div><div class='gd-sec'><span class='gd-tag'>為了不要發生</span>先做準備，避免不想要的事。</div><div class='gd-ex-line'>・<span class='gd-jp'>忘れないように、メモしておきます。</span>（為了不要忘記，我先記下來）</div><div class='gd-ex-line'>・<span class='gd-jp'>風邪をひかないように、暖かくして寝てください。</span>（為了不要感冒，睡覺穿暖一點）</div><div class='gd-sec'><span class='gd-tag'>為了讓別人能～</span>前後可以是不同人：前半句講別人，後半句是你做的事。</div><div class='gd-ex-line'>・<span class='gd-jp'>子供が食べられるように、小さく切ります。</span>（為了讓小孩吃得下，我切小塊一點）</div><div class='gd-ex-line'>・<span class='gd-jp'>後ろの人にも聞こえるように、大きい声で話します。</span>（為了讓後面的人也聽得到，我大聲講）</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・想說「為了<b>能</b>講」，要用可能形<span class='gd-jp'>話せる</span>。用原本的<span class='gd-jp'>話す</span>就沒有「能」的意思了。<br>・ように前面永遠是辭書形或ない形，就算整句講的是過去也不變：<span class='gd-jp'>忘れないように、メモしました。</span>（為了不忘記，我記下來了）不會說成「忘れなかったように」。<br>・中文都說「為了」，但不是每個「為了」都用ように。買、去、讀書這種自己想做就能直接做的動作，要用<span class='gd-jp'>ために</span>（看下面）。<br>・ように本身沒有禮貌不禮貌的問題，禮不禮貌看句尾：<span class='gd-jp'>メモします</span>是禮貌，<span class='gd-jp'>メモする</span>是朋友版。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'>同樣在講「學日文的目的」：<br><span class='gd-jp'>日本で働くために、日本語を勉強しています。</span>（為了在日本工作而學日文）<br><span class='gd-jp'>日本人と話せるように、日本語を勉強しています。</span>（為了能跟日本人聊天而學日文）<br>「去日本工作」是你決定了就能去做的行動，用<b>ために</b>；「能跟日本人聊天」是學了之後才會慢慢出現的能力，你沒辦法說做就做，用<b>ように</b>。反過來說「話せるために」就很不自然。<br>還有一點：前後是不同人的時候，像<span class='gd-jp'>子供が食べられるように、小さく切ります</span>（吃的是小孩，切的是我），用ように就對了。ために通常前後是同一個人。</div><div class='gd-warn'>判斷小訣竅：前面是「能～」「不要～」，或是自己控制不了的事，就用ように；前面是自己想做就能直接去做的動作，就用ために。</div><div class='gd-h'>學會之後可以接著學</div><div class='gd-sec'>ように後面直接接<span class='gd-jp'>する</span>，意思就變成「盡量～」：<span class='gd-jp'>毎日野菜を食べるようにしています。</span>（我每天都盡量吃青菜）<br>單獨的ように後面接另一個動作，意思是「為了～」；<span class='gd-jp'>ようにする</span>則是「盡量～」，兩個不要搞混。</div>",
  "n4-20": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>這兩個長得很像，差在最後是<b>なる</b>還是<b>する</b>。<br><b>ようになる</b>＝「<b>變得</b>～了」，講的是<b>結果</b>，以前不會、現在會了。<br><b>ようにする</b>＝「我<b>盡量</b>～」，講的是自己<b>有在努力</b>，還在做、不保證每次成功。<br>中文的「變成」跟「盡量」，剛好對上なる跟する。</div><div class='gd-h'>ようになる：以前不會，現在會了</div><div class='gd-sec'><span class='gd-tag'>能力變化</span>最常見。前面接<b>可能形</b>（表示「會～、能～」的形，像<span class='gd-jp'>話せる</span>、<span class='gd-jp'>食べられる</span>），或接<span class='gd-jp'>できる</span>、<span class='gd-jp'>わかる</span>。</div><div class='gd-ex-line'>・<span class='gd-jp'>練習して、日本語が少し話せるようになりました。</span>（練習之後，我變得會講一點日文了）</div><div class='gd-ex-line'>・<span class='gd-jp'>辛い物が食べられるようになった。</span>（我變得敢吃辣了）</div><div class='gd-sec'><span class='gd-tag'>習慣變化</span>接一般的辭書形，意思是「開始變成會這樣做」。</div><div class='gd-ex-line'>・<span class='gd-jp'>日本に来てから、毎朝コーヒーを飲むようになった。</span>（來日本之後，我變成每天早上都會喝咖啡）</div><div class='gd-sec'>變化可能是自己練出來的，也可能是不知不覺變的，重點都是<b>現在的結果</b>。</div><div class='gd-h'>ようにする：我盡量這樣做</div><div class='gd-sec'>要做的事：辭書形＋ようにする　<span class='gd-pair'><span class='gd-jp'>食べる</span> → <span class='gd-jp'>食べるようにする</span></span><br>不要做的事：ない形＋ようにする　<span class='gd-pair'><span class='gd-jp'>飲まない</span> → <span class='gd-jp'>飲まないようにする</span></span></div><div class='gd-sec'><span class='gd-tag'>ようにしている</span>最近一直在保持的習慣，最常用。</div><div class='gd-ex-line'>・<span class='gd-jp'>毎日野菜を食べるようにしています。</span>（我都盡量每天吃青菜）</div><div class='gd-ex-line'>・<span class='gd-jp'>夜はコーヒーを飲まないようにしている。</span>（我晚上都盡量不喝咖啡）</div><div class='gd-sec'><span class='gd-tag'>ようにします</span>從現在開始要注意，常用在道歉、保證。</div><div class='gd-ex-line'>・<span class='gd-jp'>これからは遅れないようにします。</span>（以後我會注意不遲到）</div><div class='gd-sec'><span class='gd-tag'>ようにしてください</span>請對方盡量做到，醫生、老師很常講。</div><div class='gd-ex-line'>・<span class='gd-jp'>薬は毎日飲むようにしてください。</span>（藥請記得每天吃）</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・要說「變得<b>會</b>～」，前面要用可能形：<span class='gd-jp'>日本語が話せるようになった</span>才是「變得會講日文」。寫成<span class='gd-jp'>日本語を話すようになった</span>，意思會變成「開始有在講日文了」，講的是習慣，不是能力。<br>・用了可能形，前面的「を」通常會換成「が」：<span class='gd-jp'>日本語が話せる</span>。<br>・「變得<b>不</b>～了」，日本人通常直接說<b>〜なくなる</b>：<span class='gd-jp'>最近、テレビを見なくなった。</span>（最近變得不看電視了）。比較少說「見ないようになった」。<br>・形容詞、名詞不能接ようになる。「變大」是<span class='gd-jp'>大きくなる</span>，「變安靜」是<span class='gd-jp'>静かになる</span>，「當老師」是<span class='gd-jp'>先生になる</span>。ようになる只接動詞。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'>同樣講早起，看三種說法：<br><b>ようになった</b>＝結果：<span class='gd-jp'>早く起きられるようになった。</span>（我變得能早起了）<br><b>ようにしている</b>＝努力中：<span class='gd-jp'>早く起きるようにしている。</span>（我都盡量早起）<br><b>ことにした</b>＝下決定：<span class='gd-jp'>明日から早く起きることにした。</span>（我決定明天開始早起）</div><div class='gd-sec'>另外，<b>ことになった</b>是「被決定、被安排成這樣」，不是自己變的，也不是自己努力：<span class='gd-jp'>来月から大阪で働くことになった。</span>（下個月開始要去大阪上班了）</div><div class='gd-warn'>判斷小訣竅：「變成會～了」用ようになる，「盡量～」用ようにする，「決定～」用ことにする，「被安排～」用ことになる。</div><div class='gd-h'>學會之後可以接著學</div><div class='gd-sec'>拿掉なる、する，單獨的「ように」可以表示「為了讓～」：<span class='gd-jp'>忘れないように、メモします。</span>（為了不忘記，我記下來）</div>",
  "n4-8": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「のに」就是中文的<b>「明明～，卻…」</b>。前面是一件確定的事，後面的結果跟你想的不一樣，你心裡會有「怎麼會這樣」的感覺，可能是不滿、意外，也可能是可惜。</div><div class='gd-ex-line'>・<span class='gd-jp'>薬を飲んだのに、熱が下がらない。</span>（明明吃了藥，燒卻沒退）</div><div class='gd-h'>什麼時候用</div><div class='gd-sec'>前面是一個<b>已經確定的事實</b>，可以是已經發生的事、現在的狀態，或確定會發生的事。後面接「照理說不該這樣」的結果。</div><div class='gd-ex-line'>・<span class='gd-jp'>約束したのに、彼は来なかった。</span>（明明說好了，他卻沒來）</div><div class='gd-ex-line'>・<span class='gd-jp'>この店は安いのに、おいしい。</span>（這家店明明很便宜，卻很好吃）</div><div class='gd-ex-line'>・<span class='gd-jp'>明日テストなのに、全然勉強していない。</span>（明天明明要考試，卻完全沒唸書）</div><div class='gd-sec'>第二句是意外的驚喜，所以のに不一定是抱怨，重點是<b>「跟預期相反」</b>。</div><div class='gd-h'>怎麼接</div><div class='gd-sec'>前面用普通形（沒有ます的說法）。<br><b>動詞</b>：<span class='gd-pair'><span class='gd-jp'>行った</span> → <span class='gd-jp'>行ったのに</span></span><span class='gd-pair'><span class='gd-jp'>来ない</span> → <span class='gd-jp'>来ないのに</span></span><br><b>い形容詞</b>：<span class='gd-pair'><span class='gd-jp'>高い</span> → <span class='gd-jp'>高いのに</span></span><br><b>な形容詞、名詞</b>：要先補一個「な」。<br><span class='gd-pair'><span class='gd-jp'>静か</span> → <span class='gd-jp'>静かなのに</span></span><span class='gd-pair'><span class='gd-jp'>日曜日</span> → <span class='gd-jp'>日曜日なのに</span></span><br>講過去的話就用だった：<span class='gd-pair'><span class='gd-jp'>雨</span> → <span class='gd-jp'>雨だったのに</span></span></div><div class='gd-h'>最常聽到的樣子</div><div class='gd-sec'><span class='gd-tag'>話只講一半</span>後面的結果不講出來，留下「唉」的感覺。抱怨、惋惜時很常用。</div><div class='gd-ex-line'>・<span class='gd-jp'>せっかく作ったのに…。</span>（虧我還特地做了…）</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・な形容詞和名詞後面一定要有な：說<span class='gd-jp'>静かなのに</span>，不能說「静かのに」或「静かだのに」。<br>・のに後面<b>不能接自己的意志、邀約、命令、請求</b>，像「～吧」「我要～」「請～」都不行。<br>　× 高いのに、買おう。<br>　○ <span class='gd-jp'>高いけど、買おう。</span>（雖然很貴，還是買吧）<br>・のに帶著情緒，對長輩、客人直接說「～のに」可能聽起來像在抱怨或責怪對方，要注意場合。<br>・另一種長得一樣的「のに」意思是「做～的時候（用、花）」：<span class='gd-jp'>駅へ行くのに30分かかる。</span>（去車站要花 30 分鐘）。這裡沒有「明明」的意思，看後面是不是「花時間、需要、使用」就分得出來。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'><b>のに</b>＝明明～卻…（有情緒）：<span class='gd-jp'>薬を飲んだのに、熱が下がらない。</span>（明明吃了藥，燒卻沒退，怎麼會這樣）<br><b>けど</b>＝雖然～但是…（單純轉折，比較冷靜）：<span class='gd-jp'>薬を飲んだけど、熱が下がらない。</span>（吃了藥，但燒還沒退）<br><b>ても</b>＝就算～也…，可以講還沒發生的假設：<span class='gd-jp'>明日雨が降っても、行きます。</span>（就算明天下雨我也要去）<br>這句不能換成のに，因為「明天會不會下雨」還不確定，而且後面是自己要做的事。</div><div class='gd-sec'><b>ので</b>的意思剛好相反，是「因為～所以…」，順著結果走：<br><span class='gd-jp'>雨なので、出かけなかった。</span>（因為下雨，所以沒出門）<br><span class='gd-jp'>雨なのに、彼は出かけた。</span>（明明在下雨，他卻出門了）</div><div class='gd-warn'>判斷小訣竅：前面是確定的事實（不是假設），而且你心裡想「怎麼會這樣」，就用のに；只是平平地轉折用けど；「就算～也」用ても；結果順理成章用ので。</div>",
  "n4-22": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「〜ても」就是中文的<b>「就算～也…」「即使～還是…」</b>。前面先退一步，承認有某個情況；後面接著說：結果還是一樣，不受影響。像「就算下雨，我也要去」，日文就是<span class='gd-jp'>雨が降っても、行きます。</span></div><div class='gd-h'>怎麼接</div><div class='gd-sec'><b>動詞</b>：先變成て形，再加「も」。<br><span class='gd-pair'><span class='gd-jp'>書く</span> → <span class='gd-jp'>書いて</span> → <span class='gd-jp'>書いても</span></span><br><span class='gd-pair'><span class='gd-jp'>読む</span> → <span class='gd-jp'>読んで</span> → <span class='gd-jp'>読んでも</span></span>（て形是「で」的，就變成「でも」）<br><span class='gd-pair'><span class='gd-jp'>食べる</span> → <span class='gd-jp'>食べても</span></span><span class='gd-pair'><span class='gd-jp'>する</span> → <span class='gd-jp'>しても</span></span><span class='gd-pair'><span class='gd-jp'>来る</span> → <span class='gd-jp'>来ても</span>（きても）</span></div><div class='gd-sec'><b>い形容詞</b>：把最後的「い」換成「く」，再加「ても」。<br><span class='gd-pair'><span class='gd-jp'>高い</span> → <span class='gd-jp'>高くても</span></span><span class='gd-pair'><span class='gd-jp'>悪い</span> → <span class='gd-jp'>悪くても</span></span></div><div class='gd-sec'><b>な形容詞・名詞</b>：直接加「でも」。<br><span class='gd-pair'><span class='gd-jp'>静か</span> → <span class='gd-jp'>静かでも</span></span><span class='gd-pair'><span class='gd-jp'>雨</span> → <span class='gd-jp'>雨でも</span></span></div><div class='gd-sec'><b>就算不～</b>：把ない形的「ない」換成「なくても」。<br><span class='gd-pair'><span class='gd-jp'>行かない</span> → <span class='gd-jp'>行かなくても</span></span></div><div class='gd-h'>什麼時候用</div><div class='gd-sec'><span class='gd-tag'>就算發生了</span>先假設一個情況，說自己的決定不會變。</div><div class='gd-ex-line'>・<span class='gd-jp'>体調が悪くても、試合に出ます。</span>（就算身體不舒服，我也要出賽）</div><div class='gd-ex-line'>・<span class='gd-jp'>高くても、買います。</span>（就算很貴我也要買）</div><div class='gd-sec'><span class='gd-tag'>試了還是沒用</span>真的做過了，結果還是不如預期。</div><div class='gd-ex-line'>・<span class='gd-jp'>何度読んでも、意味がわかりません。</span>（讀了好幾次還是看不懂）</div><div class='gd-ex-line'>・<span class='gd-jp'>電話しても、出ません。</span>（打電話給他也不接）</div><div class='gd-sec'><span class='gd-tag'>不管怎樣都</span>前面放<span class='gd-jp'>いくら</span>、<span class='gd-jp'>どんなに</span>、<span class='gd-jp'>何を</span>、<span class='gd-jp'>誰が</span>這種詞，意思變成「不管再怎麼～都…」。</div><div class='gd-ex-line'>・<span class='gd-jp'>いくら食べても、太りません。</span>（不管吃多少都不會胖）</div><div class='gd-ex-line'>・<span class='gd-jp'>どんなに忙しくても、朝ごはんは食べます。</span>（再怎麼忙，早餐還是會吃）</div><div class='gd-ex-line'>・<span class='gd-jp'>誰が来ても、ドアを開けないでください。</span>（不管誰來都不要開門）</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・<span class='gd-jp'>読む</span>、<span class='gd-jp'>飲む</span>、<span class='gd-jp'>遊ぶ</span>這種て形是「で」的，要說<span class='gd-jp'>読んでも</span>，不是読んても。<br>・名詞、な形容詞接的是「でも」：<span class='gd-jp'>雨でも</span>、<span class='gd-jp'>元気でも</span>。<span class='gd-jp'>いい</span>要變成<span class='gd-jp'>よくても</span>，不是いくても。<br>・後半句要說「結果沒變、跟預期相反」。如果是順理成章的結果，假設的情況要用たら（或ば），已經是事實、要說原因時才用から、ので。<br>　<span class='gd-jp'>雨が降ったら、行きません。</span>（如果下雨就不去）<br>　<span class='gd-jp'>雨が降っても、行きます。</span>（就算下雨也要去）<br>・中文的「也」已經包在ても裡面，後半句不用再加「も」。說成<span class='gd-jp'>雨が降っても、私も行きます</span>，會變成「我也（跟別人一樣）要去」。<br>・不要跟「〜てもいいです」搞混：後面多了いいです，意思就變成「可以～」。<span class='gd-jp'>食べてもいいです。</span>（可以吃）／<span class='gd-jp'>食べても、太りません。</span>（就算吃也不會胖）</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'><b>のに</b>也有「卻」的感覺，但用法不一樣。同樣是下雨的情境：<br><span class='gd-jp'>雨でも、行きます。</span>（就算下雨我也要去：說自己的決定，現在下不下都沒關係）<br><span class='gd-jp'>雨なのに、彼は行きました。</span>（明明在下雨，他還是去了：已經發生，帶點意外或不以為然）<br><b>ても</b>的重點是「前面怎樣都改變不了後面」，可以是假設，也可以是試過的事。<br><b>のに</b>前面一定是已經成真的事，口氣是「明明～卻」，常帶抱怨或意外。而且のに後面不能接「我要～」「請～」這種說法。</div><div class='gd-warn'>判斷小訣竅：想說「就算～，我也要／請你～」用ても；想抱怨「明明～，怎麼卻～」用のに。</div><div class='gd-h'>學會之後可以接著學</div><div class='gd-sec'>前面加上<span class='gd-jp'>たとえ</span>，語氣更強：<span class='gd-jp'>たとえ反対されても、留学します。</span>（就算被反對，我也要去留學）</div>",
  "n4-24": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「〜てしまう」很像中文的<b>「～掉了」「～完了」「不小心～了」</b>。<br>它有兩個意思：一是<b>整個做完、做光</b>，例如「把蛋糕吃掉了」；二是<b>不小心做了、很懊惱</b>，例如「糟糕，把錢包忘了」。兩個意思的共通點是：<b>事情已經做完，回不去了</b>。</div><div class='gd-h'>什麼時候用</div><div class='gd-sec'><span class='gd-tag'>全部做完</span>強調整件事徹底做完、做光，常帶一點「一下子就～」或「趕快處理掉」的感覺。</div><div class='gd-ex-line'>・<span class='gd-jp'>宿題はもう全部やってしまいました。</span>（作業已經全部寫完了）</div><div class='gd-ex-line'>・<span class='gd-jp'>ご飯の前に、宿題をやってしまおう。</span>（吃飯前先把作業寫完吧）</div><div class='gd-sec'><span class='gd-tag'>不小心・後悔</span>做了不想做的事，或發生了不想要的結果，心裡覺得「糟了」「好可惜」。日常最常用的是這個意思。</div><div class='gd-ex-line'>・<span class='gd-jp'>財布を忘れてしまいました。</span>（我不小心把錢包忘了）</div><div class='gd-ex-line'>・<span class='gd-jp'>大事なお皿を割ってしまった。</span>（把很重要的盤子打破了）</div><div class='gd-ex-line'>・<span class='gd-jp'>今朝、寝坊してしまいました。</span>（今天早上不小心睡過頭了）</div><div class='gd-sec'>有時候兩個意思會同時出現，就看上下文：<span class='gd-jp'>ケーキを全部食べてしまった。</span>可以是單純的「蛋糕吃光了」，也可以是「不小心全吃光了（糟糕）」。</div><div class='gd-h'>怎麼接</div><div class='gd-sec'>先把動詞變成て形，再加<b>しまう</b>。<br><span class='gd-pair'><span class='gd-jp'>忘れる</span> → <span class='gd-jp'>忘れて</span> → <span class='gd-jp'>忘れてしまう</span></span><br><span class='gd-pair'><span class='gd-jp'>割る</span> → <span class='gd-jp'>割って</span> → <span class='gd-jp'>割ってしまう</span></span><br><span class='gd-pair'><span class='gd-jp'>飲む</span> → <span class='gd-jp'>飲んで</span> → <span class='gd-jp'>飲んでしまう</span></span><br>しまう本身照第一類（五段動詞）變：禮貌說<span class='gd-jp'>しまいます</span>，過去說<span class='gd-jp'>しまいました</span>，朋友之間說<span class='gd-jp'>しまった</span>。因為講的多半是已經發生的事，所以<b>最常聽到的是過去形</b>。</div><div class='gd-h'>最常聽到的樣子</div><div class='gd-sec'><span class='gd-tag'>口語縮短</span>講話時常把「てしまう」縮成<b>ちゃう</b>，「でしまう」縮成<b>じゃう</b>。<br><span class='gd-pair'><span class='gd-jp'>食べてしまった</span> → <span class='gd-jp'>食べちゃった</span></span><br><span class='gd-pair'><span class='gd-jp'>行ってしまう</span> → <span class='gd-jp'>行っちゃう</span></span><br><span class='gd-pair'><span class='gd-jp'>飲んでしまった</span> → <span class='gd-jp'>飲んじゃった</span></span></div><div class='gd-ex-line'>・<span class='gd-jp'>あ、ケーキ全部食べちゃった。</span>（啊，蛋糕全部被我吃光了）</div><div class='gd-sec'><span class='gd-tag'>單獨一句</span>發現出錯時脫口而出的<span class='gd-jp'>しまった！</span>，就是「糟了！」「慘了！」。</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・て形是「んで」的動詞（<span class='gd-jp'>飲む</span>、<span class='gd-jp'>読む</span>、<span class='gd-jp'>遊ぶ</span>、<span class='gd-jp'>死ぬ</span>），接的是<b>でしまう</b>，縮短後是<b>じゃう</b>：<span class='gd-jp'>飲んじゃった</span>，不是飲んちゃった。<br>・ちゃう、じゃう是口語，對朋友很自然；對主管、客人或寫信，用<span class='gd-jp'>〜てしまいました</span>比較穩。<br>・單獨的動詞<span class='gd-jp'>しまう</span>是「收起來」的意思：<span class='gd-jp'>本をかばんにしまう。</span>（把書收進包包）。前面沒有て形，就不是這個文法。<br>・中文說「我忘了」就夠了，所以很多人不會加しまう。日文的<span class='gd-jp'>忘れた</span>文法沒錯，但聽起來只是在陳述事實；說<span class='gd-jp'>忘れてしまった</span>，才帶出「糟糕、懊惱」的心情。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'>同一件事，用一般的過去形「た」，或用「てしまった」，感覺不一樣：<br><b>た</b>＝單純說發生了什麼：<span class='gd-jp'>財布を忘れた。</span>（我忘了帶錢包）<br><b>てしまった</b>＝加上「糟了、好可惜」的心情：<span class='gd-jp'>財布を忘れてしまった。</span>（慘了，我把錢包忘了）<br><br><b>た</b>＝吃了：<span class='gd-jp'>ケーキを食べた。</span>（我吃了蛋糕）<br><b>てしまった</b>＝吃光了，或不小心吃掉了：<span class='gd-jp'>ケーキを食べてしまった。</span>（蛋糕被我吃光了）</div><div class='gd-warn'>判斷小訣竅：中文想加「～掉了」「～光了」「糟糕，～了」的時候，日文就用てしまう；只是平平地說發生什麼事，用た就好。</div><div class='gd-h'>學會之後可以接著學</div><div class='gd-sec'>同樣是「て形＋一個動詞」的還有<span class='gd-jp'>〜ておく</span>（事先做好準備），可以放在一起比較。ちゃう、じゃう這類講話時的縮短說法，在「縮約表現」那一課會一次整理。</div>",
  "n4-28": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「ところ」本來是「地方」，在這裡變成<b>時間上的某個點</b>。它跟中文的<b>「正要～」「正在～」「剛～」</b>剛好對得上：前面的動詞換個形，就能交代這件事做到哪一步了。</div><div class='gd-h'>同一個情境，三種回答</div><div class='gd-sec'>朋友打電話問你「<span class='gd-jp'>今、大丈夫？</span>」（現在方便嗎？），你可以這樣回：</div><div class='gd-ex-line'>・<span class='gd-jp'>ごめん、今から出かけるところ。</span>（抱歉，我正要出門）</div><div class='gd-ex-line'>・<span class='gd-jp'>今、ご飯を食べているところ。</span>（我現在正在吃飯）</div><div class='gd-ex-line'>・<span class='gd-jp'>ちょうど今、家に着いたところ。</span>（我剛到家）</div><div class='gd-sec'>這就是「ところ」最常出現的時機：<b>跟對方說明你現在的狀況</b>。跟朋友講可以只說「ところ」，禮貌一點就加「です」。</div><div class='gd-h'>怎麼接</div><div class='gd-sec'><span class='gd-tag'>正要做</span>辭書形（字典裡查得到的原形）＋ところ。事情<b>還沒開始</b>，馬上要開始。<br><span class='gd-pair'><span class='gd-jp'>食べる</span> → <span class='gd-jp'>食べるところです</span></span>（正要吃）</div><div class='gd-ex-line'>・<span class='gd-jp'>これから晩ご飯を作るところです。</span>（我正要開始煮晚餐）</div><div class='gd-sec'><span class='gd-tag'>正在做</span>ている＋ところ。事情<b>做到一半</b>，還沒結束。<br><span class='gd-pair'><span class='gd-jp'>食べている</span> → <span class='gd-jp'>食べているところです</span></span>（正在吃）</div><div class='gd-ex-line'>・<span class='gd-jp'>今、宿題をしているところです。</span>（我現在正在寫作業）</div><div class='gd-sec'><span class='gd-tag'>剛做完</span>た形（過去式的那個形）＋ところ。事情<b>才剛結束</b>。<br><span class='gd-pair'><span class='gd-jp'>食べた</span> → <span class='gd-jp'>食べたところです</span></span>（剛吃完）</div><div class='gd-ex-line'>・<span class='gd-jp'>今、起きたところです。</span>（我剛起床）</div><div class='gd-sec'>常跟它一起出現的詞：<span class='gd-jp'>これから</span>、<span class='gd-jp'>今から</span>（配正要）、<span class='gd-jp'>今</span>（配正在）、<span class='gd-jp'>ちょうど</span>、<span class='gd-jp'>今</span>（配剛做完）。</div><div class='gd-h'>講過去也可以</div><div class='gd-sec'>把「です」換成「でした」，就能講<b>過去某一刻</b>你正處在哪個階段。</div><div class='gd-ex-line'>・<span class='gd-jp'>電話が来たとき、お風呂に入っているところでした。</span>（電話來的時候，我正在洗澡）</div><div class='gd-ex-line'>・<span class='gd-jp'>友達が来たとき、ちょうど出かけるところでした。</span>（朋友來的時候，我剛好正要出門）</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・三個是不同時間點，接錯意思就跑掉：<b>辭書形＝還沒開始、ている＝進行中、た形＝剛結束</b>。「<span class='gd-jp'>食べるところです</span>」是「正要吃」，不是「正在吃」。<br>・ところ前面要用普通形，不能接ます：是<span class='gd-jp'>行くところです</span>，不是行きますところです。<br>・「ているところ」講的是<b>某個時間點</b>（現在，或過去的某一刻）正在進行的動作。每天的習慣只能用一般的ている：<span class='gd-jp'>毎日日本語を勉強しています。</span>（我每天都在學日文），不會說成「毎日勉強しているところです」。<br>・「住んでいる」「結婚している」這種表示一直維持的狀態，也不能加ところ。<br>・「たところ」是<b>真的剛剛</b>，通常是幾分鐘、頂多幾小時內的事。來日本已經三個月，就不要說「来たところです」。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'><b>たところ</b>跟<b>たばかり</b>（n4-29）都翻成「剛～」。<br>剛走進車站那一刻，兩個都可以：<span class='gd-jp'>今、駅に着いたところです。</span>／<span class='gd-jp'>今、駅に着いたばかりです。</span>（我剛到車站）<br>但如果已經過了一段時間，只是<b>你自己覺得還很新</b>，就只能用たばかり：<span class='gd-jp'>日本に来たばかりです。</span>（我才剛來日本沒多久，例如來了三個月）<br>另外，たばかり可以直接放在名詞前面：<span class='gd-jp'>買ったばかりの靴</span>（剛買的鞋子），たところ不能這樣用。</div><div class='gd-warn'>判斷小訣竅：真的就在剛剛、時間點很精準，用たところ；時間過了一陣子但感覺還很新，用たばかり。</div><div class='gd-h'>學會之後可以接著學</div><div class='gd-sec'>「辭書形＋ところでした」前面加「<span class='gd-jp'>もう少しで</span>」，會變成「差一點就～」：<span class='gd-jp'>もう少しで電車に遅れるところでした。</span>（差一點就沒趕上電車）</div>",
  "n4-31": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「〜そう」就是中文的<b>「看起來～」「好像快要～了」</b>。你眼睛看到一個樣子，馬上冒出一個感覺，就用它。例如看到蛋糕說「看起來好好吃」，看到天空很暗說「好像快下雨了」。</div><div class='gd-h'>什麼時候用</div><div class='gd-sec'><span class='gd-tag'>動詞：快要發生了</span>看到徵兆，覺得事情馬上就要發生。</div><div class='gd-ex-line'>・<span class='gd-jp'>空が暗いですね。雨が降りそうです。</span>（天好暗喔，好像快下雨了）</div><div class='gd-ex-line'>・<span class='gd-jp'>あ、ボタンが取れそう。</span>（啊，扣子快掉了）</div><div class='gd-sec'><span class='gd-tag'>形容詞：看起來很～</span>從外表感覺出來的樣子。</div><div class='gd-ex-line'>・<span class='gd-jp'>このケーキ、おいしそう！</span>（這蛋糕看起來好好吃）</div><div class='gd-ex-line'>・<span class='gd-jp'>田中さんは今日も元気そうですね。</span>（田中先生今天看起來也很有精神呢）</div><div class='gd-h'>怎麼接</div><div class='gd-sec'><b>動詞</b>：先變成ます形，把ます拿掉，加そう。<br><span class='gd-pair'><span class='gd-jp'>降る</span> → <span class='gd-jp'>降ります</span> → <span class='gd-jp'>降りそう</span></span><br><span class='gd-pair'><span class='gd-jp'>泣く</span> → <span class='gd-jp'>泣きそう</span></span><span class='gd-pair'><span class='gd-jp'>できる</span> → <span class='gd-jp'>できそう</span></span></div><div class='gd-sec'><b>い形容詞</b>：把最後的「い」拿掉，加そう。<br><span class='gd-pair'><span class='gd-jp'>おいしい</span> → <span class='gd-jp'>おいしそう</span></span><span class='gd-pair'><span class='gd-jp'>熱い</span> → <span class='gd-jp'>熱そう</span></span></div><div class='gd-sec'><b>な形容詞</b>：直接加そう，不用加だ。<br><span class='gd-pair'><span class='gd-jp'>元気</span> → <span class='gd-jp'>元気そう</span></span><span class='gd-pair'><span class='gd-jp'>暇</span> → <span class='gd-jp'>暇そう</span></span></div><div class='gd-sec'><b>兩個例外，直接背</b>：<span class='gd-pair'><span class='gd-jp'>いい</span> → <span class='gd-jp'>よさそう</span></span><span class='gd-pair'><span class='gd-jp'>ない</span> → <span class='gd-jp'>なさそう</span></span><br>要講「看起來不～」，形容詞就從否定形接：<span class='gd-pair'><span class='gd-jp'>おいしくない</span> → <span class='gd-jp'>おいしくなさそう</span></span><br>動詞要講「看起來不會～」，用<span class='gd-jp'>降りそうにない</span>或<span class='gd-jp'>降りそうもない</span>（看起來不會下）。</div><div class='gd-h'>最常聽到的樣子</div><div class='gd-sec'>そう的用法跟な形容詞一樣：後面接名詞變<b>そうな</b>，後面接動詞變<b>そうに</b>。</div><div class='gd-ex-line'>・<span class='gd-jp'>おいしそうなパンですね。</span>（看起來很好吃的麵包呢）</div><div class='gd-ex-line'>・<span class='gd-jp'>子どもたちが楽しそうに遊んでいる。</span>（孩子們玩得很開心的樣子）</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・<span class='gd-jp'>いい</span>的樣態是<b>よさそう</b>，不能說いさそう；<span class='gd-jp'>いいそう</span>會變成「聽說很好」。<br>・<span class='gd-jp'>かわいそう</span>是「好可憐」，不是「看起來很可愛」。<br>・一眼就看得出來的事不用そう。花很漂亮就直接說<span class='gd-jp'>きれいですね</span>，不說「看起來很漂亮」的きれいそう。<br>・名詞後面不能直接加這個そう，「看起來像學生」不能說学生そう。<br>・動詞＋そう常常是「<b>快要</b>～了」，不只是「好像」：<span class='gd-jp'>泣きそう</span>是「快哭了」。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'>下一課的「〜そうです（傳聞）」是<b>「聽說～」</b>，長得幾乎一樣，只差前面接的形式。用同樣的字對照：<br><b>動詞</b>：<span class='gd-jp'>雨が降りそうです。</span>（看起來快下雨了）<br>　　　<span class='gd-jp'>雨が降るそうです。</span>（聽說會下雨）<br><b>い形容詞</b>：<span class='gd-jp'>おいしそうです。</span>（看起來很好吃）<br>　　　　<span class='gd-jp'>おいしいそうです。</span>（聽說很好吃）<br><b>な形容詞</b>：<span class='gd-jp'>元気そうです。</span>（看起來很有精神）<br>　　　　<span class='gd-jp'>元気だそうです。</span>（聽說很有精神）</div><div class='gd-warn'>判斷小訣竅：そう前面如果是辭書形、普通形（<span class='gd-jp'>降る</span>、<span class='gd-jp'>おいしい</span>、<span class='gd-jp'>元気だ</span>）＝聽說；動詞把ます拿掉、い形容詞把い拿掉、な形容詞直接接、沒有だ（<span class='gd-jp'>降り</span>、<span class='gd-jp'>おいし</span>、<span class='gd-jp'>元気</span>）＝看起來。</div><div class='gd-h'>學會之後可以接著學</div><div class='gd-sec'>接著學「〜そうです（傳聞）」，把兩個放在一起練。再來是「〜ようです・〜みたいです」，那是根據線索推測的「好像～」。</div>",
  "n4-32": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>這個「〜そうです」就是中文的<b>「聽說～」「據說～」</b>，只是日文把它放在句子最後面。你從新聞、氣象預報、朋友那裡聽到一件事，要轉述給別人，就在那句話後面加「そうです」。意思是「這不是我說的，是我聽來的」。</div><div class='gd-ex-line'>・<span class='gd-jp'>新しい社長は厳しいそうです。</span>（聽說新社長很嚴格）</div><div class='gd-ex-line'>・<span class='gd-jp'>田中さんはもう帰ったそうです。</span>（聽說田中已經回去了）</div><div class='gd-h'>怎麼接</div><div class='gd-sec'>前面放<b>普通形</b>，也就是不加ます、です的「朋友版說法」。你可以想成：先把聽到的那句話用朋友版講完整，最後再黏上そうです。<br><b>動詞</b>：<span class='gd-pair'><span class='gd-jp'>降る</span> → <span class='gd-jp'>降るそうです</span></span><span class='gd-pair'><span class='gd-jp'>来ない</span> → <span class='gd-jp'>来ないそうです</span></span><span class='gd-pair'><span class='gd-jp'>結婚した</span> → <span class='gd-jp'>結婚したそうです</span></span><br><b>い形容詞</b>：直接接。<span class='gd-pair'><span class='gd-jp'>高い</span> → <span class='gd-jp'>高いそうです</span></span><br><b>な形容詞、名詞</b>：一定要先加<b>だ</b>。<span class='gd-pair'><span class='gd-jp'>静か</span> → <span class='gd-jp'>静かだそうです</span></span><span class='gd-pair'><span class='gd-jp'>雨</span> → <span class='gd-jp'>雨だそうです</span></span></div><div class='gd-h'>最常聽到的樣子</div><div class='gd-sec'><span class='gd-tag'>先講消息來源</span>前面常搭「〜によると」（根據～）、「〜の話では」（照～的說法），先交代是從哪裡聽來的。</div><div class='gd-ex-line'>・<span class='gd-jp'>天気予報によると、明日は雨だそうです。</span>（氣象預報說明天會下雨）</div><div class='gd-ex-line'>・<span class='gd-jp'>林さんの話では、あの店はおいしいそうです。</span>（照林先生的說法，那家店很好吃）</div><div class='gd-sec'><span class='gd-tag'>跟朋友講</span>把です換成だ就是朋友版：<span class='gd-jp'>明日は休みだそうだ。</span>不過朋友聊天更常說「〜んだって」「〜って」：<span class='gd-jp'>明日、休みなんだって。</span>（聽說明天放假）</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・名詞、な形容詞<b>忘了加だ</b>最常見：要說<span class='gd-jp'>雨だそうです</span>、<span class='gd-jp'>元気だそうです</span>。少了だ，意思會跑掉，或根本不成句（下面會講）。<br>・前面不能放ます形：是<span class='gd-jp'>行くそうです</span>，不是「行きますそうです」。<br>・「聽說<b>以前</b>～」「聽說<b>不</b>～」，過去、否定要放在前面那句，そうです本身不變：<span class='gd-jp'>雨だったそうです</span>（聽說之前下了雨），不能說「雨だそうでした」。<br>・中文「聽說」可以放句首，日文的そうです一定在句尾。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'>上一課的<b>様態そうです</b>（看起來～）也長得一模一樣，差別在<b>前面接什麼</b>：<br><span class='gd-jp'>このかばんは高いそうです。</span>（聽說這個包包很貴：別人告訴我的）<br><span class='gd-jp'>このかばんは高そうです。</span>（這個包包看起來很貴：我自己眼睛看的）<br><br><span class='gd-jp'>雨が降るそうです。</span>（聽說會下雨：看了預報）<br><span class='gd-jp'>雨が降りそうです。</span>（好像快下雨了：看到天空很暗）<br><br><span class='gd-jp'>先生は元気だそうです。</span>（聽說老師很好）<br><span class='gd-jp'>先生は元気そうです。</span>（老師看起來很有精神）<br><br>「いい」比較特別：聽說是<span class='gd-jp'>いいそうです</span>，看起來是<span class='gd-jp'>よさそうです</span>。</div><div class='gd-warn'>判斷小訣竅：そうです前面如果是一句<b>完整的話</b>（高い、降る、元気だ），就是「聽說」；前面是<b>被砍掉一截</b>的樣子（高、降り、元気），就是「看起來」。</div><div class='gd-h'>學會之後可以接著學</div><div class='gd-sec'>另一個也能表示「聽說、好像」的「〜らしいです」，還有直接轉述別人原話的「〜と言っていました」，都可以跟這課一起比較著學。</div>",
  "n4-33": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「〜ようです」「〜みたいです」就是中文的<b>「好像～」「看起來～」</b>。你看到、聽到或感覺到一些線索，自己推測出一個結論。兩個意思一樣，<b>ようです比較正式</b>，<b>みたいです比較口語</b>，平常聊天用みたい最自然。</div><div class='gd-h'>什麼時候用</div><div class='gd-sec'><span class='gd-tag'>根據線索推測</span>最常見的用法。你沒有百分之百確定，但手上有證據。</div><div class='gd-ex-line'>・<span class='gd-jp'>電気が消えていますね。田中さんはもう帰ったようです。</span>（燈關了耶，田中先生好像已經回去了）</div><div class='gd-ex-line'>・<span class='gd-jp'>外がうるさいですね。何かあったみたいです。</span>（外面好吵，好像發生什麼事了）</div><div class='gd-ex-line'>・<span class='gd-jp'>風邪をひいたみたいです。</span>（我好像感冒了）</div><div class='gd-sec'>最後一句是根據自己身體的感覺，例如喉嚨痛、發冷，這種也算線索，所以很常用。</div><div class='gd-sec'><span class='gd-tag'>比喻：像～一樣</span>明知道不是，只是說「很像」。常跟<span class='gd-jp'>まるで</span>（簡直）一起出現。</div><div class='gd-ex-line'>・<span class='gd-jp'>まるで夢のようです。</span>（簡直像在做夢一樣）</div><div class='gd-ex-line'>・<span class='gd-jp'>田中さんは日本語が上手で、日本人みたいです。</span>（田中先生日文好好，像日本人一樣）</div><div class='gd-h'>怎麼接</div><div class='gd-sec'>動詞、い形容詞：直接接，兩個都一樣。<br><span class='gd-pair'><span class='gd-jp'>帰った</span> → <span class='gd-jp'>帰ったようです</span>／<span class='gd-jp'>帰ったみたいです</span></span><br><span class='gd-pair'><span class='gd-jp'>忙しい</span> → <span class='gd-jp'>忙しいようです</span>／<span class='gd-jp'>忙しいみたいです</span></span></div><div class='gd-sec'><b>な形容詞、名詞就不一樣了</b>（現在式的時候）：<br>ようです：な形容詞要加「な」，名詞要加「の」。<br><span class='gd-pair'><span class='gd-jp'>静か</span> → <span class='gd-jp'>静かなようです</span></span><span class='gd-pair'><span class='gd-jp'>学生</span> → <span class='gd-jp'>学生のようです</span></span><br>みたいです：什麼都不用加，直接接。<br><span class='gd-pair'><span class='gd-jp'>静か</span> → <span class='gd-jp'>静かみたいです</span></span><span class='gd-pair'><span class='gd-jp'>学生</span> → <span class='gd-jp'>学生みたいです</span></span><br>過去式兩個都接「だった」：<span class='gd-jp'>学生だったようです</span>／<span class='gd-jp'>学生だったみたいです</span>。</div><div class='gd-h'>最常聽到的樣子</div><div class='gd-sec'><span class='gd-tag'>朋友之間</span>把です拿掉，說「〜みたい」「〜みたいだね」。<span class='gd-jp'>ようだ</span>比較像書面語，聊天很少用。</div><div class='gd-ex-line'>・<span class='gd-jp'>あの店、休みみたい。</span>（那家店好像沒開）</div><div class='gd-sec'><span class='gd-tag'>後面接名詞</span>變成「ような／みたいな」＋名詞，意思是「像～那樣的」。</div><div class='gd-ex-line'>・<span class='gd-jp'>田中さんみたいな人になりたいです。</span>（我想成為像田中先生那樣的人）</div><div class='gd-sec'><span class='gd-tag'>後面接動作</span>變成「ように／みたいに」，意思是「像～一樣地（做）」。</div><div class='gd-ex-line'>・<span class='gd-jp'>子どもみたいに喜んでいます。</span>（像小孩子一樣開心）</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・名詞、な形容詞最容易接錯：是<span class='gd-jp'>学生みたい</span>、<span class='gd-jp'>学生のようです</span>，不是「学生のみたい」；是<span class='gd-jp'>静かみたい</span>，不是「静かなみたい」。<br>・已經親眼確定的事就不要加：你人就在雨中，直接說<span class='gd-jp'>雨が降っています</span>。聽到雨聲、看到窗外有人撐傘，才說<span class='gd-jp'>雨が降っているようです</span>。<br>・<span class='gd-jp'>学生みたい</span>可能是「好像是學生」（推測），也可能是「像學生一樣」（其實不是），要看前後文。<br>・寫報告、正式場合用ようです，みたい太口語。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'>同樣跟下雨有關：<br><b>そうです（様態）</b>＝看外表，<b>快要</b>那樣了：<span class='gd-jp'>雨が降りそうです。</span>（看起來快下雨了：天空烏雲很多，還沒下）<br><b>ようです／みたいです</b>＝根據線索推測<b>已經</b>是那樣：<span class='gd-jp'>雨が降っているみたいです。</span>（好像在下雨：聽到雨聲）<br><b>らしいです</b>＝比較像是<b>聽別人說的</b>：<span class='gd-jp'>東京は雨が降っているらしいです。</span>（聽說東京在下雨：看新聞、聽朋友講的）</div><div class='gd-sec'>形容詞也一樣：<span class='gd-jp'>おいしそう</span>是「看起來很好吃」，光看外表；<span class='gd-jp'>おいしいみたい</span>是「好像很好吃」，例如看到每天都大排長龍。</div><div class='gd-warn'>判斷小訣竅：「光看外表、快要～」用そう；「我有線索，推測好像～」用よう／みたい；「聽人家說～」用らしい。</div><div class='gd-h'>學會之後可以接著學</div><div class='gd-sec'>接著把<span class='gd-jp'>〜らしいです</span>和兩種<span class='gd-jp'>〜そうです</span>（樣子、聽說）一起對照著學，推測的說法就完整了。</div>",
  "n4-34": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「らしい」有兩種意思。第一種是<b>「聽說好像～」</b>，就像你跟朋友說「欸，聽說中村要換工作耶」：消息是從別處聽來的，你自己也沒百分之百確定。第二種是<b>「很有～的樣子」</b>，就像中文說「很有春天的感覺」「很有男子氣概」。</div><div class='gd-h'>什麼時候用</div><div class='gd-sec'><span class='gd-tag'>聽說・好像</span>消息是聽來的、看來的，你根據這些消息覺得「應該是這樣」。</div><div class='gd-ex-line'>・<span class='gd-jp'>中村さんは会社をやめるらしいです。</span>（聽說中村要辭職）</div><div class='gd-ex-line'>・<span class='gd-jp'>あの店のラーメンはおいしいらしいよ。</span>（聽說那家店的拉麵很好吃喔）</div><div class='gd-ex-line'>・<span class='gd-jp'>田中さんは昨日休んだらしいです。</span>（田中昨天好像請假了）</div><div class='gd-sec'><span class='gd-tag'>很有～的樣子</span>前面放名詞，意思是「很符合這個身分、季節應該有的樣子」，通常帶有稱讚的意思。</div><div class='gd-ex-line'>・<span class='gd-jp'>今日は春らしい天気ですね。</span>（今天的天氣很有春天的感覺呢）</div><div class='gd-ex-line'>・<span class='gd-jp'>彼は本当に男らしい人です。</span>（他真的很有男子氣概）</div><div class='gd-sec'>這種「らしい」用起來跟い形容詞（像<span class='gd-jp'>高い</span>這種以い結尾的形容詞）一樣，否定就是<b>らしくない</b>：</div><div class='gd-ex-line'>・<span class='gd-jp'>今日はなんだか田中さんらしくないですね。</span>（今天的田中感覺不太像平常的他耶）</div><div class='gd-h'>怎麼接</div><div class='gd-sec'><b>動詞、い形容詞</b>：用沒有ます的說法，直接接。<br><span class='gd-pair'><span class='gd-jp'>行く</span> → <span class='gd-jp'>行くらしい</span></span><span class='gd-pair'><span class='gd-jp'>行かない</span> → <span class='gd-jp'>行かないらしい</span></span><span class='gd-pair'><span class='gd-jp'>高い</span> → <span class='gd-jp'>高いらしい</span></span></div><div class='gd-sec'><b>な形容詞、名詞</b>：先把「だ」拿掉，再接。<br><span class='gd-pair'><span class='gd-jp'>静かだ</span> → だ拿掉 → <span class='gd-jp'>静からしい</span></span><span class='gd-pair'><span class='gd-jp'>雨だ</span> → <span class='gd-jp'>雨らしい</span></span><br>如果是過去的「だった」，就保留不拿掉：<span class='gd-pair'><span class='gd-jp'>雨だった</span> → <span class='gd-jp'>雨だったらしい</span></span></div><div class='gd-sec'>對長輩或在正式場合，後面加「です」就變成禮貌說法；跟朋友說話只講「らしい」就好。</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・な形容詞和名詞後面不要留「だ」：要說<span class='gd-jp'>静からしい</span>，不能說静かだらしい。<br>・ます形不能直接接らしい：要說<span class='gd-jp'>行くらしいです</span>，不能說行きますらしい。<br>・同一個字可能有兩種意思：<span class='gd-jp'>あの人は学生らしい。</span>可以是「那個人好像是學生」。<span class='gd-jp'>本当に学生らしい服ですね。</span>則是「真的很有學生樣的衣服」。看前後文判斷，前面有「本当に」「とても」這種程度詞，多半是第二種意思。<br>・第二種意思是正面的「符合該有的樣子」。說小孩<span class='gd-jp'>子供らしい</span>是稱讚他天真；想說大人很幼稚，日本人會用<span class='gd-jp'>子供っぽい</span>，不會說子供らしい。<br>・第一種意思用在聽來、沒親自確認的事。自己親眼看到、很確定的事，就直接說，不要加らしい。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'>同樣在講明天的天氣：<br><b>そうです（傳聞）</b>：<span class='gd-jp'>天気予報によると、明日は雨だそうです。</span>（根據氣象預報，明天會下雨）有明確的消息來源，你只是原封不動地轉述。<br><b>らしいです</b>：<span class='gd-jp'>明日は雨らしいです。</span>（明天好像會下雨）一樣是聽來的，但來源比較模糊，像是「大家好像都這麼說」，還多了一點你自己的判斷，口氣比較不確定。<br><b>ようです・みたいです</b>：（看著窗外）<span class='gd-jp'>雨が降っているみたいです。</span>（外面好像在下雨）這是你自己看到、感覺到之後做的判斷。</div><div class='gd-sec'>再看一個很多人會搞混的例子，桌上有一塊蛋糕：<br><span class='gd-jp'>おいしそう！</span>（看起來好好吃！）這是眼睛看到後的感覺，用的是「そうです（樣態）」。<br><span class='gd-jp'>このケーキ、おいしいらしいよ。</span>（聽說這個蛋糕很好吃喔）這是聽別人說的。</div><div class='gd-warn'>判斷小訣竅：消息是「別人說的」，就用らしい或そうです（傳聞）。只想原封不動傳話用そうです，帶一點自己的猜測、來源比較模糊就用らしい。如果是「自己看到、感覺到的」，就用ようです、みたいです或～そう（樣態）。</div><div class='gd-h'>學會之後可以接著學</div><div class='gd-sec'>把n4-32「～そうです（傳聞）」和n4-33「～ようです・～みたいです」一起複習，把「聽來的」和「自己看到的」這兩組分清楚，推測類的句子就不容易用錯。</div>",
  "n4-35": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「〜はずです」就是中文的<b>「照理說應該～」</b>。你手上有根據，例如看過時刻表、聽他說過、知道他是醫生，從這些根據推出一個結論，而且心裡很有把握，就用はず。像「他六點下班，現在<b>應該</b>到家了」裡的那個「應該」。</div><div class='gd-h'>什麼時候用</div><div class='gd-sec'><span class='gd-tag'>有根據的推斷</span>先有一個「因為～」，再推出「所以應該～」。</div><div class='gd-ex-line'>・<span class='gd-jp'>田中さんは6時に会社を出たから、もう家に着いたはずです。</span>（田中先生六點就離開公司了，現在應該到家了）</div><div class='gd-ex-line'>・<span class='gd-jp'>木村さんは医者だから、薬に詳しいはずです。</span>（木村先生是醫生，應該很懂藥）</div><div class='gd-sec'><span class='gd-tag'>難怪</span>看到原因以後恍然大悟，常用「〜はずだ」。</div><div class='gd-ex-line'>・<span class='gd-jp'>窓が開いている。寒いはずだ。</span>（窗戶開著，難怪這麼冷）</div><div class='gd-h'>怎麼接</div><div class='gd-sec'>接法跟後面接名詞的時候一樣：<br><b>動詞</b>：普通形（也就是不加ます的形）直接接。<br><span class='gd-pair'><span class='gd-jp'>行く</span> → <span class='gd-jp'>行くはず</span></span><span class='gd-pair'><span class='gd-jp'>行かない</span> → <span class='gd-jp'>行かないはず</span></span><span class='gd-pair'><span class='gd-jp'>行った</span> → <span class='gd-jp'>行ったはず</span></span><br><b>い形容詞</b>：直接接。<span class='gd-pair'><span class='gd-jp'>高い</span> → <span class='gd-jp'>高いはず</span></span><br><b>な形容詞</b>：加「な」。<span class='gd-pair'><span class='gd-jp'>静か</span> → <span class='gd-jp'>静かなはず</span></span><br><b>名詞</b>：加「の」。<span class='gd-pair'><span class='gd-jp'>休み</span> → <span class='gd-jp'>休みのはず</span></span><br>如果要講過去，な形容詞和名詞就用「だった」：<span class='gd-jp'>学生だったはず</span>。<br>對朋友說「はずだ」，對老師、客人說「はずです」。</div><div class='gd-h'>最常聽到的樣子</div><div class='gd-sec'><span class='gd-tag'>はずがない</span>不可能～，語氣很強的否定。</div><div class='gd-ex-line'>・<span class='gd-jp'>あの人がうそをつくはずがありません。</span>（那個人不可能說謊）</div><div class='gd-sec'><span class='gd-tag'>はずだった</span>本來應該～，結果沒有。</div><div class='gd-ex-line'>・<span class='gd-jp'>電車は10時に着くはずだったのに、30分も遅れた。</span>（電車本來應該十點到，結果晚了三十分鐘）</div><div class='gd-sec'><span class='gd-tag'>はずなのに</span>明明應該～，怎麼會這樣。</div><div class='gd-ex-line'>・<span class='gd-jp'>鍵はかばんに入れたはずなのに、ない。</span>（我明明把鑰匙放進包包了，卻找不到）</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・中文的「應該」有兩種意思：「他應該到了」是推測，「你應該早點睡」是勸人。<b>はず只有推測這一種</b>。要勸人，就用<span class='gd-jp'>早く寝たほうがいいですよ</span>。如果說成<span class='gd-jp'>早く寝るはずです</span>，意思會變成「照理說你會早睡」。<br>・名詞要加の，な形容詞要加な：要說<span class='gd-jp'>休みのはず</span>、<span class='gd-jp'>静かなはず</span>，不能說「休みはず」「学生だはず」。<br>・自己決定要做的事不要用はず。中文常說「我明天應該會去」，日文要說<span class='gd-jp'>明日は行くつもりです</span>或<span class='gd-jp'>行くと思います</span>。說<span class='gd-jp'>行くはずです</span>的話，聽起來像「照安排好的行程，我會去」。<br>・<span class='gd-jp'>来ないはずです</span>是「應該不會來」，屬於推測；<span class='gd-jp'>来るはずがありません</span>是「不可能來」，語氣強很多。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'>同樣在等田中先生：<br><span class='gd-jp'>田中さんは来るはずです。</span>（他說好要來，照理說會來：有根據，很有把握）<br><span class='gd-jp'>田中さんは来るでしょう。</span>（他大概會來吧：一般的猜測）<br><span class='gd-jp'>田中さんは来るかもしれません。</span>（他可能會來，也可能不會：差不多一半一半）</div><div class='gd-warn'>判斷小訣竅：講得出「因為～所以」的根據，而且很有把握，用はず；只是隨口猜，用でしょう；沒什麼把握，用かもしれません。</div><div class='gd-h'>學會之後可以接著學</div><div class='gd-sec'>到了 N3 會學「べき」（應該去做～），剛好就是中文「應該」的另一種意思。把はず和べき分開記，就不會再混在一起。</div>",
  "n4-54": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>ば形就是中文的<b>「只要～就～」</b>。<span class='gd-jp'>安ければ買います</span>＝只要便宜我就買。它的重點放在前面那個<b>條件</b>：條件成立，後面的結果就跟著來。</div><div class='gd-h'>什麼時候用</div><div class='gd-sec'><span class='gd-tag'>只要～就～</span>說某個條件一成立，就會有什麼結果。</div><div class='gd-ex-line'>・<span class='gd-jp'>安ければ買います。</span>（便宜的話就買）</div><div class='gd-ex-line'>・<span class='gd-jp'>急げば間に合いますよ。</span>（快一點的話還來得及喔）</div><div class='gd-sec'><span class='gd-tag'>不變的道理</span>大自然、常識這種「每次都會這樣」的事。</div><div class='gd-ex-line'>・<span class='gd-jp'>春になれば、桜が咲きます。</span>（到了春天，櫻花就會開）</div><div class='gd-sec'><span class='gd-tag'>不～的話</span>否定的版本，常用來提醒「沒做就糟了」。</div><div class='gd-ex-line'>・<span class='gd-jp'>急がなければ、間に合いません。</span>（不快一點的話會來不及）</div><div class='gd-h'>怎麼變：先看動詞是哪一類</div><div class='gd-sec'><b>第一類（五段動詞）</b>：最後一個音換成同一行的「え」段音，再加「ば」。<br><span class='gd-pair'><span class='gd-jp'>行く</span> → く換成け → <span class='gd-jp'>行けば</span></span><br><span class='gd-pair'><span class='gd-jp'>飲む</span> → <span class='gd-jp'>飲めば</span></span><span class='gd-pair'><span class='gd-jp'>買う</span> → <span class='gd-jp'>買えば</span></span><span class='gd-pair'><span class='gd-jp'>待つ</span> → <span class='gd-jp'>待てば</span></span><span class='gd-pair'><span class='gd-jp'>帰る</span> → <span class='gd-jp'>帰れば</span></span></div><div class='gd-sec'><b>第二類（一段動詞）</b>：把最後的「る」拿掉，加「れば」。<br><span class='gd-pair'><span class='gd-jp'>食べる</span> → <span class='gd-jp'>食べれば</span></span><span class='gd-pair'><span class='gd-jp'>起きる</span> → <span class='gd-jp'>起きれば</span></span><span class='gd-pair'><span class='gd-jp'>見る</span> → <span class='gd-jp'>見れば</span></span></div><div class='gd-sec'><b>第三類（只有兩個，直接背）</b>：<span class='gd-pair'><span class='gd-jp'>する</span> → <span class='gd-jp'>すれば</span></span><span class='gd-pair'><span class='gd-jp'>来る</span> → <span class='gd-jp'>来れば</span>（くれば）</span></div><div class='gd-sec'><b>「不～的話」</b>：先變成ない形，再把「ない」的「い」拿掉，加「ければ」。<br><span class='gd-pair'><span class='gd-jp'>行かない</span> → <span class='gd-jp'>行かなければ</span></span><span class='gd-pair'><span class='gd-jp'>食べない</span> → <span class='gd-jp'>食べなければ</span></span></div><div class='gd-sec'><b>い形容詞</b>：把最後的「い」拿掉，加「ければ」。<br><span class='gd-pair'><span class='gd-jp'>安い</span> → <span class='gd-jp'>安ければ</span></span><span class='gd-pair'><span class='gd-jp'>寒い</span> → <span class='gd-jp'>寒ければ</span></span><br><b>な形容詞・名詞</b>：不用ば，直接加「なら」。<br><span class='gd-pair'><span class='gd-jp'>静か</span> → <span class='gd-jp'>静かなら</span></span><span class='gd-pair'><span class='gd-jp'>学生</span> → <span class='gd-jp'>学生なら</span></span></div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・<span class='gd-jp'>来れば</span>念<b>くれば</b>，不是きれば，也不是これば。<br>・<span class='gd-jp'>いい</span>要變成<span class='gd-jp'>よければ</span>，沒有「いければ」。例：<span class='gd-jp'>よければ、どうぞ。</span>（不嫌棄的話請用）<br>・第一類不是加れば：是<span class='gd-jp'>行けば</span>，不是行くれば。<br>・前面是一個<b>動作</b>（去、到、吃…），後面又要說「請～」「～吧」的時候，用ば會很怪，要換成たら：<br>×駅に着けば、電話してください。<br>○<span class='gd-jp'>駅に着いたら、電話してください。</span>（到車站之後打給我）<br>前面如果是<b>狀態</b>（ある、いる、できる、形容詞）就沒問題：<span class='gd-jp'>時間があれば、来てください。</span>（有時間的話請過來）</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'>日文的「如果」有四種，用同一個情境「去車站」來比：<br><b>ば</b>＝只要～就～：<span class='gd-jp'>駅まで歩けば、10分で着きます。</span>（走路去車站的話，10 分鐘就到）<br><b>たら</b>＝～之後，後面可以接請求、揪人：<span class='gd-jp'>駅に着いたら、電話してください。</span>（到車站之後打給我）<br><b>と</b>＝一～就一定會，像指路、機器反應：<span class='gd-jp'>この道をまっすぐ行くと、駅があります。</span>（這條路直走就會看到車站）<br><b>なら</b>＝接對方說的話給建議，事情還沒發生：<span class='gd-jp'>駅に行くなら、この道が近いですよ。</span>（你要去車站的話，走這條比較近喔）</div><div class='gd-warn'>判斷小訣竅：「只要～就」用ば；「～之後」或後面要請人、揪人用たら；「一～就一定會」用と；「你說要～的話」用なら。拿不準的時候先用たら，最不容易錯。</div><div class='gd-h'>學會之後可以接著學</div><div class='gd-sec'>後面加「いい」＝「～就好」，問別人意見超常用：<span class='gd-jp'>どうすればいいですか。</span>（該怎麼做才好？）<br>「なければ」再加「なりません」就是「非～不可」：<span class='gd-jp'>明日は早く起きなければなりません。</span>（明天非早起不可）</div>",
  "n4-55": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「〜たら」就是中文的<b>「～的話」「等～了，就～」</b>。講「有錢的話想去旅行」「回到家就打給你」都用它，是日常講條件最常用的說法。它還有一個特別用法：<b>「一～，結果發現～」</b>。</div><div class='gd-h'>怎麼接：會た形就會たら</div><div class='gd-sec'>先把た形做出來，後面加「ら」就好。動詞的た形變法跟て形一樣，只是把て換成た、で換成だ。<br><span class='gd-pair'><span class='gd-jp'>行く</span> → <span class='gd-jp'>行った</span> → <span class='gd-jp'>行ったら</span></span><br><span class='gd-pair'><span class='gd-jp'>飲む</span> → <span class='gd-jp'>飲んだ</span> → <span class='gd-jp'>飲んだら</span></span><br><span class='gd-pair'><span class='gd-jp'>食べる</span> → <span class='gd-jp'>食べた</span> → <span class='gd-jp'>食べたら</span></span><br><span class='gd-pair'><span class='gd-jp'>する</span> → <span class='gd-jp'>したら</span></span><span class='gd-pair'><span class='gd-jp'>来る</span> → <span class='gd-jp'>来たら</span>（きたら）</span></div><div class='gd-sec'>形容詞、名詞也可以，一樣是先變成過去的樣子再加ら：<br><span class='gd-pair'><span class='gd-jp'>高い</span> → <span class='gd-jp'>高かったら</span></span><span class='gd-pair'><span class='gd-jp'>暇</span> → <span class='gd-jp'>暇だったら</span></span><span class='gd-pair'><span class='gd-jp'>雨</span> → <span class='gd-jp'>雨だったら</span></span><br>否定也一樣：<span class='gd-pair'><span class='gd-jp'>行かない</span> → <span class='gd-jp'>行かなかったら</span></span>（不去的話）</div><div class='gd-h'>什麼時候用</div><div class='gd-sec'><span class='gd-tag'>如果～的話</span>不一定會發生，只是假設。</div><div class='gd-ex-line'>・<span class='gd-jp'>お金があったら、旅行したい。</span>（有錢的話想去旅行）</div><div class='gd-ex-line'>・<span class='gd-jp'>明日雨だったら、行きません。</span>（明天下雨的話就不去）</div><div class='gd-sec'><span class='gd-tag'>等～之後就</span>一定會發生的事，講「到時候」要做什麼。</div><div class='gd-ex-line'>・<span class='gd-jp'>家に帰ったら、電話します。</span>（回到家就打給你）</div><div class='gd-ex-line'>・<span class='gd-jp'>駅に着いたら、連絡してください。</span>（到車站了請跟我聯絡）</div><div class='gd-sec'><span class='gd-tag'>結果發現</span>做了某件事之後，發現了意料外的事。這時候後面要用<b>過去式</b>。</div><div class='gd-ex-line'>・<span class='gd-jp'>窓を開けたら、猫がいた。</span>（一打開窗，發現有隻貓）</div><div class='gd-ex-line'>・<span class='gd-jp'>家に帰ったら、母が来ていました。</span>（回到家，發現我媽來了）</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・たら一定是<b>前面先發生，後面才發生</b>。<span class='gd-jp'>日本へ行ったら、ガイドブックを買います。</span>是「到了日本才買」。如果你想說「出發前先買」，要用なら（下面會講）。<br>・<span class='gd-jp'>来たら</span>念<b>きたら</b>，不是こたら。<br>・講自己過去做的一連串事情，不要用たら。「回家後吃了飯」是<span class='gd-jp'>家に帰って、ご飯を食べました。</span>「たら＋過去式」是專門講「結果碰到、發現了什麼」的，後面放自己刻意做的動作會很怪。<br>・想加中文的「如果」，前面可以放<span class='gd-jp'>もし</span>：<span class='gd-jp'>もし雨だったら</span>。但「等～之後」那種一定會發生的事不能加もし，<span class='gd-jp'>もし家に帰ったら</span>聽起來像不確定自己回不回得了家。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'>N4 會學到四種條件：たら、ば、と、なら。同一個情境放在一起看：<br><b>たら</b>＝最萬用，後面可以接請求、希望、打算：<span class='gd-jp'>春になったら、日本へ行きたい。</span>（到了春天想去日本）<br><b>と</b>＝每次都一定這樣，像自然現象：<span class='gd-jp'>春になると、桜が咲きます。</span>（一到春天櫻花就會開）<br><b>ば</b>＝強調「只要有這個條件就～」：<span class='gd-jp'>春になれば、暖かくなります。</span>（只要到了春天就會變暖）<br><b>なら</b>＝接在對方說的話後面給建議，而且<b>可以先講後面的事</b>：<span class='gd-jp'>日本へ行くなら、春がいいですよ。</span>（你要去日本的話，春天比較好喔）</div><div class='gd-sec'>差別最明顯的是「請對方做事」：<span class='gd-jp'>駅に着いたら、電話してください。</span>很自然；換成と或ば說成「駅に着くと」「駅に着けば」再接「電話してください」，日本人聽起來會覺得不對。</div><div class='gd-warn'>判斷小訣竅：拿不定主意時先用たら，大多數情況都通。例外是「每次都這樣」比較常用と；「聽到對方要做某事，先給建議」要用なら。</div><div class='gd-h'>學會之後可以接著學</div><div class='gd-sec'>後面加「いいです」就變成給建議：<span class='gd-jp'>先生に聞いたらいいですよ。</span>（去問老師就好啦）</div>",
  "n4-56": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「なら」就是中文的<b>「～的話」</b>。朋友說「我想去泡溫泉」，你順著他的話接「溫泉的話，箱根不錯喔」。先接住對方提的事，再給出你的建議或想法，這就是なら最常見的用法。</div><div class='gd-h'>什麼時候用</div><div class='gd-sec'><span class='gd-tag'>接話給建議</span>對方提到一件事，你針對那件事給意見。</div><div class='gd-ex-line'>・<span class='gd-jp'>A：週末、温泉に行きたいな。</span>（週末好想去泡溫泉）</div><div class='gd-ex-line'>・<span class='gd-jp'>B：温泉なら、箱根がいいよ。</span>（溫泉的話，箱根不錯喔）</div><div class='gd-sec'><span class='gd-tag'>先假設，再說打算</span>「如果是這樣的話，我就～」。</div><div class='gd-ex-line'>・<span class='gd-jp'>あなたが行くなら、私も行きます。</span>（你去的話，我也去）</div><div class='gd-ex-line'>・<span class='gd-jp'>家賃が予算内なら、契約したいです。</span>（房租在預算內的話，我想簽約）</div><div class='gd-h'>怎麼接</div><div class='gd-sec'><b>動詞</b>：用普通形（沒有ます的說法）直接接。<br><span class='gd-pair'><span class='gd-jp'>行く</span> → <span class='gd-jp'>行くなら</span></span><span class='gd-pair'><span class='gd-jp'>行かない</span> → <span class='gd-jp'>行かないなら</span></span><br><b>い形容詞</b>：直接接。<span class='gd-pair'><span class='gd-jp'>高い</span> → <span class='gd-jp'>高いなら</span></span><br><b>な形容詞</b>：把「だ」拿掉再接。<span class='gd-pair'><span class='gd-jp'>静かだ</span> → <span class='gd-jp'>静かなら</span></span><br><b>名詞</b>：直接接。<span class='gd-pair'><span class='gd-jp'>日本語</span> → <span class='gd-jp'>日本語なら</span></span></div><div class='gd-h'>最常聽到的樣子</div><div class='gd-sec'><span class='gd-tag'>名詞＋なら</span>意思是「說到～的話」，把話題縮小到這一樣東西。</div><div class='gd-ex-line'>・<span class='gd-jp'>コーヒーなら、駅前の店がおいしいですよ。</span>（說到咖啡，車站前那家很好喝喔）</div><div class='gd-sec'><span class='gd-tag'>それなら</span>放在句子開頭，意思是「那這樣的話」，口語常常只講「なら」。</div><div class='gd-ex-line'>・<span class='gd-jp'>A：明日は忙しいです。</span>（我明天很忙）</div><div class='gd-ex-line'>・<span class='gd-jp'>B：それなら、あさってにしましょう。</span>（那這樣的話，改後天吧）</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・名詞和な形容詞<b>不要加だ</b>：要說<span class='gd-jp'>学生なら</span>，不是学生だなら。<br>・なら後面那件事，<b>可以比前面那件事先做</b>：<span class='gd-jp'>京都へ行くなら、ホテルを早く予約したほうがいいですよ。</span>（要去京都的話，最好早點訂飯店）訂飯店是出發前的事。這跟たら剛好相反。<br>・なら後面多半接建議、請求、自己的打算或判斷。「春天一到，花就開」這種一定會發生的事，不用なら，要用と：<span class='gd-jp'>春になると、桜が咲きます。</span>（一到春天，櫻花就會開）</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'>なら和たら都可以翻成「～的話」，最容易混。差別在<b>後面那件事是什麼時候做</b>。同樣是去日本：<br><b>なら</b>＝去之前就要做：</div><div class='gd-ex-line'>・<span class='gd-jp'>日本へ行くなら、日本語を勉強しておいたほうがいいよ。</span>（要去日本的話，先學點日文比較好）</div><div class='gd-sec'><b>たら</b>＝到了之後才做：</div><div class='gd-ex-line'>・<span class='gd-jp'>日本へ行ったら、ラーメンを食べたい。</span>（到了日本，我想吃拉麵）</div><div class='gd-sec'>如果第一句換成「行ったら」，意思就變成「到了日本才開始學日文」，跟你想講的不一樣。反過來，「到車站後打給我」一定是到了才打，要用たら：<span class='gd-jp'>駅に着いたら、電話してください。</span>（到車站後請打電話給我）</div><div class='gd-warn'>判斷小訣竅：「還沒做、先給建議」用なら，「做完、到了之後才發生」用たら。對方剛提到一件事，你接著給意見，幾乎都是なら。</div><div class='gd-h'>學會之後可以接著學</div><div class='gd-sec'>日文的「如果」有四種：と、ば、たら、なら。學完なら，可以把<span class='gd-jp'>〜ば</span>（n4-54）和<span class='gd-jp'>〜と</span>（n4-57）拿來一起比，看看各自什麼時候用。</div>",
  "n4-59": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>受身形就是中文的<b>「被～」</b>：<span class='gd-jp'>先生に褒められた</span>是「被老師稱讚了」。不過日文的被動用得比中文多，還常常帶一種<b>「我被弄得很倒楣、很困擾」</b>的感覺，像中文說「被他這樣一搞，我很頭痛」。</div><div class='gd-h'>怎麼變：先看動詞是哪一類</div><div class='gd-sec'><b>第一類（五段動詞）</b>：最後一個音換成同一行的「あ」段音，再加「れる」。<br><span class='gd-pair'><span class='gd-jp'>書く</span> → く換成か → <span class='gd-jp'>書かれる</span></span><br><span class='gd-pair'><span class='gd-jp'>踏む</span> → <span class='gd-jp'>踏まれる</span></span><span class='gd-pair'><span class='gd-jp'>叱る</span> → <span class='gd-jp'>叱られる</span></span><br>「う」結尾的要特別注意，う不是換成あ，是換成<b>わ</b>：<br><span class='gd-pair'><span class='gd-jp'>言う</span> → う換成わ → <span class='gd-jp'>言われる</span></span><span class='gd-pair'><span class='gd-jp'>誘う</span> → <span class='gd-jp'>誘われる</span></span><br>從ます形想也可以：<span class='gd-jp'>書きます</span>的「き」換成「か」，再加「れます」→<span class='gd-jp'>書かれます</span>。</div><div class='gd-sec'><b>第二類（一段動詞）</b>：把最後的「る」拿掉，加「られる」。<br><span class='gd-pair'><span class='gd-jp'>食べる</span> → <span class='gd-jp'>食べられる</span></span><span class='gd-pair'><span class='gd-jp'>見る</span> → <span class='gd-jp'>見られる</span></span></div><div class='gd-sec'><b>第三類（只有兩個，直接背）</b>：<span class='gd-pair'><span class='gd-jp'>する</span> → <span class='gd-jp'>される</span></span><span class='gd-pair'><span class='gd-jp'>来る</span> → <span class='gd-jp'>来られる</span>（こられる）</span></div><div class='gd-sec'>變好之後的「〜れる／〜られる」，就當成第二類動詞繼續變：<span class='gd-jp'>叱られます</span>、<span class='gd-jp'>叱られた</span>、<span class='gd-jp'>叱られて</span>。</div><div class='gd-h'>三種最常見的被動</div><div class='gd-sec'>不管哪一種，<b>做動作的人後面都用「に」</b>。</div><div class='gd-sec'><span class='gd-tag'>我被做了什麼</span>（私は）人に＋被動。跟中文的「被」最像，好事壞事都可以用。<br><span class='gd-jp'>先生が私を褒めた。</span>（老師稱讚了我）→ 換成被動：</div><div class='gd-ex-line'>・<span class='gd-jp'>私は先生に褒められた。</span>（我被老師稱讚了）</div><div class='gd-ex-line'>・<span class='gd-jp'>母に叱られました。</span>（我被媽媽罵了）</div><div class='gd-sec'><span class='gd-tag'>我的東西被弄了</span>（私は）人に＋東西を＋被動。日文習慣把「受害的人」當主角，東西用「を」。</div><div class='gd-ex-line'>・<span class='gd-jp'>電車で足を踏まれた。</span>（在電車上被踩到腳）</div><div class='gd-ex-line'>・<span class='gd-jp'>弟にケーキを食べられた。</span>（蛋糕被弟弟吃掉了）</div><div class='gd-sec'><span class='gd-tag'>被弄得很困擾</span>別人做的事本來跟你無關，但你因此受害。連「下雨」「哭」這種動作也能變被動，中文通常不會翻成「被」。</div><div class='gd-ex-line'>・<span class='gd-jp'>雨に降られて、びしょびしょになった。</span>（碰上下雨，全身濕透了）</div><div class='gd-ex-line'>・<span class='gd-jp'>夜中に子供に泣かれて、寝られなかった。</span>（半夜小孩一直哭，害我睡不著）</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・<span class='gd-jp'>言う</span>的被動是<span class='gd-jp'>言われる</span>，不是「言あれる」也不是「言られる」。<span class='gd-jp'>買う</span>、<span class='gd-jp'>使う</span>也一樣是わ。<br>・做動作的人用「に」：是<span class='gd-jp'>先生に褒められた</span>，不是「先生が褒められた」，那樣會變成「老師被稱讚了」。<br>・中文講「我的腳被踩了」，日文不要直翻成「私の足が踏まれた」，自然的說法是<span class='gd-jp'>足を踏まれた</span>。<br>・中文的「被」大多是壞事，日文被動好事也能用：<span class='gd-jp'>褒められた</span>（被稱讚）、<span class='gd-jp'>誘われた</span>（被邀約）都很常見。<br>・看到被動句，先想「主角是不是受影響、甚至受害的一方」，那股語感就抓得到。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'><b>受身形 vs 可能形</b>：第二類動詞和来る，兩種形長得一模一樣。<br><span class='gd-jp'>犬にパンを食べられた。</span>（麵包被狗吃掉了：被動）<br><span class='gd-jp'>このパンはまだ食べられる。</span>（這個麵包還能吃：可能）<br>前面有「人に」、句子在講誰被怎樣，就是被動；在講「能不能」，就是可能形。</div><div class='gd-sec'><b>〜られる vs 〜てもらう</b>：同樣是別人來找你。<br><span class='gd-jp'>友達に来られて困った。</span>（朋友跑來，我很困擾）<br><span class='gd-jp'>友達に来てもらって助かった。</span>（朋友來幫忙，真是幫了大忙）<br>被動常帶「被打擾」的感覺；てもらう是「承蒙對方幫我」，帶感謝。</div><div class='gd-warn'>判斷小訣竅：心裡想的是「被～、倒楣」用〜れる／〜られる；想的是「人家幫我，真好」用〜てもらう。</div><div class='gd-h'>學會之後可以接著學</div><div class='gd-sec'>使役形（叫別人做）：<span class='gd-jp'>書かせる</span>；再往上是使役受身（被逼著做）：<span class='gd-jp'>母に野菜を食べさせられた。</span>（被媽媽逼著吃青菜）。另外，同樣是〜れる／〜られる，也可以用來對長輩表示尊敬，例如<span class='gd-jp'>先生が書かれた本</span>（老師寫的書），之後學尊敬形時會再碰到。</div>",
  "n4-60": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>使役形就是中文的<b>「叫～做」「讓～做」</b>。像是「媽媽叫小孩吃青菜」「店長讓工讀生先下班」，日文都是把動詞變成「〜せる／〜させる」。它可以是<b>硬叫對方做（強迫）</b>，也可以是<b>對方想做、你同意他做（允許）</b>，要看前後文判斷。</div><div class='gd-h'>什麼時候用</div><div class='gd-sec'><span class='gd-tag'>強迫</span>不管對方想不想，叫他去做。</div><div class='gd-ex-line'>・<span class='gd-jp'>母は子供に野菜を食べさせます。</span>（媽媽叫小孩吃青菜）</div><div class='gd-sec'><span class='gd-tag'>允許</span>對方想做，你讓他做。</div><div class='gd-ex-line'>・<span class='gd-jp'>子供が遊びたがっていたので、公園で遊ばせました。</span>（小孩很想玩，我就讓他在公園玩）</div><div class='gd-sec'><span class='gd-tag'>讓人有某種心情</span>害別人擔心、讓別人開心，也用使役形。</div><div class='gd-ex-line'>・<span class='gd-jp'>親を心配させたくない。</span>（我不想讓爸媽擔心）</div><div class='gd-h'>怎麼變：先看動詞是哪一類</div><div class='gd-sec'><b>第一類（五段動詞）</b>：最後一個音換成同一行的「あ」段音，再加「せる」。<br><span class='gd-pair'><span class='gd-jp'>書く</span> → く換成か → <span class='gd-jp'>書かせる</span></span><br><span class='gd-pair'><span class='gd-jp'>飲む</span> → <span class='gd-jp'>飲ませる</span></span><span class='gd-pair'><span class='gd-jp'>帰る</span> → <span class='gd-jp'>帰らせる</span></span><span class='gd-pair'><span class='gd-jp'>待つ</span> → <span class='gd-jp'>待たせる</span></span><br>「う」結尾的要換成<b>わ</b>：<span class='gd-pair'><span class='gd-jp'>買う</span> → <span class='gd-jp'>買わせる</span></span><br>小技巧：跟ない形用的是同一個音。<span class='gd-jp'>書かない</span>把ない拿掉，加せる，就是<span class='gd-jp'>書かせる</span>。</div><div class='gd-sec'><b>第二類（一段動詞）</b>：把最後的「る」拿掉，加「させる」。<br><span class='gd-pair'><span class='gd-jp'>食べる</span> → <span class='gd-jp'>食べさせる</span></span><span class='gd-pair'><span class='gd-jp'>見る</span> → <span class='gd-jp'>見させる</span></span><span class='gd-pair'><span class='gd-jp'>起きる</span> → <span class='gd-jp'>起きさせる</span></span></div><div class='gd-sec'><b>第三類（只有兩個，直接背）</b>：<span class='gd-pair'><span class='gd-jp'>する</span> → <span class='gd-jp'>させる</span></span><span class='gd-pair'><span class='gd-jp'>来る</span> → <span class='gd-jp'>来させる</span>（こさせる）</span><br><span class='gd-jp'>勉強する</span>、<span class='gd-jp'>残業する</span>這種也一樣：<span class='gd-pair'><span class='gd-jp'>勉強する</span> → <span class='gd-jp'>勉強させる</span></span></div><div class='gd-sec'>變好之後，它就是一個普通的第二類動詞，可以照常變：<span class='gd-jp'>書かせます</span>、<span class='gd-jp'>書かせた</span>、<span class='gd-jp'>書かせない</span>。</div><div class='gd-h'>被叫的人用に還是を</div><div class='gd-sec'>句子長這樣：<b>叫人的人</b>は　<b>做事的人</b>に／を　〜させる<br>判斷方法：先看句子裡<b>有沒有別的「を」</b>（吃什麼、寫什麼）。</div><div class='gd-sec'><span class='gd-tag'>有別的を</span>做事的人只能用<b>に</b>。日文一句話裡不喜歡出現兩個「を」。</div><div class='gd-ex-line'>・<span class='gd-jp'>先生は生徒に作文を書かせます。</span>（老師叫學生寫作文）</div><div class='gd-ex-line'>・<span class='gd-jp'>子供に日本語を勉強させています。</span>（我讓小孩學日文）</div><div class='gd-sec'><span class='gd-tag'>沒有別的を</span>用<b>を</b>或<b>に</b>都可以。用を的時候，強迫的感覺比較明顯。</div><div class='gd-ex-line'>・<span class='gd-jp'>先生は学生を立たせました。</span>（老師叫學生站起來）</div><div class='gd-ex-line'>・<span class='gd-jp'>部長は毎日私を残業させます。</span>（部長每天叫我加班）</div><div class='gd-ex-line'>・<span class='gd-jp'>部長は毎日私に残業させます。</span>（部長每天叫我加班）</div><div class='gd-h'>最常聽到的樣子</div><div class='gd-sec'><span class='gd-tag'>させてください</span>「請讓我～」，自己想做，請對方同意。</div><div class='gd-ex-line'>・<span class='gd-jp'>少し休ませてください。</span>（請讓我休息一下）</div><div class='gd-ex-line'>・<span class='gd-jp'>私にやらせてください。</span>（讓我來做吧）</div><div class='gd-sec'><span class='gd-tag'>待たせる</span>「讓人等」，道歉時超常用。</div><div class='gd-ex-line'>・<span class='gd-jp'>お待たせしました。</span>（讓您久等了）</div><div class='gd-ex-line'>・<span class='gd-jp'>待たせてごめんね。</span>（抱歉讓你等了）</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・「う」結尾變<b>わ</b>：是<span class='gd-jp'>買わせる</span>、<span class='gd-jp'>言わせる</span>，不是「買あせる」。<br>・<span class='gd-jp'>帰る</span>、<span class='gd-jp'>入る</span>、<span class='gd-jp'>走る</span>是第一類：是<span class='gd-jp'>帰らせる</span>，不是「帰させる」。<br>・<span class='gd-jp'>来させる</span>念<b>こさせる</b>，不是きさせる。<br>・使役形是上對下的說法，<b>不能拿來叫長輩</b>。「我請老師說明」說成<span class='gd-jp'>先生に説明させる</span>會很失禮，要說<span class='gd-jp'>先生に説明してもらう</span>（更客氣是<span class='gd-jp'>説明していただく</span>）。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'><b>させる vs てもらう</b>：中文都可能說「讓朋友幫我拍照」，日文差很多。<br><span class='gd-jp'>友達に写真を撮らせた。</span>（我叫朋友拍照：聽起來像在使喚人）<br><span class='gd-jp'>友達に写真を撮ってもらった。</span>（我請朋友幫我拍照：對方幫忙，帶感謝）</div><div class='gd-sec'><b>させる vs される（被動）</b>：一個字之差，方向完全相反。<br><span class='gd-jp'>友達を1時間待たせた。</span>（我讓朋友等了一小時：是我害的）<br><span class='gd-jp'>友達に1時間待たされた。</span>（我被朋友害得等了一小時：我是吃虧的）</div><div class='gd-warn'>判斷小訣竅：看到「<b>せ</b>」是我叫別人做；看到「<b>れ</b>」是我被別人怎樣；想拜託人幫忙，用「てもらう」。</div><div class='gd-h'>學會之後可以接著學</div><div class='gd-sec'>使役＋被動＝被逼著做（使役受身形）：<span class='gd-jp'>母に野菜を食べさせられた。</span>（我被媽媽逼著吃青菜）<br>還有服務業很常聽到的<span class='gd-jp'>〜させていただきます</span>，也是從使役形來的。</div>",
  "n4-61": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>使役受身形就是中文的<b>「被逼著～」「被叫去～」</b>。重點是：<b>動作是你自己做的，但你不想做</b>，是別人逼你的。像「小時候被媽媽逼著吃青椒」，吃的是你，逼的是媽媽，語氣裡帶著一點抱怨。</div><div class='gd-h'>它是怎麼來的</div><div class='gd-sec'>名字很長，其實是兩個東西疊起來：<b>使役</b>（叫別人做某事）＋<b>受身</b>（被～）。<br>先看媽媽的角度：</div><div class='gd-ex-line'>・<span class='gd-jp'>母は私にピーマンを食べさせた。</span>（媽媽叫我吃青椒）</div><div class='gd-sec'>換成從「我」的角度講，就變成使役受身：</div><div class='gd-ex-line'>・<span class='gd-jp'>私は母にピーマンを食べさせられた。</span>（我被媽媽逼著吃青椒）</div><div class='gd-sec'>被逼的人（我）用<span class='gd-jp'>は</span>或<span class='gd-jp'>が</span>，逼你的人用<b><span class='gd-jp'>に</span></b>。</div><div class='gd-h'>怎麼變：先看動詞是哪一類</div><div class='gd-sec'><b>第二類（一段動詞）</b>：把「る」拿掉，加「させられる」。<br><span class='gd-pair'><span class='gd-jp'>食べる</span> → <span class='gd-jp'>食べさせられる</span></span><span class='gd-pair'><span class='gd-jp'>見る</span> → <span class='gd-jp'>見させられる</span></span></div><div class='gd-sec'><b>第一類（五段動詞）</b>：最後一個音換成同一行的「あ」段音，再加「される」。這是日本人最常講的版本。<br><span class='gd-pair'><span class='gd-jp'>行く</span> → く換成か → <span class='gd-jp'>行かされる</span></span><br><span class='gd-pair'><span class='gd-jp'>飲む</span> → <span class='gd-jp'>飲まされる</span></span><span class='gd-pair'><span class='gd-jp'>待つ</span> → <span class='gd-jp'>待たされる</span></span><span class='gd-pair'><span class='gd-jp'>買う</span> → う換成わ → <span class='gd-jp'>買わされる</span></span><br>加「せられる」也對（<span class='gd-jp'>行かせられる</span>），只是比較長、比較少聽到。</div><div class='gd-sec'><b>第三類（只有兩個，直接背）</b>：<span class='gd-pair'><span class='gd-jp'>する</span> → <span class='gd-jp'>させられる</span></span><span class='gd-pair'><span class='gd-jp'>来る</span> → <span class='gd-jp'>来させられる</span>（こさせられる）</span></div><div class='gd-sec'>禮貌講法把最後的る換成ます：<span class='gd-pair'><span class='gd-jp'>待たされる</span> → <span class='gd-jp'>待たされます</span></span></div><div class='gd-h'>最常聽到的樣子</div><div class='gd-ex-line'>・<span class='gd-jp'>駅で30分も待たされた。</span>（在車站被迫等了 30 分鐘）</div><div class='gd-ex-line'>・<span class='gd-jp'>部長にお酒を飲まされました。</span>（被部長灌酒）</div><div class='gd-ex-line'>・<span class='gd-jp'>子供の頃、毎日ピアノを練習させられた。</span>（小時候每天被逼著練鋼琴）</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・「す」結尾的第一類動詞<b>不能</b>用される：<span class='gd-jp'>話す</span>要變<span class='gd-jp'>話させられる</span>，不是話さされる。<br>・「う」結尾的換成「わ」不是「あ」：<span class='gd-jp'>買わされる</span>，不是買あされる。<br>・<span class='gd-jp'>来る</span>的使役受身念<b>こさせられる</b>，不是きさせられる。<br>・<span class='gd-jp'>食べさせる</span>是「叫別人吃」，<span class='gd-jp'>食べさせられる</span>是「自己被逼著吃」，少了「られる」意思整個反過來。<br>・它帶著「不情願」的感覺，開心的事不要用。學長請你吃飯要說<span class='gd-jp'>先輩におごってもらった</span>；如果說<span class='gd-jp'>先輩におごらされた</span>，意思會變成「被學長逼著請客」。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'><b>受身形</b>＝動作是<b>對方</b>做的，你是被做的那個：<span class='gd-jp'>先生に叱られた。</span>（被老師罵：罵的人是老師）<br><b>使役受身形</b>＝動作是<b>你自己</b>做的，只是被逼：<span class='gd-jp'>先生に立たされた。</span>（被老師罰站：站的人是我）<br><b>てもらう</b>＝對方幫你做，你很感謝：<span class='gd-jp'>先生に作文を直してもらった。</span>（老師幫我改了作文）</div><div class='gd-warn'>判斷小訣竅：問自己「是誰在做這個動作？」對方做在你身上是受身；你自己不甘願地做是使役受身；對方幫你、你很感謝就用てもらう。</div><div class='gd-h'>學會之後可以接著學</div><div class='gd-sec'>想要禮貌地說「請讓我～」，用使役形的て形接<span class='gd-jp'>いただきます</span>（<span class='gd-jp'>〜させていただきます</span>）：<span class='gd-jp'>発表する</span> → <span class='gd-jp'>発表させる</span> → <span class='gd-jp'>発表させていただきます。</span>（請容我來報告）</div>",
  "n4-62": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>尊敬語就是講到<b>對方或長輩、上司在做的事</b>時，把動作換成比較恭敬的說法。像中文把「你吃了嗎」說成「您用過餐了嗎」，把「老師來了」說成「老師蒞臨」：動作沒變，只是用字更尊敬。</div><div class='gd-h'>什麼時候用</div><div class='gd-sec'>做這個動作的人是老師、主管、客人、長輩這些你要尊敬的人。當面跟他講、或在別人面前提到他，都可以用。</div><div class='gd-ex-line'>・<span class='gd-jp'>先生はもうお帰りになりました。</span>（老師已經回去了）</div><div class='gd-ex-line'>・<span class='gd-jp'>週末は何をなさいますか。</span>（您週末要做什麼呢？）</div><div class='gd-h'>怎麼變：分兩步想</div><div class='gd-sec'><b>第一步：先想這個動詞有沒有「專屬的尊敬說法」</b><br>很常用的動詞有自己的尊敬說法，有的話通常優先用它：<br><span class='gd-pair'><span class='gd-jp'>いる・行く・来る</span> → <span class='gd-jp'>いらっしゃる</span></span><br><span class='gd-pair'><span class='gd-jp'>言う</span> → <span class='gd-jp'>おっしゃる</span></span><br><span class='gd-pair'><span class='gd-jp'>食べる・飲む</span> → <span class='gd-jp'>召し上がる</span></span><br><span class='gd-pair'><span class='gd-jp'>見る</span> → <span class='gd-jp'>ご覧になる</span></span><br><span class='gd-pair'><span class='gd-jp'>する</span> → <span class='gd-jp'>なさる</span></span><br><span class='gd-pair'><span class='gd-jp'>くれる</span> → <span class='gd-jp'>くださる</span></span><br><span class='gd-pair'><span class='gd-jp'>知っている</span> → <span class='gd-jp'>ご存じだ</span></span></div><div class='gd-ex-line'>・<span class='gd-jp'>社長は明日大阪へいらっしゃいます。</span>（社長明天要去大阪）</div><div class='gd-ex-line'>・<span class='gd-jp'>この本、もうご覧になりましたか。</span>（這本書您看過了嗎？）</div><div class='gd-sec'><b>第二步：沒有專屬說法，就套「お＋ます形＋になる」</b><br>先變成ます形，把ます拿掉，前面加お、後面加になる。<br><span class='gd-pair'><span class='gd-jp'>待つ</span> → <span class='gd-jp'>待ちます</span> → 把ます拿掉 → <span class='gd-jp'>お待ちになる</span></span><br><span class='gd-pair'><span class='gd-jp'>帰る</span> → <span class='gd-jp'>お帰りになる</span></span><span class='gd-pair'><span class='gd-jp'>書く</span> → <span class='gd-jp'>お書きになる</span></span><br>「漢字詞＋する」的動詞，常用ご：<span class='gd-pair'><span class='gd-jp'>利用する</span> → <span class='gd-jp'>ご利用になる</span></span></div><div class='gd-ex-line'>・<span class='gd-jp'>部長は何時にお戻りになりますか。</span>（部長幾點回來呢？）</div><div class='gd-sec'><b>見る・言う・する・いる・来る</b>這類一定要用專屬說法，不能硬套公式。至於<span class='gd-jp'>飲む</span>等少數動詞，兩種都對：<span class='gd-jp'>何を召し上がりますか。</span>、<span class='gd-jp'>何をお飲みになりますか。</span>（您要喝什麼？）都很自然。</div><div class='gd-sec'>另外還有一種比較輕的尊敬說法「れる・られる」（例：<span class='gd-jp'>社長が帰られました</span>），會在 n4-74 另外講。</div><div class='gd-h'>最常聽到的樣子</div><div class='gd-sec'><span class='gd-tag'>店裡</span><span class='gd-jp'>いらっしゃいませ。</span>（歡迎光臨）其實就是いらっしゃる變來的。<br><span class='gd-tag'>請您～</span>お＋ます形＋ください：<span class='gd-jp'>少々お待ちください。</span>（請您稍等）<br><span class='gd-tag'>問對方知不知道</span><span class='gd-jp'>このお店、ご存じですか。</span>（您知道這家店嗎？）</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・尊敬語<b>絕對不能用在自己身上</b>。說「我明天去」不能講<span class='gd-jp'>私がいらっしゃいます</span>，要用一般說法或謙讓語：<span class='gd-jp'>私が参ります</span>。<br>・下面這些動詞不能硬套公式：不說お見になる、お言いになる、おしになる，要說<span class='gd-jp'>ご覧になる</span>、<span class='gd-jp'>おっしゃる</span>、<span class='gd-jp'>なさる</span>。<br>・ます形很容易寫錯：是<span class='gd-jp'>いらっしゃいます</span>、<span class='gd-jp'>おっしゃいます</span>、<span class='gd-jp'>なさいます</span>、<span class='gd-jp'>くださいます</span>，不是いらっしゃります、おっしゃります。<br>・在公司跟外面的客人講到自己的主管，不用尊敬語，要把自己公司的人放低說。例如客人打電話找部長，要回<span class='gd-jp'>田中は今おりません。</span>，不說「部長はいらっしゃいません」。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'>謙讓語（n4-63）也是敬語，但方向相反：尊敬語是<b>把對方抬高</b>，謙讓語是<b>把自己放低</b>。同一段對話看：<br><span class='gd-jp'>A：この資料、ご覧になりましたか。</span>（這份資料您看過了嗎？：對方看，用尊敬語）<br><span class='gd-jp'>B：はい、拝見しました。</span>（是的，我看過了：自己看，用謙讓語）<br><span class='gd-jp'>A：何を召し上がりますか。</span>（您要吃什麼？）<br><span class='gd-jp'>B：じゃ、ケーキをいただきます。</span>（那我吃蛋糕）</div><div class='gd-warn'>判斷小訣竅：先看<b>誰在做這個動作</b>。是對方或長輩上司做 → 尊敬語；是我自己（或我這邊的人）做 → 謙讓語。</div><div class='gd-h'>學會之後可以接著學</div><div class='gd-sec'>接著學謙讓語（n4-63），兩個一起記最不會搞混；再看「れる・られる」的尊敬用法（n4-74）。</div>",
  "n4-63": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>謙譲語就是<b>把自己的動作講得低一點，對方自然就顯得高</b>。中文其實也有：介紹自己說「敝姓林」，看對方的文章說「拜讀」，去對方家說「登門拜訪」。日文的謙譲語就是這個概念，只是用得比中文多很多。</div><div class='gd-h'>什麼時候用</div><div class='gd-sec'>對客人、老師、主管這些要尊敬的人，講<b>自己要做的事</b>時用。打工、上班、寫信給老師，幾乎天天會碰到。</div><div class='gd-h'>做法一：お＋動詞＋します</div><div class='gd-sec'>把ます形的「ます」拿掉，前面加「お」，後面加「します」。<br><span class='gd-pair'><span class='gd-jp'>持ちます</span> → 把ます拿掉 → <span class='gd-jp'>お持ちします</span></span><br><span class='gd-pair'><span class='gd-jp'>待ちます</span> → <span class='gd-jp'>お待ちします</span></span><br><span class='gd-pair'><span class='gd-jp'>送ります</span> → <span class='gd-jp'>お送りします</span></span><br>「案内」「連絡」這種漢字詞，前面通常加「ご」：<br><span class='gd-pair'><span class='gd-jp'>案内します</span> → <span class='gd-jp'>ご案内します</span></span><br><span class='gd-pair'><span class='gd-jp'>連絡します</span> → <span class='gd-jp'>ご連絡します</span></span></div><div class='gd-ex-line'>・<span class='gd-jp'>荷物、お持ちします。</span>（行李我來幫您拿）</div><div class='gd-ex-line'>・<span class='gd-jp'>駅までお送りします。</span>（我送您到車站）</div><div class='gd-ex-line'>・<span class='gd-jp'>あとでご連絡します。</span>（我晚點再跟您聯絡）</div><div class='gd-sec'>這招只能用在<b>為對方做、或跟對方有關</b>的動作。自己吃飯、自己睡覺跟對方沒關係，就不能這樣套。</div><div class='gd-h'>做法二：直接換成特別的動詞</div><div class='gd-sec'>有些常用動詞有自己專屬的謙虛版本，<b>整個換掉</b>，不用お～します。N4 先把這幾個背起來：<br><span class='gd-pair'><span class='gd-jp'>行く・来る</span> → <span class='gd-jp'>参ります</span></span><br><span class='gd-pair'><span class='gd-jp'>いる</span> → <span class='gd-jp'>おります</span></span><br><span class='gd-pair'><span class='gd-jp'>言う</span> → <span class='gd-jp'>申します</span></span><br><span class='gd-pair'><span class='gd-jp'>する</span> → <span class='gd-jp'>いたします</span></span><br><span class='gd-pair'><span class='gd-jp'>食べる・飲む・もらう</span> → <span class='gd-jp'>いただきます</span></span><br><span class='gd-pair'><span class='gd-jp'>見る</span> → <span class='gd-jp'>拝見します</span></span><br><span class='gd-pair'>請問、去對方那裡拜訪 → <span class='gd-jp'>伺います</span></span><br><span class='gd-pair'><span class='gd-jp'>知っている</span> → <span class='gd-jp'>存じております</span></span><br><span class='gd-pair'><span class='gd-jp'>会う</span> → <span class='gd-jp'>お目にかかります</span></span><br>吃飯前說的「いただきます」，其實就是這個謙虛的いただく。</div><div class='gd-ex-line'>・<span class='gd-jp'>はじめまして、林と申します。</span>（初次見面，我姓林）</div><div class='gd-ex-line'>・<span class='gd-jp'>資料、拝見しました。</span>（資料我看過了）</div><div class='gd-ex-line'>・<span class='gd-jp'>では、お先に失礼いたします。</span>（那我先告辭了）</div><div class='gd-sec'>對外人講到<b>自己家人</b>的動作也用謙譲語，因為家人算「自己這一邊」。</div><div class='gd-ex-line'>・<span class='gd-jp'>父は今、出かけております。</span>（我爸爸現在出門了）</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・謙譲語只能用在<b>自己（和自己這一邊）</b>。請老師吃東西說<span class='gd-jp'>いただいてください</span>是錯的，要說<span class='gd-jp'>召し上がってください</span>；問老師去不去，不能說<span class='gd-jp'>先生も参りますか</span>，要說<span class='gd-jp'>先生もいらっしゃいますか</span>。<br>・有專屬版本的動詞，就用專屬版本：不說お見します，要說<span class='gd-jp'>拝見します</span>；不說お行きします，要說<span class='gd-jp'>参ります</span>或<span class='gd-jp'>伺います</span>。<br>・<span class='gd-jp'>お待ちします</span>是「我等您」，<span class='gd-jp'>お待ちください</span>是「請您等」，主角不同。店員說<span class='gd-jp'>少々お待ちください</span>是請你等，說<span class='gd-jp'>お待ちしております</span>是他們在等你。<br>・<span class='gd-jp'>参ります</span>只是把「去、來」講客氣；<span class='gd-jp'>伺います</span>是「去對方那裡」。<span class='gd-jp'>来週、大阪へ参ります。</span>（下週我要去大阪）／<span class='gd-jp'>明日、先生のお宅に伺います。</span>（明天我去老師家拜訪）</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'>最容易混的是<b>尊敬語</b>。同一件事，主角是對方就用尊敬語（把對方抬高），主角是自己就用謙譲語（把自己壓低）。</div><div class='gd-ex-line'>・<span class='gd-jp'>先生も召し上がりますか。</span>（老師也要吃嗎：對方吃，尊敬語）</div><div class='gd-ex-line'>・<span class='gd-jp'>はい、私もいただきます。</span>（好，我也吃：自己吃，謙譲語）</div><div class='gd-ex-line'>・<span class='gd-jp'>先生、傘をお持ちになりましたか。</span>（老師，您有帶傘嗎：對方帶）</div><div class='gd-ex-line'>・<span class='gd-jp'>傘、お持ちします。</span>（傘我來幫您拿：自己拿）</div><div class='gd-warn'>判斷小訣竅：先問「這個動作是誰做的？」對方做 → 尊敬語（お～になる、いらっしゃる、召し上がる）；自己做 → 謙譲語（お～します、参ります、いただきます）。</div><div class='gd-h'>學會之後可以接著學</div><div class='gd-sec'>接著學「〜させていただきます」，這是很謙虛地說「我要做～」的說法（字面上是「承蒙您讓我做～」），例如<span class='gd-jp'>本日は休ませていただきます。</span>（今天請容我休息）打工、上班時天天都會聽到。</div>",
  "n4-7": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「ので」就是<b>「因為～，所以～」</b>，跟「から」一樣是在講理由。差別是「ので」聽起來比較<b>客氣、像在說明狀況</b>。中文的「因為～啊」比較像から，「由於～的關係」比較像ので。對老師、主管、客人講理由，用ので最不會出錯。</div><div class='gd-h'>什麼時候用</div><div class='gd-sec'><span class='gd-tag'>客氣地交代理由</span>上班、上課、跟不熟的人講話時最常用。</div><div class='gd-ex-line'>・<span class='gd-jp'>用事があるので、お先に失礼します。</span>（因為有事，我先走了）</div><div class='gd-ex-line'>・<span class='gd-jp'>道が混んでいたので、遅れました。</span>（因為路上塞車，所以遲到了）</div><div class='gd-sec'><span class='gd-tag'>拜託別人</span>先講理由，再請對方幫忙，聽起來很有禮貌。</div><div class='gd-ex-line'>・<span class='gd-jp'>寒いので、窓を閉めてください。</span>（因為很冷，請把窗戶關起來）</div><div class='gd-sec'><span class='gd-tag'>委婉拒絕</span>日本人常常只講理由，後面不講完，對方就懂了。</div><div class='gd-ex-line'>・<span class='gd-jp'>明日はちょっと用事があるので…。</span>（明天有點事…）</div><div class='gd-h'>怎麼接</div><div class='gd-sec'><b>動詞、い形容詞</b>：直接接。<br><span class='gd-pair'><span class='gd-jp'>行く</span> → <span class='gd-jp'>行くので</span></span><span class='gd-pair'><span class='gd-jp'>行った</span> → <span class='gd-jp'>行ったので</span></span><span class='gd-pair'><span class='gd-jp'>痛い</span> → <span class='gd-jp'>痛いので</span></span></div><div class='gd-sec'><b>な形容詞、名詞</b>：中間要加「な」。<br><span class='gd-pair'><span class='gd-jp'>静か</span> → <span class='gd-jp'>静かなので</span></span><span class='gd-pair'><span class='gd-jp'>雨</span> → <span class='gd-jp'>雨なので</span></span><br>講過去的事就用「だった」：<span class='gd-pair'><span class='gd-jp'>雨</span> → <span class='gd-jp'>雨だったので</span></span></div><div class='gd-sec'>想更正式，也可以接在ます、です後面，店家、職場很常聽到：<br><span class='gd-jp'>雨が降っていますので、お気をつけください。</span>（因為在下雨，請小心）</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・名詞、な形容詞不能直接加だ：<span class='gd-jp'>雨だので</span>是錯的，要說<span class='gd-jp'>雨なので</span>。<br>・い形容詞反過來，<b>不用加な</b>：是<span class='gd-jp'>痛いので</span>，不是痛いなので。<br>・回答「為什麼？」時，句尾可以說<span class='gd-jp'>電車が遅れたからです</span>，但<b>不能</b>說遅れたのでです。<br>・ので不適合接很兇的命令，像「うるさいので、黙れ」就很怪，這種要用から。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'><b>から vs ので</b>：同樣是發燒要請假。<br><span class='gd-jp'>熱があるから、休む。</span>（我發燒，所以要休息：跟朋友講，比較直接）<br><span class='gd-jp'>熱があるので、休ませてください。</span>（因為發燒，請讓我休息：跟主管講，比較客氣）<br>罵人、警告時只能用から：<span class='gd-jp'>危ないから、触るな！</span>（很危險，不要碰！）</div><div class='gd-sec'><b>ので vs のに</b>：只差一個字，意思差很多。<br><span class='gd-jp'>薬を飲んだので、治った。</span>（因為吃了藥，所以好了）<br><span class='gd-jp'>薬を飲んだのに、治らない。</span>（明明吃了藥，卻沒好）</div><div class='gd-warn'>判斷小訣竅：講理由、想客氣就用ので；想強調、很衝、在命令人就用から；「明明～卻～」是のに。</div><div class='gd-h'>學會之後可以接著學</div><div class='gd-sec'>理由不只一個時，可以用「し」一個一個列出來：<span class='gd-jp'>雨も降っているし、寒いし、今日は出かけない。</span>（又下雨又冷，今天不出門了）</div>",
  "n4-5": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「〜やすい」就是中文的<b>「好～」「容易～」</b>，「〜にくい」就是<b>「不好～」「很難～」</b>。這支筆好寫、這個名字很難記，日文都用它們來說。</div><div class='gd-h'>怎麼接</div><div class='gd-sec'>先把動詞變成ます形，把「ます」拿掉，後面加やすい或にくい。<br><span class='gd-pair'><span class='gd-jp'>書く</span> → <span class='gd-jp'>書きます</span> → 把ます拿掉 → <span class='gd-jp'>書きやすい</span></span><br><span class='gd-pair'><span class='gd-jp'>食べる</span> → <span class='gd-jp'>食べます</span> → <span class='gd-jp'>食べにくい</span></span><br><span class='gd-pair'><span class='gd-jp'>話す</span> → <span class='gd-jp'>話しやすい</span></span><span class='gd-pair'><span class='gd-jp'>覚える</span> → <span class='gd-jp'>覚えにくい</span></span><span class='gd-pair'><span class='gd-jp'>する</span> → <span class='gd-jp'>しやすい</span></span><span class='gd-pair'><span class='gd-jp'>来る</span> → <span class='gd-jp'>来やすい</span>（きやすい）</span></div><div class='gd-sec'>接好之後，整個詞就<b>當成い形容詞用</b>，跟「おいしい」的變法一樣：<br><span class='gd-pair'><span class='gd-jp'>書きやすい</span> → <span class='gd-jp'>書きやすかった</span></span>（以前覺得好寫）<br><span class='gd-pair'><span class='gd-jp'>わかりやすい</span> → <span class='gd-jp'>わかりやすくて</span></span>（好懂，而且…）<br>也可以直接放在名詞前面：<span class='gd-jp'>使いやすいアプリ</span>（好用的 App）</div><div class='gd-h'>什麼時候用</div><div class='gd-sec'><span class='gd-tag'>做起來輕鬆／費力</span>人去做這件事時，順不順手。</div><div class='gd-ex-line'>・<span class='gd-jp'>この靴は軽くて歩きやすいです。</span>（這雙鞋很輕，很好走）</div><div class='gd-ex-line'>・<span class='gd-jp'>先生の説明はわかりやすいです。</span>（老師的說明很好懂）</div><div class='gd-ex-line'>・<span class='gd-jp'>この魚は骨が多くて食べにくいです。</span>（這條魚刺很多，吃起來很麻煩）</div><div class='gd-sec'><span class='gd-tag'>容易／不容易發生</span>不是人刻意去做，而是東西或人<b>本來就容易變成那樣</b>。</div><div class='gd-ex-line'>・<span class='gd-jp'>白い服は汚れやすいです。</span>（白色的衣服很容易髒）</div><div class='gd-ex-line'>・<span class='gd-jp'>冬は風邪をひきやすいです。</span>（冬天容易感冒）</div><div class='gd-ex-line'>・<span class='gd-jp'>このコップは割れにくいです。</span>（這個杯子不容易破）</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・要接<b>ます形拿掉ます</b>，不是接原形：是<span class='gd-jp'>書きやすい</span>，不是書くやすい。<br>・<span class='gd-jp'>食べやすい</span>不是「好吃」！它是「好入口、吃起來方便」。要說好吃請用<span class='gd-jp'>おいしい</span>。同樣，<span class='gd-jp'>食べにくい</span>是「不好吃下去、吃起來麻煩」，不是「難吃」（難吃是<span class='gd-jp'>まずい</span>）。<br>・想說「不好寫」，日本人通常直接說<span class='gd-jp'>書きにくい</span>，比<span class='gd-jp'>書きやすくない</span>自然。<br>・<span class='gd-jp'>割れやすい</span>是「容易破」，在講東西的性質，不是「很好打破」。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'>「〜そうです」（看起來好像會～）也接ます形拿掉ます，跟やすい很容易混：<br><b>割れそう</b>＝看了外表<b>當下猜</b>它會破：<span class='gd-jp'>このお皿、薄くて割れそう。</span>（這盤子好薄，看起來好像會破）<br><b>割れやすい</b>＝本來就知道它<b>容易破</b>，是它的特性：<span class='gd-jp'>このお皿は割れやすいから、気をつけて。</span>（這盤子很容易破，小心一點）</div><div class='gd-warn'>判斷小訣竅：「看起來好像會～」用そう；「本來就容易～、做起來好～」用やすい。</div><div class='gd-h'>學會之後可以接著學</div><div class='gd-sec'>同樣是「ます形拿掉ます」再加東西的，還有<span class='gd-jp'>食べすぎる</span>（吃太多）、<span class='gd-jp'>書き方</span>（寫法）。接法學會一次，這幾個一起通。</div>",
  "n4-10": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「〜たことがあります」就是中文的<b>「～過」</b>，講你這輩子<b>有沒有這個經驗</b>。「我去過日本」就是<span class='gd-jp'>日本へ行ったことがあります。</span>，「我沒吃過香菜」就是<span class='gd-jp'>パクチーを食べたことがありません。</span></div><div class='gd-h'>怎麼接</div><div class='gd-sec'>動詞先變成<b>た形</b>（常體的過去式，「吃了」「去了」的那個形），後面接<span class='gd-jp'>ことがあります</span>。<br>た形的變法跟て形一樣，只是把て換成た、で換成だ：<br><b>第一類（五段動詞）</b>：<span class='gd-pair'><span class='gd-jp'>行く</span> → <span class='gd-jp'>行った</span></span><span class='gd-pair'><span class='gd-jp'>書く</span> → <span class='gd-jp'>書いた</span></span><span class='gd-pair'><span class='gd-jp'>飲む</span> → <span class='gd-jp'>飲んだ</span></span><span class='gd-pair'><span class='gd-jp'>乗る</span> → <span class='gd-jp'>乗った</span></span><br><b>第二類（一段動詞）</b>：把「る」拿掉，加た。<span class='gd-pair'><span class='gd-jp'>食べる</span> → <span class='gd-jp'>食べた</span></span><span class='gd-pair'><span class='gd-jp'>見る</span> → <span class='gd-jp'>見た</span></span><br><b>第三類（只有兩個，直接背）</b>：<span class='gd-pair'><span class='gd-jp'>する</span> → <span class='gd-jp'>した</span></span><span class='gd-pair'><span class='gd-jp'>来る</span> → <span class='gd-jp'>来た</span>（きた）</span><br>然後整組接上去：<span class='gd-pair'><span class='gd-jp'>食べた</span> → <span class='gd-jp'>食べたことがあります</span></span></div><div class='gd-h'>最常聽到的樣子</div><div class='gd-sec'><span class='gd-tag'>有過</span>講自己的經驗。前面可以加次數。</div><div class='gd-ex-line'>・<span class='gd-jp'>着物を着たことがあります。</span>（我穿過和服）</div><div class='gd-ex-line'>・<span class='gd-jp'>大阪には二回行ったことがあります。</span>（大阪我去過兩次）</div><div class='gd-sec'><span class='gd-tag'>沒有過</span>把あります換成<b>ありません</b>。加「一度も」就是「一次也沒有」。</div><div class='gd-ex-line'>・<span class='gd-jp'>一度も雪を見たことがありません。</span>（我一次也沒看過雪）</div><div class='gd-sec'><span class='gd-tag'>問人家</span>句尾加か。回答不用整句重講，用あります／ありません就好。</div><div class='gd-ex-line'>・<span class='gd-jp'>馬に乗ったことがありますか。</span>（你騎過馬嗎？）</div><div class='gd-ex-line'>・<span class='gd-jp'>はい、あります。</span>／<span class='gd-jp'>いいえ、ありません。</span>（有／沒有）</div><div class='gd-sec'><span class='gd-tag'>朋友版</span>跟朋友講就用<span class='gd-jp'>ことがある</span>／<span class='gd-jp'>ことがない</span>，口語常把が省掉。</div><div class='gd-ex-line'>・<span class='gd-jp'>富士山、登ったことある？</span>（你爬過富士山嗎？）</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・它講的是「人生中有沒有這個經驗」，<b>剛剛、昨天這種最近的事不能用</b>：<span class='gd-jp'>さっき食べたことがある</span>是錯的，直接說<span class='gd-jp'>さっき食べた</span>。像「小時候」這種很久以前、範圍很大的時間就可以：<span class='gd-jp'>子どものころ、日本に住んだことがあります。</span>（我小時候在日本住過）<br>・<b>每個人都一定做過的事不要用</b>：「我吃過飯」講成<span class='gd-jp'>ご飯を食べたことがあります</span>，日本人會覺得很怪，好像吃飯是什麼稀奇的體驗。<br>・「沒做過」是<span class='gd-jp'>食べたことがありません</span>，不是<span class='gd-jp'>食べなかったことがあります</span>，後者變成「有過一次沒吃的經驗」。<br>・前面一定要是<b>た形</b>。換成辭書形意思就整個變了，看下面。<br>・<span class='gd-jp'>来たことがあります</span>的来念<b>き</b>，不是く也不是こ。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'><b>た形＋ことがあります</b>＝曾經～過（經驗）<br><span class='gd-jp'>納豆を食べたことがあります。</span>（我吃過納豆）<br><b>辭書形＋ことがあります</b>＝有時候會～（偶爾發生）<br><span class='gd-jp'>納豆を食べることがあります。</span>（我有時候會吃納豆）</div><div class='gd-sec'>另外，中文的「過」也可以是「已經做完了」，這時候日文<b>不用</b>ことがある：<br><span class='gd-jp'>もう食べましたか。</span>（你吃過了沒？＝吃了嗎）<br><span class='gd-jp'>食べたことがありますか。</span>（你有沒有吃過？＝有這個經驗嗎）</div><div class='gd-warn'>判斷小訣竅：中文能改成「有沒有～過」就用たことがある；意思是「已經～了沒」就用<span class='gd-jp'>もう〜ました</span>；前面是辭書形就是「有時候會」。</div><div class='gd-h'>學會之後可以接著學</div><div class='gd-sec'>跟「〜てみたい」（想試試看）一起用，自我介紹、聊天超好用：<br><span class='gd-jp'>温泉に入ったことがないので、一度入ってみたいです。</span>（我沒泡過溫泉，想去泡一次看看）</div>",
  "n4-45": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「〜んです」很像中文的<b>「是因為～啦」「其實是這樣的～」「是怎麼了嗎？」</b>。句子的意思沒變，只是多了一層感覺：<b>我在跟你交代背景</b>，或<b>我看到某個狀況，想知道是怎麼回事</b>。日本人講話超常用，口語幾乎都說「んです」，「のです」是寫文章、演講才用的版本。</div><div class='gd-h'>什麼時候用</div><div class='gd-sec'><span class='gd-tag'>解釋理由</span>別人問你為什麼，或你覺得該交代一下原因的時候。</div><div class='gd-ex-line'>・<span class='gd-jp'>どうして昨日休んだんですか。</span>（你昨天為什麼請假？）</div><div class='gd-ex-line'>・<span class='gd-jp'>熱があったんです。</span>（因為我發燒了）</div><div class='gd-sec'><span class='gd-tag'>看到狀況想問</span>眼前看到一個情況，想知道背後是怎麼回事。</div><div class='gd-ex-line'>・<span class='gd-jp'>どうしたんですか。</span>（怎麼了？）</div><div class='gd-ex-line'>・<span class='gd-jp'>雨が降っているんですか。</span>（外面在下雨嗎？看到對方拿著濕傘進來）</div><div class='gd-sec'><span class='gd-tag'>開口前先鋪陳</span>用「〜んですが」「〜んですけど」先把狀況講出來，再拜託或發問，是很道地的開場。</div><div class='gd-ex-line'>・<span class='gd-jp'>すみません、駅に行きたいんですが…。</span>（不好意思，我想去車站…）</div><div class='gd-sec'><span class='gd-tag'>說出消息、心情</span>主動告訴對方一件事，或強調自己的感受。</div><div class='gd-ex-line'>・<span class='gd-jp'>実は来月結婚するんです。</span>（其實我下個月要結婚了）</div><div class='gd-ex-line'>・<span class='gd-jp'>本当に困っているんです。</span>（我真的很困擾）</div><div class='gd-h'>怎麼接</div><div class='gd-sec'><b>動詞、い形容詞</b>：普通形（就是沒有ます、です的說法）直接加んです。<br><span class='gd-pair'><span class='gd-jp'>行く</span> → <span class='gd-jp'>行くんです</span></span><span class='gd-pair'><span class='gd-jp'>行かない</span> → <span class='gd-jp'>行かないんです</span></span><span class='gd-pair'><span class='gd-jp'>行った</span> → <span class='gd-jp'>行ったんです</span></span><span class='gd-pair'><span class='gd-jp'>高い</span> → <span class='gd-jp'>高いんです</span></span></div><div class='gd-sec'><b>な形容詞、名詞</b>：現在肯定的時候，中間要加<b>な</b>。<br><span class='gd-pair'><span class='gd-jp'>好き</span> → <span class='gd-jp'>好きなんです</span></span><span class='gd-pair'><span class='gd-jp'>学生</span> → <span class='gd-jp'>学生なんです</span></span><br>過去或否定就照普通形接，不用加な：<span class='gd-pair'><span class='gd-jp'>学生だった</span> → <span class='gd-jp'>学生だったんです</span></span><span class='gd-pair'><span class='gd-jp'>好きじゃない</span> → <span class='gd-jp'>好きじゃないんです</span></span></div><div class='gd-sec'>跟朋友講話時，說明用「〜んだ」或「〜の」，問句用「〜の？」：<span class='gd-jp'>どうしたの？</span>（怎麼了？）</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・な形容詞、名詞忘了加な：不是学生んです，也不是学生だんです，是<span class='gd-jp'>学生なんです</span>。<br>・不能接在ます、です後面：不是行きますんです、高いですんです，是<span class='gd-jp'>行くんです</span>、<span class='gd-jp'>高いんです</span>。<br>・不要每句都加。單純講事實用ます就好，句句都んです，聽起來像一直在解釋、找理由。<br>・「〜んですか」問別人的行為時，語調和場合不對，可能聽起來像在追究、質問。例如<span class='gd-jp'>何をしているんですか</span>口氣一兇，就變成「你在幹嘛！」；<span class='gd-jp'>どうして遅れたんですか</span>也可能像在興師問罪。問長輩時語氣要放軟，可以先說<span class='gd-jp'>あのう</span>。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'>同一個情境：同事明天的行程。<br><b>〜ますか</b>＝單純問，手上沒有任何線索：<br><span class='gd-jp'>明日、どこかへ行きますか。</span>（你明天有要去哪裡嗎？）<br><b>〜んですか</b>＝看到同事拖著行李箱，想知道是怎麼回事：<br><span class='gd-jp'>どこかへ行くんですか。</span>（你是要去哪裡嗎？）<br>回答也一樣，要交代原因就用んです：<span class='gd-jp'>大阪に出張なんです。</span>（我要去大阪出差）</div><div class='gd-warn'>判斷小訣竅：有看到什麼、想知道背後的原因，用んですか；只是單純問一件事，用ますか。</div><div class='gd-h'>學會之後可以接著學</div><div class='gd-sec'>「〜んですが」後面接拜託的說法，就是很有禮貌的請求：<span class='gd-jp'>日本語がよくわからないんですが、ゆっくり話していただけませんか。</span>（我日文不太好，可以請您講慢一點嗎？）</div>",
  "n4-47": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>兩個都在講「決定」，差在<b>是誰拍板的</b>。<br><b>ことにする</b>＝「我決定～」，自己做主。<br><b>ことになる</b>＝「結果變成要～了」，可能是公司、學校安排的，也可能是事情自己發展成這樣。像中文說「我決定搬家」和「我被調去台中了」的差別。</div><div class='gd-h'>怎麼接</div><div class='gd-sec'>要做的事：辭書形＋ことにする／ことになる<br><span class='gd-pair'><span class='gd-jp'>行く</span> → <span class='gd-jp'>行くことにする</span></span><br>不做的事：ない形＋ことにする／ことになる<br><span class='gd-pair'><span class='gd-jp'>行かない</span> → <span class='gd-jp'>行かないことにする</span></span><br>決定通常是已經做好的，所以最常用過去式：<b>ことにした</b>、<b>ことになった</b>。</div><div class='gd-h'>最常聽到的四種樣子</div><div class='gd-sec'><span class='gd-tag'>ことにした</span>自己剛下的決定。</div><div class='gd-ex-line'>・<span class='gd-jp'>来年、日本に留学することにしました。</span>（我決定明年去日本留學）</div><div class='gd-ex-line'>・<span class='gd-jp'>今日はどこにも行かないことにした。</span>（我決定今天哪裡都不去）</div><div class='gd-sec'><span class='gd-tag'>ことになった</span>別人決定的，或事情自然變成這樣。</div><div class='gd-ex-line'>・<span class='gd-jp'>来月から大阪に転勤することになりました。</span>（下個月起我要調去大阪了）</div><div class='gd-ex-line'>・<span class='gd-jp'>6月に結婚することになりました。</span>（我六月要結婚了）</div><div class='gd-sec'>結婚明明是自己決定的，為什麼用なる？因為用なる聽起來像「事情走到這一步」，比較<b>低調、客氣</b>，日本人跟同事、主管報告時很常這樣講。</div><div class='gd-sec'><span class='gd-tag'>ことにしている</span>自己給自己定的規矩，一直有在遵守。</div><div class='gd-ex-line'>・<span class='gd-jp'>寝る前はスマホを見ないことにしている。</span>（我規定自己睡前不滑手機）</div><div class='gd-sec'><span class='gd-tag'>ことになっている</span>團體的規定或慣例，不是你自己定的。</div><div class='gd-ex-line'>・<span class='gd-jp'>この寮では、10時までに帰ることになっている。</span>（這間宿舍規定 10 點前要回來）</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・名詞後面直接接にする，不用加こと：點餐說<span class='gd-jp'>コーヒーにします</span>（我要咖啡）；動詞才要先加こと再接にする：<span class='gd-jp'>コーヒーをやめることにします</span>（我決定戒咖啡）。<br>・助詞是<b>に</b>，不是を：<span class='gd-jp'>行くことにした</span>，不是「行くことをした」。<br>・跟別人說自己要離職，<span class='gd-jp'>辞めることにしました</span>聽起來是「我自己決定的」，態度很明確；<span class='gd-jp'>辞めることになりました</span>比較委婉，不會那麼直接。<br>・ことにしている是「自己定的」，ことになっている是「規定本來就這樣」，別把宿舍規定說成ことにしている。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'>同樣講「每天走路」：<br><b>ことにする</b>＝下決定的那一刻：<span class='gd-jp'>毎日歩くことにした。</span>（我決定每天走路）<br><b>ようにする</b>＝盡量做到、有在努力：<span class='gd-jp'>毎日歩くようにしている。</span>（我盡量每天走路）<br><b>つもり</b>＝心裡的打算，還沒真的定案：<span class='gd-jp'>毎日歩くつもりだ。</span>（我打算每天走路）</div><div class='gd-sec'>另外，<b>ことになる</b>跟<b>ようになる</b>也常被搞混：<br><span class='gd-jp'>日本で働くことになった。</span>（我要去日本工作了：被安排、事情定案）<br><span class='gd-jp'>日本語が話せるようになった。</span>（我變得會講日文了：能力、習慣慢慢改變）</div><div class='gd-warn'>判斷小訣竅：「我決定」用ことにする，「事情定下來了」用ことになる，「盡量」用ようにする，「打算」用つもり。</div>",
  "n4-48": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「〜まま」就是中文的<b>「～著就…」「就那樣～」</b>：某個狀態<b>沒有改變</b>，你就直接做了下一件事。像是冷氣開著就出門、鞋子穿著就走進房間。它常帶著「本來應該先改一下，結果沒改」的感覺。</div><div class='gd-h'>怎麼接</div><div class='gd-sec'><b>動詞た形＋まま</b>：最常用。先做了某個動作，留下一個狀態，然後一直沒變。<br><span class='gd-pair'><span class='gd-jp'>開けた</span> → <span class='gd-jp'>開けたまま</span>（開著沒關）</span><br><span class='gd-pair'><span class='gd-jp'>つけた</span> → <span class='gd-jp'>つけたまま</span>（燈、電視開著沒關）</span><br><b>動詞ない形＋まま</b>：一直「沒做」某件事的狀態。<br><span class='gd-pair'><span class='gd-jp'>言わない</span> → <span class='gd-jp'>言わないまま</span>（一直沒說）</span><br><b>名詞＋の＋まま</b>：<span class='gd-pair'><span class='gd-jp'>昔</span> → <span class='gd-jp'>昔のまま</span>（跟以前一樣）</span><br><b>この・その・あの＋まま</b>：<span class='gd-jp'>このまま</span>（就這樣）、<span class='gd-jp'>そのまま</span>（就那樣）<br>形容詞也可以接：い形容詞直接接，像<span class='gd-jp'>若いまま</span>（一直年輕）；な形容詞要加な，像<span class='gd-jp'>きれいなまま</span>（一直保持乾淨）。</div><div class='gd-h'>最常聽到的樣子</div><div class='gd-sec'><span class='gd-tag'>不小心就那樣了</span>跟「〜てしまう」一起用，表示懊惱、糟糕。</div><div class='gd-ex-line'>・<span class='gd-jp'>眼鏡をかけたままシャワーを浴びてしまった。</span>（戴著眼鏡就去沖澡了）</div><div class='gd-ex-line'>・<span class='gd-jp'>テレビをつけたまま寝てしまった。</span>（電視開著就睡著了）</div><div class='gd-sec'><span class='gd-tag'>規定、提醒</span>告訴別人不要「～著就…」。</div><div class='gd-ex-line'>・<span class='gd-jp'>靴を履いたまま部屋に入らないでください。</span>（請不要穿著鞋進房間）</div><div class='gd-sec'><span class='gd-tag'>一直沒做</span>用ない形，講某件事從頭到尾都沒做。</div><div class='gd-ex-line'>・<span class='gd-jp'>何も言わないまま帰ってしまった。</span>（什麼都沒說就回去了）</div><div class='gd-sec'><span class='gd-tag'>このまま・そのまま</span>生活中超常聽到，店員、客服最愛講。</div><div class='gd-ex-line'>・<span class='gd-jp'>そのままお待ちください。</span>（請就這樣稍等一下）</div><div class='gd-ex-line'>・<span class='gd-jp'>袋はいりません。このままで大丈夫です。</span>（不用袋子，直接這樣拿就好）</div><div class='gd-sec'><span class='gd-tag'>放句尾</span>用「〜のままだ／のままです」講「還是原樣」。</div><div class='gd-ex-line'>・<span class='gd-jp'>この町は昔のままだ。</span>（這個城鎮跟以前一模一樣）</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・這裡的た<b>不是「過去」</b>，是「已經變成那個狀態」。講現在、講未來也照樣用た形：<span class='gd-jp'>靴を履いたまま入ってもいいですよ。</span>（穿著鞋直接進來沒關係）<br>・講「保持某個狀態」時，不要接辭書形：×<span class='gd-jp'>眼鏡をかけるまま</span>，要說○<span class='gd-jp'>眼鏡をかけたまま</span>。<br>・名詞後面一定要加の：×<span class='gd-jp'>昔まま</span>，要說○<span class='gd-jp'>昔のまま</span>。<br>・中文的「～著」不一定都是まま。只是兩件事同時在做（邊吃邊看），日文要用ながら，看下面。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'><b>〜ながら</b>＝兩個動作<b>同時在做</b>，兩件都是你主動在做：<br><span class='gd-jp'>テレビを見ながら勉強した。</span>（邊看電視邊讀書）<br><b>〜たまま</b>＝某個狀態<b>放著沒動</b>，就做了下一件事：<br><span class='gd-jp'>テレビをつけたまま勉強した。</span>（電視開著沒關就讀書了）<br>第一句你真的有在看電視；第二句電視只是開著，你可能根本沒在看。</div><div class='gd-sec'><b>〜て</b>＝很普通的「～著（做）」，沒有「該改沒改」的感覺：<br><span class='gd-jp'>帽子をかぶって出かけた。</span>（戴上帽子出門了）<br><b>〜たまま</b>＝聽的人會覺得「應該先改掉吧」：<br><span class='gd-jp'>帽子をかぶったまま教室に入った。</span>（戴著帽子就進教室了，好像該先脫掉）</div><div class='gd-warn'>判斷小訣竅：兩件事一起做是ながら；某個狀態沒去動它、就那樣做下一件事是たまま。</div><div class='gd-h'>學會之後可以接著學</div><div class='gd-sec'>後面加「にしておく」＝<b>刻意讓它保持那樣</b>：<span class='gd-jp'>窓を開けたままにしておいてください。</span>（窗戶請就開著，不要關）</div>",
  "n4-13": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「〜てもいいです」就是中文的<b>「可以～」「～也沒關係」</b>。後面加「か」變成「可以～嗎？」，是在日本<b>問人家准不准</b>最常用的說法。在店裡想拍照、想坐空位、想試穿，都是用它開口。</div><div class='gd-h'>怎麼接</div><div class='gd-sec'>動詞先變成て形，再加「もいいです」。<br><span class='gd-pair'><span class='gd-jp'>使う</span> → <span class='gd-jp'>使って</span> → <span class='gd-jp'>使ってもいいです</span></span></div><div class='gd-h'>怎麼變：先看動詞是哪一類</div><div class='gd-sec'><b>第一類（五段動詞）</b>：看最後一個字。<br>う、つ、る → って：<span class='gd-pair'><span class='gd-jp'>座る</span> → <span class='gd-jp'>座って</span></span><span class='gd-pair'><span class='gd-jp'>待つ</span> → <span class='gd-jp'>待って</span></span><br>む、ぶ、ぬ → んで：<span class='gd-pair'><span class='gd-jp'>休む</span> → <span class='gd-jp'>休んで</span></span><span class='gd-pair'><span class='gd-jp'>呼ぶ</span> → <span class='gd-jp'>呼んで</span></span><br>く → いて：<span class='gd-pair'><span class='gd-jp'>書く</span> → <span class='gd-jp'>書いて</span></span>（只有<span class='gd-pair'><span class='gd-jp'>行く</span> → <span class='gd-jp'>行って</span></span>例外）<br>ぐ → いで：<span class='gd-pair'><span class='gd-jp'>泳ぐ</span> → <span class='gd-jp'>泳いで</span></span><br>す → して：<span class='gd-pair'><span class='gd-jp'>話す</span> → <span class='gd-jp'>話して</span></span></div><div class='gd-sec'><b>第二類（一段動詞）</b>：把「る」拿掉，加て。<br><span class='gd-pair'><span class='gd-jp'>食べる</span> → <span class='gd-jp'>食べて</span></span><span class='gd-pair'><span class='gd-jp'>見る</span> → <span class='gd-jp'>見て</span></span></div><div class='gd-sec'><b>第三類（只有兩個，直接背）</b>：<span class='gd-pair'><span class='gd-jp'>する</span> → <span class='gd-jp'>して</span></span><span class='gd-pair'><span class='gd-jp'>来る</span> → <span class='gd-jp'>来て</span>（きて）</span></div><div class='gd-h'>最常聽到的樣子</div><div class='gd-sec'><span class='gd-tag'>問可不可以</span>句尾加「か」。</div><div class='gd-ex-line'>・<span class='gd-jp'>この椅子を使ってもいいですか。</span>（這張椅子可以用嗎？）</div><div class='gd-ex-line'>・<span class='gd-jp'>ここに座ってもいいですか。</span>（可以坐這裡嗎？）</div><div class='gd-sec'><span class='gd-tag'>怎麼回答</span>可以：<span class='gd-jp'>はい、どうぞ。</span>（好，請）、<span class='gd-jp'>いいですよ。</span>（可以喔）<br>不行：<span class='gd-jp'>すみません、ちょっと…。</span>（不好意思，有點不方便……）</div><div class='gd-sec'><span class='gd-tag'>告訴對方可以</span>句尾常加「よ」，聽起來比較親切。</div><div class='gd-ex-line'>・<span class='gd-jp'>明日は休んでもいいですよ。</span>（明天可以休息喔）</div><div class='gd-ex-line'>・<span class='gd-jp'>鉛筆で書いてもいいです。</span>（用鉛筆寫也可以）</div><div class='gd-sec'><span class='gd-tag'>朋友之間</span>把です拿掉，口語連「も」也常省掉。</div><div class='gd-ex-line'>・<span class='gd-jp'>これ、食べていい？</span>（這個可以吃嗎？）</div><div class='gd-sec'>對主管、客人想問得更客氣，就把いい換成<span class='gd-jp'>よろしい</span>：<span class='gd-jp'>写真を撮ってもよろしいですか。</span>（請問可以拍照嗎？）</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・て形是「で」結尾的，後面就接「でもいい」：<span class='gd-jp'>休んでもいい</span>，不要寫成休んてもいい。<br>・被問「〜てもいいですか」想拒絕時，課本會教<span class='gd-jp'>いいえ、いけません</span>，但真實對話聽起來很硬，像在罵人。生活中多半說<span class='gd-jp'>すみません、ちょっと…</span>。<br>・「〜てもいいですよ」是<b>給人許可</b>，口氣有點上對下。對老師、主管說<span class='gd-jp'>帰ってもいいですよ</span>會很失禮。<br>・中文的「可以」也拿來講能力，像「我可以講日文」其實是「我會講」，日文要說<span class='gd-jp'>日本語が話せます</span>。講成<span class='gd-jp'>日本語を話してもいいです</span>，意思會變成「准許講日文」。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'>「可以、不可以、不用、一定要」這四個句型長得很像，用同一件事來看：<br><span class='gd-tag'>做，OK</span><span class='gd-jp'>明日は来てもいいです。</span>（明天可以來）<br><span class='gd-tag'>做，NG</span><span class='gd-jp'>明日は来てはいけません。</span>（明天不可以來）<br><span class='gd-tag'>不做，OK</span><span class='gd-jp'>明日は来なくてもいいです。</span>（明天不來也沒關係）<br><span class='gd-tag'>不做，NG</span><span class='gd-jp'>明日は来なくてはいけません。</span>（明天一定要來）<br>最後一格也常說成<span class='gd-jp'>来なければなりません</span>，意思一樣。</div><div class='gd-warn'>判斷小訣竅：先看前面是「て」還是「なくて」，再看後面是「いい」還是「いけない」。</div><div class='gd-sec'>另外別跟<b>ことができます</b>搞混：<br><span class='gd-jp'>ここで泳いでもいいですか。</span>（這裡可以游泳嗎？：問准不准）<br><span class='gd-jp'>泳ぐことができますか。</span>（你會游泳嗎？：問會不會）</div><div class='gd-warn'>判斷小訣竅：問「准不准」用てもいい；講「會不會、做不做得到」用ことができる。</div><div class='gd-h'>學會之後可以接著學</div><div class='gd-sec'>把上面那張表的另外三格學起來：「〜てはいけません」（禁止）、「〜なくてもいいです」（不必要）、「〜なければなりません」（義務）。</div>",
  "n4-14": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「〜てはいけません」就是中文的<b>「不可以～」「禁止～」</b>。老師宣布規定、介紹場所規則，或是爸媽跟小孩說「不可以說謊」，都會用到它。（實際的告示牌多半寫成「<span class='gd-jp'>撮影禁止</span>」或「<span class='gd-jp'>〜ないでください</span>」，不太會整句寫出來。）</div><div class='gd-h'>什麼時候用</div><div class='gd-sec'><span class='gd-tag'>說明規則</span>學校、公司、場所的規定，用嘴巴講給對方聽。</div><div class='gd-ex-line'>・<span class='gd-jp'>ここで写真を撮ってはいけません。</span>（這裡不可以拍照）</div><div class='gd-ex-line'>・<span class='gd-jp'>授業中に寝てはいけません。</span>（上課不可以睡覺）</div><div class='gd-sec'><span class='gd-tag'>教小孩、講道理</span>大人對小孩、或講一般人都該遵守的事，常用不加ます的「〜てはいけない」。</div><div class='gd-ex-line'>・<span class='gd-jp'>うそをついてはいけないよ。</span>（不可以說謊喔）</div><div class='gd-h'>怎麼接</div><div class='gd-sec'>先把動詞變成<b>て形</b>（就是接「〜てください」的那個形），後面直接加「はいけません」。<br><span class='gd-pair'><span class='gd-jp'>撮る</span> → <span class='gd-jp'>撮って</span> → <span class='gd-jp'>撮ってはいけません</span></span><br><span class='gd-pair'><span class='gd-jp'>食べる</span> → <span class='gd-jp'>食べて</span> → <span class='gd-jp'>食べてはいけません</span></span><br><span class='gd-pair'><span class='gd-jp'>する</span> → <span class='gd-jp'>して</span> → <span class='gd-jp'>してはいけません</span></span><br>有些第一類（五段動詞）的て形是「で」，就變成「ではいけません」：<br><span class='gd-pair'><span class='gd-jp'>飲む</span> → <span class='gd-jp'>飲んで</span> → <span class='gd-jp'>飲んではいけません</span></span><br><span class='gd-pair'><span class='gd-jp'>遊ぶ</span> → <span class='gd-jp'>遊んで</span> → <span class='gd-jp'>遊んではいけません</span></span></div><div class='gd-h'>最常聽到的樣子</div><div class='gd-sec'><span class='gd-tag'>〜てはいけません</span>有禮貌的說法，說明規則時用。<br><span class='gd-tag'>〜てはいけない</span>普通說法，對家人、朋友、小孩。<br><span class='gd-tag'>〜ちゃいけない</span>口語縮短版：「ては」變「ちゃ」，「では」變「じゃ」。</div><div class='gd-ex-line'>・<span class='gd-jp'>危ないから、ここで遊んじゃいけないよ。</span>（很危險，不可以在這裡玩喔）</div><div class='gd-sec'><span class='gd-tag'>〜ちゃだめ</span>把「いけない」換成「だめ」，更口語，爸媽罵小孩超常聽到。</div><div class='gd-ex-line'>・<span class='gd-jp'>まだ食べちゃだめ。</span>（還不可以吃）</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・「ては」的「は」念<b>wa</b>，不是ha。<br>・「飲んで」「遊んで」後面要接<b>では</b>，不要寫成飲んてはいけません。縮短時也跟著變成「じゃ」：<span class='gd-jp'>飲んじゃだめ</span>。<br>・這個說法<b>口氣很硬</b>，像在下規定。對主管、客人、長輩不要直接用，改說<span class='gd-jp'>〜ないでください</span>（請不要～），或店家常講的<span class='gd-jp'>〜はご遠慮ください</span>。<br>・課本常教「<span class='gd-jp'>〜てもいいですか</span>」→「<span class='gd-jp'>いいえ、〜てはいけません</span>」，但現實中這樣回很衝。日本人通常會說<span class='gd-jp'>すみません、ここはちょっと…</span>，用「ちょっと」委婉拒絕。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'>「可以／不可以／不用／一定要」這四個很容易打結，用同一個情境（醫生交代吃藥）一次看：<br><b>てもいい</b>＝可以做：<span class='gd-jp'>この薬は飲んでもいいです。</span>（這個藥可以吃）<br><b>てはいけない</b>＝不可以做：<span class='gd-jp'>この薬は飲んではいけません。</span>（這個藥不可以吃）<br><b>なくてもいい</b>＝不做也可以：<span class='gd-jp'>この薬は飲まなくてもいいです。</span>（這個藥不吃也沒關係）<br><b>なければならない</b>＝一定要做：<span class='gd-jp'>この薬は飲まなければなりません。</span>（這個藥一定要吃）</div><div class='gd-sec'>最要小心的是「<b>なくてはいけません</b>」，它也有「いけません」，意思卻是<b>必須</b>，跟「なければなりません」一樣：<br><span class='gd-jp'>飲んではいけません</span>（不可以吃）<br><span class='gd-jp'>飲まなくてはいけません</span>（一定要吃）<br>只差幾個字，意思完全相反。</div><div class='gd-warn'>判斷小訣竅：看「はいけません」前面。是一般的て形（<span class='gd-jp'>飲んで</span>）→ 不可以；是「なくて」（<span class='gd-jp'>飲まなくて</span>）→ 一定要。</div>",
  "n4-15": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「〜なくてもいいです」就是中文的<b>「不用～」「不～也沒關係」</b>。像店員跟你說「鞋子不用脫喔」，就是告訴你這件事<b>可以不做，要做也可以</b>。</div><div class='gd-h'>什麼時候用</div><div class='gd-sec'><span class='gd-tag'>告訴對方不必做</span>讓對方放心、幫對方省事。</div><div class='gd-ex-line'>・<span class='gd-jp'>明日は来なくてもいいです。</span>（明天不用來）</div><div class='gd-ex-line'>・<span class='gd-jp'>全部食べなくてもいいですよ。</span>（不用全部吃完喔）</div><div class='gd-sec'><span class='gd-tag'>問對方需不需要</span>句尾加「か」，就是「不～也可以嗎？」。</div><div class='gd-ex-line'>・<span class='gd-jp'>靴を脱がなくてもいいですか。</span>（不用脫鞋嗎？）</div><div class='gd-ex-line'>・<span class='gd-jp'>はい、脱がなくてもいいですよ。</span>（對，不用脫喔）</div><div class='gd-h'>怎麼接</div><div class='gd-sec'>先把動詞變成ない形（就是「不～」的形），再把最後的「い」換成「くて」，後面加「もいい」。<br><span class='gd-pair'><span class='gd-jp'>行かない</span> → い換成くて → <span class='gd-jp'>行かなくて</span></span> → 加もいい → <span class='gd-pair'><span class='gd-jp'>行かなくてもいい</span></span><br>要講得禮貌，後面再加「です」。</div><div class='gd-h'>怎麼變：先看動詞是哪一類</div><div class='gd-sec'><b>第一類（五段動詞）</b>：最後一個音換成同一行的「あ」段音，加ない，再改成なくてもいい。<br><span class='gd-pair'><span class='gd-jp'>書く</span> → く換成か → <span class='gd-jp'>書かなくてもいい</span></span><br><span class='gd-pair'><span class='gd-jp'>待つ</span> → <span class='gd-jp'>待たなくてもいい</span></span><span class='gd-pair'><span class='gd-jp'>帰る</span> → <span class='gd-jp'>帰らなくてもいい</span></span><br>最後是「う」的，要換成<b>わ</b>：<span class='gd-pair'><span class='gd-jp'>買う</span> → <span class='gd-jp'>買わなくてもいい</span></span><br>例外：<span class='gd-jp'>ある</span>的ない形就是「ない」，所以是<span class='gd-jp'>なくてもいい</span>，不是あらなくてもいい。</div><div class='gd-ex-line'>・<span class='gd-jp'>予約がなくてもいいですか。</span>（沒有預約也可以嗎？）</div><div class='gd-sec'><b>第二類（一段動詞）</b>：把「る」拿掉，加なくてもいい。<br><span class='gd-pair'><span class='gd-jp'>食べる</span> → <span class='gd-jp'>食べなくてもいい</span></span><span class='gd-pair'><span class='gd-jp'>慌てる</span> → <span class='gd-jp'>慌てなくてもいい</span></span></div><div class='gd-sec'><b>第三類（只有兩個，直接背）</b>：<span class='gd-pair'><span class='gd-jp'>する</span> → <span class='gd-jp'>しなくてもいい</span></span><span class='gd-pair'><span class='gd-jp'>来る</span> → <span class='gd-jp'>来なくてもいい</span>（こなくても）</span></div><div class='gd-ex-line'>・<span class='gd-jp'>今日は残業しなくてもいいです。</span>（今天不用加班）</div><div class='gd-h'>最常聽到的樣子</div><div class='gd-sec'><span class='gd-tag'>朋友之間</span>把「です」換成「よ」，常常連「も」都省掉。</div><div class='gd-ex-line'>・<span class='gd-jp'>無理しなくていいよ。</span>（不用勉強啦）</div><div class='gd-sec'><span class='gd-tag'>換個說法</span>「いい」換成「大丈夫」，意思一樣。</div><div class='gd-ex-line'>・<span class='gd-jp'>返事しなくても大丈夫です。</span>（不用回覆也沒關係）</div><div class='gd-sec'><span class='gd-tag'>更客氣</span>在公司、店裡、正式通知會聽到「なくてもかまいません」。</div><div class='gd-ex-line'>・<span class='gd-jp'>印鑑は持ってこなくてもかまいません。</span>（不用帶印章也沒關係）</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・不能直接在ない後面接ても：說成「行かないてもいい」是錯的，要把い換成くて，變成<span class='gd-jp'>行かなくてもいい</span>。<br>・<span class='gd-jp'>買う</span>是<span class='gd-jp'>買わない</span>，不是買あない；<span class='gd-jp'>ある</span>是<span class='gd-jp'>ない</span>，不是あらない。<br>・中文「不用來」和「不要來」只差一個字，日文差很多。<span class='gd-jp'>来なくてもいい</span>是「不來也行，來也可以」，沒有叫你別來的意思。<br>・別人問你「<span class='gd-jp'>〜なくてもいいですか</span>」，如果答案是「一定要做」，要用<span class='gd-jp'>いいえ、〜なければなりません</span>回答，不是只說いいえ就結束。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'>同一件事「明天去公司」，四種說法：<br><b>てもいい</b>＝可以做：<span class='gd-jp'>明日、会社に行ってもいいです。</span>（明天可以去公司）<br><b>なくてもいい</b>＝不做也行：<span class='gd-jp'>明日、会社に行かなくてもいいです。</span>（明天不用去公司）<br><b>てはいけない</b>＝不可以做：<span class='gd-jp'>明日、会社に行ってはいけません。</span>（明天不可以去公司）<br><b>なければならない</b>＝一定要做：<span class='gd-jp'>明日、会社に行かなければなりません。</span>（明天一定要去公司）</div><div class='gd-sec'>另外常跟它搞混的是「ないでください」：<br><span class='gd-jp'>来ないでください。</span>（請不要來：叫對方別做）<br><span class='gd-jp'>来なくてもいいです。</span>（不用來：做不做都可以）</div><div class='gd-warn'>判斷小訣竅：想說「不用、免了」用なくてもいい；想說「別做、不准」用ないでください或てはいけない。</div><div class='gd-h'>學會之後可以接著學</div><div class='gd-sec'>形容詞、名詞也能用同樣的意思：<span class='gd-jp'>高くなくてもいいです。</span>（不貴也沒關係）、<span class='gd-jp'>上手じゃなくてもいいです。</span>（不厲害也沒關係）。接著學「<span class='gd-jp'>〜なければなりません</span>」，就能把「不用做」和「一定要做」一起講清楚。</div>",
  "n4-16": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「〜なければなりません」就是中文的<b>「一定要～」「非～不可」</b>。日文的想法很有趣：它其實是「不做的話，不行」。不做不行，意思就是一定要做。</div><div class='gd-h'>什麼時候用</div><div class='gd-sec'><span class='gd-tag'>規定・義務</span>用在規定、義務：學校、公司規定的事，或情況逼你非做不可的事。</div><div class='gd-ex-line'>・<span class='gd-jp'>明日までにレポートを出さなければなりません。</span>（明天之前一定要交報告）</div><div class='gd-ex-line'>・<span class='gd-jp'>学校では制服を着なければなりません。</span>（在學校一定要穿制服）</div><div class='gd-sec'><span class='gd-tag'>自己覺得非做不可</span>沒有人規定，是你自己覺得「該做了」。</div><div class='gd-ex-line'>・<span class='gd-jp'>もう11時だ。帰らなければならない。</span>（已經 11 點了，我得回家了）</div><div class='gd-ex-line'>・<span class='gd-jp'>薬を毎日飲まなければなりません。</span>（我每天都得吃藥）</div><div class='gd-h'>怎麼接</div><div class='gd-sec'>三個步驟：先變成ない形（「不～」的樣子），把最後的「ない」拿掉，再接<b>なければなりません</b>。<br><span class='gd-pair'><span class='gd-jp'>行く</span> → <span class='gd-jp'>行かない</span></span> → 把ない拿掉 → <span class='gd-pair'><span class='gd-jp'>行か</span> → <span class='gd-jp'>行かなければなりません</span></span></div><div class='gd-sec'><b>第一類（五段動詞）</b>：<br><span class='gd-pair'><span class='gd-jp'>書く</span> → <span class='gd-jp'>書かなければなりません</span></span><br><span class='gd-pair'><span class='gd-jp'>待つ</span> → <span class='gd-jp'>待たなければなりません</span></span><br><span class='gd-pair'><span class='gd-jp'>買う</span> → <span class='gd-jp'>買わなければなりません</span></span>（う結尾的變成わ，不是あ）</div><div class='gd-sec'><b>第二類（一段動詞）</b>：<br><span class='gd-pair'><span class='gd-jp'>食べる</span> → <span class='gd-jp'>食べなければなりません</span></span><br><span class='gd-pair'><span class='gd-jp'>起きる</span> → <span class='gd-jp'>起きなければなりません</span></span></div><div class='gd-sec'><b>第三類（只有兩個，直接背）</b>：<br><span class='gd-pair'><span class='gd-jp'>する</span> → <span class='gd-jp'>しなければなりません</span></span><br><span class='gd-pair'><span class='gd-jp'>来る</span> → <span class='gd-jp'>来なければなりません</span>（こなければ）</span></div><div class='gd-h'>最常聽到的樣子</div><div class='gd-sec'><span class='gd-tag'>なければなりません</span>禮貌說法，對老師、主管、客人用。<br><span class='gd-tag'>なければならない</span>普通體，自言自語、寫文章用。<br><span class='gd-tag'>なきゃ／ないと</span>朋友之間的口語，「なければ」縮短成「なきゃ」，或直接說到「ないと」就停。</div><div class='gd-ex-line'>・<span class='gd-jp'>あ、もう行かなきゃ。</span>（啊，我該走了）</div><div class='gd-ex-line'>・<span class='gd-jp'>明日早いから、早く寝ないと。</span>（明天要早起，得早點睡了）</div><div class='gd-sec'>講過去「當時必須～」，把最後變成<b>なりませんでした</b>：</div><div class='gd-ex-line'>・<span class='gd-jp'>昨日は遅くまで働かなければなりませんでした。</span>（昨天我得工作到很晚）</div><div class='gd-sec'>另外你也會聽到「<span class='gd-jp'>〜なければいけません</span>」，意思幾乎一樣，日常對話裡很常用。</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・要接ない形，不是辭書形（字典裡的原形）：不是行くなければ，是<span class='gd-jp'>行かなければ</span>。<br>・字很長容易念錯，拆成「な・け・れ・ば」＋「なりません」來記，不是なくれば、なけば。<br>・別看到最後的「ません」就以為是「不做」。整句是<b>一定要做</b>。<br>・<span class='gd-jp'>来る</span>念<b>こなければ</b>，不是きなければ。<br>・「なきゃ」「ないと」是朋友用的，對主管、老師要說完整的なければなりません。<br>・請別人做事時，直接說「你必須～」聽起來很強硬，一般用「〜てください」比較客氣。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'>這四個常常一起考，用同一件事「明天去學校」來比：<br><span class='gd-jp'>明日、学校に行かなければなりません。</span>（明天<b>一定要</b>去學校）<br><span class='gd-jp'>明日、学校に行かなくてもいいです。</span>（明天<b>不去也可以</b>）<br><span class='gd-jp'>明日、学校に行ってもいいです。</span>（明天<b>可以</b>去學校）<br><span class='gd-jp'>明日、学校に行ってはいけません。</span>（明天<b>不可以</b>去學校）</div><div class='gd-sec'>特別注意：被問「<span class='gd-jp'>〜なければなりませんか</span>」（一定要～嗎），想回答「不用」時，要說<b>なくてもいいです</b>，不是なければなりません的否定。</div><div class='gd-ex-line'>・<span class='gd-jp'>名前を書かなければなりませんか。</span>（一定要寫名字嗎？）</div><div class='gd-ex-line'>・<span class='gd-jp'>いいえ、書かなくてもいいです。</span>（不用，不寫也可以）</div><div class='gd-sec'>還有一個常混的是<b>ほうがいい</b>，它只是「建議」，沒有強制：<br><span class='gd-jp'>薬を飲んだほうがいいです。</span>（最好吃個藥）<br><span class='gd-jp'>薬を飲まなければなりません。</span>（一定要吃藥）</div><div class='gd-warn'>判斷小訣竅：「一定要」是なければなりません，「不用」是なくてもいい，「最好」是ほうがいい。</div>",
  "n4-2": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「〜つもりです」就是中文的<b>「我打算～」</b>。你心裡已經想好要做某件事，跟別人說出你的計畫時就用它。<br>例如朋友問你暑假要幹嘛，你說「我打算去日本」，就是<span class='gd-jp'>日本へ行くつもりです</span>。</div><div class='gd-h'>怎麼接</div><div class='gd-sec'><span class='gd-tag'>打算做</span>動詞的<b>辭書形</b>（字典裡查到的原形）＋つもりです<br><span class='gd-pair'><span class='gd-jp'>行く</span> → <span class='gd-jp'>行くつもりです</span></span><span class='gd-pair'><span class='gd-jp'>買う</span> → <span class='gd-jp'>買うつもりです</span></span><span class='gd-pair'><span class='gd-jp'>勉強する</span> → <span class='gd-jp'>勉強するつもりです</span></span></div><div class='gd-ex-line'>・<span class='gd-jp'>来年、日本へ留学するつもりです。</span>（我打算明年去日本留學）</div><div class='gd-ex-line'>・<span class='gd-jp'>週末は家でゆっくりするつもりです。</span>（週末我打算在家好好休息）</div><div class='gd-sec'><span class='gd-tag'>打算不做</span>動詞的<b>ない形</b>＋つもりです<br><span class='gd-pair'><span class='gd-jp'>吸う</span> → <span class='gd-jp'>吸わない</span> → <span class='gd-jp'>吸わないつもりです</span></span></div><div class='gd-ex-line'>・<span class='gd-jp'>もうタバコは吸わないつもりです。</span>（我打算不再抽菸了）</div><div class='gd-sec'>跟朋友講話時，把です換成<b>だ</b>，或乾脆只講到つもり就好：<span class='gd-jp'>夏休み、どうするつもり？</span>（暑假你打算怎樣？）</div><div class='gd-h'>最常聽到的樣子</div><div class='gd-sec'><span class='gd-tag'>つもりはありません</span>「完全沒那個打算」，比「〜ないつもりです」更斬釘截鐵，常用來拒絕。</div><div class='gd-ex-line'>・<span class='gd-jp'>会社をやめるつもりはありません。</span>（我完全沒打算辭職）</div><div class='gd-sec'><span class='gd-tag'>つもりでした</span>「本來打算～」，後面通常接「結果沒做到」。</div><div class='gd-ex-line'>・<span class='gd-jp'>早く寝るつもりでしたが、ゲームをしてしまいました。</span>（本來打算早點睡，結果打了電動）</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・つもり前面放<b>辭書形</b>，不能放ます形：是<span class='gd-jp'>行くつもりです</span>，不是「行きますつもりです」。<br>・它講的是<b>人的打算</b>，自己控制不了的事不能用。「明天打算放晴」這種話日文不會用つもり講。<br>・主要拿來講<b>自己</b>的打算。講別人的打算，通常會加「そうです」或「と言っていました」：<span class='gd-jp'>田中さんは留学するつもりだそうです。</span>（聽說田中打算去留學）<br>・對老師、主管直接問「<span class='gd-jp'>どうするつもりですか</span>」，聽起來很像在質問「你到底想怎樣」。問長輩的計畫，改說<span class='gd-jp'>ご予定は？</span>比較得體。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'>同樣是「明年去日本」，用不同說法，代表事情確定到什麼程度：<br><b>ようと思っています</b>＝心裡有這個想法，正在考慮（N4-42）<br><span class='gd-jp'>来年、日本へ行こうと思っています。</span>（我在想明年去日本）<br><b>つもりです</b>＝自己已經下定主意的打算，比上面那句更堅定<br><span class='gd-jp'>来年、日本へ行くつもりです。</span>（我打算明年去日本）<br><b>予定です</b>＝已經排好、有具體安排的行程，像機票訂了、日期定了<br><span class='gd-jp'>来年3月に日本へ行く予定です。</span>（我預定明年三月去日本）</div><div class='gd-warn'>判斷小訣竅：「還在想」用ようと思う，「我心意已決」用つもり，「已經排進行事曆」用予定。</div><div class='gd-h'>學會之後可以接著學</div><div class='gd-sec'>想說「我決定了～」，可以接著學<span class='gd-jp'>〜ことにします</span>（N4-47）：<span class='gd-jp'>来年留学することにしました。</span>（我決定明年去留學）</div>",
  "n4-3": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「〜かもしれません」就是中文的<b>「可能～」「說不定～」</b>。你心裡沒把握，覺得有這個可能，但也可能不會。像台灣人說「明天可能會下雨喔」，日文就是<span class='gd-jp'>明日は雨が降るかもしれません</span>。</div><div class='gd-h'>什麼時候用</div><div class='gd-sec'><span class='gd-tag'>猜測</span>對一件事沒把握，說出你覺得「有可能」的情況。</div><div class='gd-ex-line'>・<span class='gd-jp'>明日は雨が降るかもしれません。</span>（明天可能會下雨）</div><div class='gd-ex-line'>・<span class='gd-jp'>あの店、今日は休みかもしれない。</span>（那家店今天說不定沒開）</div><div class='gd-ex-line'>・<span class='gd-jp'>彼はもう帰ったかもしれない。</span>（他可能已經回去了）</div><div class='gd-sec'><span class='gd-tag'>先打預防針</span>講自己的事也很常用，把話說得軟一點，先讓對方有心理準備。</div><div class='gd-ex-line'>・<span class='gd-jp'>すみません、少し遅れるかもしれません。</span>（不好意思，我可能會晚一點到）</div><div class='gd-ex-line'>・<span class='gd-jp'>土曜日はちょっと行けないかもしれない。</span>（星期六我可能沒辦法去）</div><div class='gd-h'>怎麼接</div><div class='gd-sec'><b>動詞</b>：不用變，直接接。否定、過去也一樣直接接。<br><span class='gd-pair'><span class='gd-jp'>行く</span> → <span class='gd-jp'>行くかもしれない</span></span><span class='gd-pair'><span class='gd-jp'>行かない</span> → <span class='gd-jp'>行かないかもしれない</span></span><span class='gd-pair'><span class='gd-jp'>行った</span> → <span class='gd-jp'>行ったかもしれない</span></span></div><div class='gd-sec'><b>い形容詞</b>：直接接。<br><span class='gd-pair'><span class='gd-jp'>高い</span> → <span class='gd-jp'>高いかもしれない</span></span></div><div class='gd-sec'><b>な形容詞、名詞</b>：要把「だ」拿掉再接。<br><span class='gd-pair'><span class='gd-jp'>静かだ</span> → だ拿掉 → <span class='gd-jp'>静かかもしれない</span></span><br><span class='gd-pair'><span class='gd-jp'>雨だ</span> → だ拿掉 → <span class='gd-jp'>雨かもしれない</span></span><br>但過去的「だった」要留著：<span class='gd-pair'><span class='gd-jp'>雨だった</span> → <span class='gd-jp'>雨だったかもしれない</span></span></div><div class='gd-h'>最常聽到的樣子</div><div class='gd-sec'><span class='gd-tag'>かもしれません</span>禮貌版，對老師、同事、客人用。<br><span class='gd-tag'>かもしれない</span>朋友、家人之間講。<br><span class='gd-tag'>かも</span>更口語的縮短版，年輕人、朋友聊天超常聽到。</div><div class='gd-ex-line'>・<span class='gd-jp'>あ、財布忘れたかも。</span>（啊，我好像忘了帶錢包）</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・名詞、な形容詞後面不能留「だ」：說<span class='gd-jp'>雨かもしれない</span>，不是「雨だかもしれない」。<br>・「かもしれない」最後的「ない」<b>不是否定</b>。<span class='gd-jp'>来るかもしれない</span>是「可能會來」。要說「可能不來」，是把前面的動詞變否定：<span class='gd-jp'>来ないかもしれない</span>。<br>・它的把握很低，大概五五波，甚至更低。你很確定的事不要用，不然聽起來像不負責任。例如跟人約好了卻說<span class='gd-jp'>行くかもしれません</span>，對方會以為你可能不來。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'>同樣在猜「鈴木會不會來」，把握程度不一樣：<br><b>かもしれない</b>＝可能會，也可能不會，心裡沒底：<span class='gd-jp'>鈴木さんは来るかもしれません。</span>（鈴木說不定會來）<br><b>でしょう</b>＝大概會，覺得蠻有可能：<span class='gd-jp'>鈴木さんは来るでしょう。</span>（鈴木大概會來吧）<br><b>はず</b>＝照理說應該會，有根據，例如他昨天親口說會來：<span class='gd-jp'>鈴木さんは来るはずです。</span>（鈴木應該會來才對）</div><div class='gd-warn'>判斷小訣竅：把握從低到高是 かもしれない ＜ でしょう ＜ はず。心裡沒底、只是「說不定」，就用かもしれない；有理由、覺得「照理說會」，就用はず。</div>",
  "n4-11": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「〜ほうがいい」就是中文的<b>「你最好～」「最好不要～」</b>。朋友發燒了，你說「你最好去看醫生喔」，日文就是<span class='gd-jp'>病院に行ったほうがいいよ</span>。它是在給建議，口氣裡帶著「不這樣做，可能會不太好喔」的意思。</div><div class='gd-h'>怎麼接</div><div class='gd-sec'><span class='gd-tag'>最好做～</span>動詞的<b>た形</b>＋ほうがいい<br><span class='gd-pair'><span class='gd-jp'>休む</span> → <span class='gd-jp'>休んだほうがいい</span></span><span class='gd-pair'><span class='gd-jp'>行く</span> → <span class='gd-jp'>行ったほうがいい</span></span><br><span class='gd-pair'><span class='gd-jp'>食べる</span> → <span class='gd-jp'>食べたほうがいい</span></span><span class='gd-pair'><span class='gd-jp'>する</span> → <span class='gd-jp'>したほうがいい</span></span><br>た形還不熟的話，可以從て形去想：把「て」換成「た」、「で」換成「だ」就好。<span class='gd-pair'><span class='gd-jp'>休んで</span> → <span class='gd-jp'>休んだ</span></span></div><div class='gd-sec'><span class='gd-tag'>最好不要～</span>動詞的<b>ない形</b>＋ほうがいい<br><span class='gd-pair'><span class='gd-jp'>行く</span> → <span class='gd-jp'>行かないほうがいい</span></span><span class='gd-pair'><span class='gd-jp'>食べる</span> → <span class='gd-jp'>食べないほうがいい</span></span><br><span class='gd-pair'><span class='gd-jp'>来る</span> → <span class='gd-jp'>来ないほうがいい</span>（こない）</span></div><div class='gd-sec'>句尾看對象：跟朋友說「〜ほうがいいよ」，比較有禮貌就說「〜ほうがいいです」。</div><div class='gd-ex-line'>・<span class='gd-jp'>雨が降りそうだから、傘を持っていったほうがいいよ。</span>（好像快下雨了，最好帶傘出門喔）</div><div class='gd-ex-line'>・<span class='gd-jp'>寝る前にコーヒーを飲まないほうがいいです。</span>（睡前最好不要喝咖啡）</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・用的是た形，但<b>不是過去</b>。<span class='gd-jp'>行ったほうがいい</span>是叫你現在或之後去，不是「去過」。<br>・中文直覺會想用原形說成「行くほうがいい」。給別人具體建議時，日本人習慣說<span class='gd-jp'>行ったほうがいい</span>，先這樣記最保險。<br>・否定只要用ない形，<b>不用再改成た形</b>：是<span class='gd-jp'>行かないほうがいい</span>，不要說成「行かなかったほうがいい」。<br>・它的口氣其實不算輕。直接對主管、老師說「〜たほうがいいですよ」，聽起來有點像在教對方做事。想客氣一點，後面加「と思います」：<span class='gd-jp'>少し休んだほうがいいと思います。</span>（我覺得您稍微休息一下比較好）<br>・「ほう」寫成漢字是「方」，這裡念<b>ほう</b>，不是「〜方（做法）」的かた。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'>同樣是喉嚨痛的情境：<br><b>たほうがいい</b>＝給建議，不做也可以，只是不太好：<span class='gd-jp'>のどが痛いなら、薬を飲んだほうがいいですよ。</span>（喉嚨痛的話，最好吃個藥喔）<br><b>なければなりません</b>＝規定，非做不可：<span class='gd-jp'>この薬は一日三回飲まなければなりません。</span>（這個藥一天一定要吃三次）<br><b>たらいい</b>＝提供一個辦法，口氣比較輕鬆：<span class='gd-jp'>のどが痛いときは、温かいお茶を飲んだらいいですよ。</span>（喉嚨痛的時候，喝點熱茶就好了）</div><div class='gd-warn'>判斷小訣竅：「最好～（不然不太好）」用ほうがいい，「一定要～」用なければなりません，「～這樣做就行了」用たらいい。</div><div class='gd-h'>學會之後可以接著學</div><div class='gd-sec'>把いい換成よかった，就變成「早知道就～」的後悔：<span class='gd-jp'>傘を持ってきたほうがよかった。</span>（早知道就帶傘來了）</div>",
  "n4-12": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「〜すぎる」就是中文的<b>「太～了」「～過頭了」</b>。吃太多、喝太多、太貴、太難，只要是<b>超過剛好的程度</b>，就在後面加「すぎる」。禮貌一點就說「すぎます」。</div><div class='gd-ex-line'>・<span class='gd-jp'>昨日、ゲームをやりすぎました。</span>（昨天電動打過頭了）</div><div class='gd-ex-line'>・<span class='gd-jp'>このかばんは高すぎます。</span>（這個包包太貴了）</div><div class='gd-h'>怎麼接</div><div class='gd-sec'><span class='gd-tag'>動詞</span>先變成ます形，把「ます」拿掉，接すぎる。三類動詞都一樣。<br><span class='gd-pair'><span class='gd-jp'>飲む</span> → <span class='gd-jp'>飲みます</span> → <span class='gd-jp'>飲みすぎる</span></span><br><span class='gd-pair'><span class='gd-jp'>食べる</span> → <span class='gd-jp'>食べます</span> → <span class='gd-jp'>食べすぎる</span></span><br><span class='gd-pair'><span class='gd-jp'>する</span> → <span class='gd-jp'>します</span> → <span class='gd-jp'>しすぎる</span></span>（例：<span class='gd-jp'>心配しすぎる</span>＝太擔心）</div><div class='gd-sec'><span class='gd-tag'>い形容詞</span>把最後的「い」拿掉，接すぎる。<br><span class='gd-pair'><span class='gd-jp'>高い</span> → <span class='gd-jp'>高すぎる</span></span><span class='gd-pair'><span class='gd-jp'>難しい</span> → <span class='gd-jp'>難しすぎる</span></span></div><div class='gd-sec'><span class='gd-tag'>な形容詞</span>直接接，<b>不要加な</b>。<br><span class='gd-pair'><span class='gd-jp'>静か</span> → <span class='gd-jp'>静かすぎる</span></span><span class='gd-pair'><span class='gd-jp'>派手</span> → <span class='gd-jp'>派手すぎる</span></span></div><div class='gd-h'>すぎる本身也會變</div><div class='gd-sec'>すぎる的變法跟<b>第二類（一段動詞）</b>一樣，把「る」拿掉再接東西就好：<br><span class='gd-pair'><span class='gd-jp'>すぎる</span> → <span class='gd-jp'>すぎます</span></span><span class='gd-pair'><span class='gd-jp'>すぎる</span> → <span class='gd-jp'>すぎた</span></span><span class='gd-pair'><span class='gd-jp'>すぎる</span> → <span class='gd-jp'>すぎて</span></span><br>最常見的是用「すぎて」說明後面那個結果的原因：</div><div class='gd-ex-line'>・<span class='gd-jp'>食べすぎて、お腹が痛いです。</span>（吃太多，肚子痛）</div><div class='gd-ex-line'>・<span class='gd-jp'>この部屋は静かすぎて、ちょっとこわいです。</span>（這房間太安靜了，有點可怕）</div><div class='gd-h'>最常聽到的樣子</div><div class='gd-sec'><span class='gd-tag'>變成名詞</span>動詞ます形＋すぎ，後面不接る，就變成「～過量」這個名詞。</div><div class='gd-ex-line'>・<span class='gd-jp'>飲みすぎに気をつけてください。</span>（請小心不要喝太多）</div><div class='gd-sec'><span class='gd-tag'>道歉</span>吵架後很常聽到。</div><div class='gd-ex-line'>・<span class='gd-jp'>さっきは言いすぎました。ごめんなさい。</span>（剛剛我話說得太過分了，對不起）</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・い形容詞的「い」一定要拿掉：是<span class='gd-jp'>高すぎる</span>，不是高いすぎる。<br>・な形容詞不要加な：是<span class='gd-jp'>静かすぎる</span>，不是静かなすぎる。<br>・<b>「いい」要變成「よ」</b>：<span class='gd-jp'>よすぎる</span>（太好）。如果寫成<span class='gd-jp'>いいすぎる</span>，日本人會聽成<span class='gd-jp'>言いすぎる</span>（話說太過分）。<br>・「ない（沒有）」要變成<span class='gd-jp'>なさすぎる</span>：<span class='gd-jp'>時間がなさすぎる</span>（時間太少了）。但<span class='gd-jp'>少ない</span>照一般規則，是<span class='gd-jp'>少なすぎる</span>。<br>・すぎる通常帶有「超過頭、不太好」的感覺。年輕人口語會用<span class='gd-jp'>かわいすぎる</span>來誇人，但一般想說「很好吃」「很好看」，用<span class='gd-jp'>とても</span>比較穩。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'>中文的「太」有時候只是「很」的意思（例如「太棒了」），台灣人很容易一律翻成すぎる。看同一個情境：<br><span class='gd-jp'>このかばんはとても高いです。</span>（這包包很貴）：只是在描述它很貴。<br><span class='gd-jp'>このかばんは高すぎます。</span>（這包包太貴了）：已經超過你能接受的程度，言下之意是「我不會買」。</div><div class='gd-warn'>判斷小訣竅：在後面接得上「所以不行／所以有問題」的，才用すぎる；只是說程度很高，就用とても。</div><div class='gd-h'>學會之後可以接著學</div><div class='gd-sec'>跟「〜ないようにする」合在一起，就是醫生最愛講的話：<span class='gd-jp'>飲みすぎないようにしてください。</span>（請注意不要喝太多）</div>",
  "n4-21": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「し」就是中文的<b>「又～又～」「而且～」</b>。你在跟人解釋「為什麼」的時候，把理由一個一個疊上去，最後帶出結論。像是「這家店便宜，又好吃，所以我常來」，日文就用し把「便宜」「好吃」串起來。</div><div class='gd-ex-line'>・<span class='gd-jp'>この店は安いし、おいしいし、よく来ます。</span>（這家店又便宜又好吃，我常來）</div><div class='gd-h'>怎麼接</div><div class='gd-sec'>前面放<b>普通形</b>（就是沒有ます、です的說法），後面直接加し。<br><b>動詞</b>：<span class='gd-pair'><span class='gd-jp'>降る</span> → <span class='gd-jp'>降るし</span></span><span class='gd-pair'><span class='gd-jp'>ない</span> → <span class='gd-jp'>ないし</span></span><span class='gd-pair'><span class='gd-jp'>疲れた</span> → <span class='gd-jp'>疲れたし</span></span><br><b>い形容詞</b>：<span class='gd-pair'><span class='gd-jp'>安い</span> → <span class='gd-jp'>安いし</span></span><span class='gd-pair'><span class='gd-jp'>遠くない</span> → <span class='gd-jp'>遠くないし</span></span><br><b>な形容詞</b>：要先加「だ」再加し。<span class='gd-pair'><span class='gd-jp'>静か</span> → <span class='gd-jp'>静かだし</span></span><br><b>名詞</b>：一樣要加「だ」。<span class='gd-pair'><span class='gd-jp'>雨</span> → <span class='gd-jp'>雨だし</span></span><br>對長輩、客人講話時，也可以用禮貌的說法：<span class='gd-jp'>便利ですし</span>、<span class='gd-jp'>あまり時間もありませんし</span>。</div><div class='gd-h'>什麼時候用</div><div class='gd-sec'><span class='gd-tag'>疊理由帶出結論</span>最常見的用法。理由前面常搭配「も」，有「這個也～、那個也～」的感覺。</div><div class='gd-ex-line'>・<span class='gd-jp'>お金もないし、時間もないし、旅行は無理です。</span>（錢也沒有、時間也沒有，旅行是不可能了）</div><div class='gd-ex-line'>・<span class='gd-jp'>雨も降っているし、疲れているし、タクシーで帰りましょう。</span>（又在下雨，又累了，搭計程車回去吧）</div><div class='gd-sec'><span class='gd-tag'>講人或東西的優點、缺點</span>描述一個人、一個地方有哪些特色。</div><div class='gd-ex-line'>・<span class='gd-jp'>田中さんは優しいし、おもしろいし、みんなに人気がある。</span>（田中又溫柔又有趣，很受大家歡迎）</div><div class='gd-sec'><span class='gd-tag'>只說一個理由</span>只講一個也可以，聽起來像「（還有其他原因啦）光是這點就～」，口氣比較軟。</div><div class='gd-ex-line'>・<span class='gd-jp'>もう遅いし、そろそろ帰ります。</span>（都這麼晚了，我差不多該回去了）</div><div class='gd-sec'>甚至可以把結論吞掉不講，讓對方自己懂，拒絕人的時候很好用：<br><span class='gd-jp'>今日はちょっと疲れてるし…</span>（今天有點累耶……）</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・な形容詞和名詞<b>一定要加だ</b>：是<span class='gd-jp'>静かだし</span>、<span class='gd-jp'>雨だし</span>，不能說「静かし」「雨し」。<br>・疊在一起的理由要<b>往同一個方向</b>，都是支持同一個結論。例如要說「我喜歡這家店」，就疊「便宜」「好吃」；不要一個好一個壞混在一起。<br>・し有「不只這個」的味道。如果你只有一個很明確的原因，想講得清楚有力，用「から」或「ので」比較直接。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'><b>し</b>＝疊好幾個理由，口氣是「又～又～，所以…」：<br><span class='gd-jp'>この店は安いし、おいしいし、よく来ます。</span>（又便宜又好吃，我常來）<br><b>から・ので</b>＝明確說出「就是因為這個」：<br><span class='gd-jp'>この店は安いから、よく来ます。</span>（因為便宜，所以我常來）</div><div class='gd-sec'><b>たり</b>也是一次講好幾個，但它列的是<b>做了哪些事</b>當例子，不是理由：<br><span class='gd-jp'>週末は映画を見たり、買い物をしたりします。</span>（週末會看看電影、買買東西）<br><span class='gd-jp'>週末は暇だし、天気もいいし、出かけよう。</span>（週末有空，天氣又好，出去走走吧）</div><div class='gd-warn'>判斷小訣竅：在講「為什麼」、要疊好幾個理由，用し；只有一個清楚的原因，用から・ので；在講「做了哪些事」，用たり。</div><div class='gd-h'>學會之後可以接著學</div><div class='gd-sec'>理由講完想再補一個，可以用「それに」（而且）接下一句：<span class='gd-jp'>この部屋は広いし、駅にも近い。それに家賃も安い。</span>（這間房子很寬，離車站又近，而且房租也便宜）</div>",
  "n4-36": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「〜でしょう」就像中文的<b>「大概～吧」</b>。語尾往下掉，是在<b>猜</b>；語尾往上揚，就變成「～對吧？」，是在<b>跟對方確認</b>。「だろう」是它的普通說法，意思一樣，只是沒有禮貌的感覺。</div><div class='gd-h'>什麼時候用</div><div class='gd-sec'><span class='gd-tag'>猜測（語調往下）</span>不確定，但心裡覺得八成是這樣。氣象報告最愛用。</div><div class='gd-ex-line'>・<span class='gd-jp'>明日は雨が降るでしょう。</span>（明天大概會下雨）</div><div class='gd-ex-line'>・<span class='gd-jp'>田中さんはもう家に帰ったでしょう。</span>（田中先生大概已經回家了吧）</div><div class='gd-sec'>常跟「<span class='gd-jp'>たぶん</span>」（大概）一起出現：<span class='gd-jp'>たぶん大丈夫でしょう。</span>（大概沒問題吧）</div><div class='gd-sec'><span class='gd-tag'>確認（語調往上）</span>你覺得對方也知道、也會同意，問一下讓他點頭。口語常縮短成「<span class='gd-jp'>でしょ？</span>」。</div><div class='gd-ex-line'>・<span class='gd-jp'>これ、おいしいでしょう？</span>（這個很好吃對吧？）</div><div class='gd-ex-line'>・<span class='gd-jp'>ほら、言ったでしょ？</span>（你看，我不是說過了嗎？）</div><div class='gd-h'>怎麼接</div><div class='gd-sec'>前面放<b>普通形</b>（就是不加です、ます的說法），後面加でしょう或だろう。<br>動詞：<span class='gd-pair'><span class='gd-jp'>行く</span> → <span class='gd-jp'>行くでしょう</span></span><span class='gd-pair'><span class='gd-jp'>行かない</span> → <span class='gd-jp'>行かないでしょう</span></span><span class='gd-pair'><span class='gd-jp'>行った</span> → <span class='gd-jp'>行ったでしょう</span></span><br>い形容詞：直接加。<span class='gd-pair'><span class='gd-jp'>高い</span> → <span class='gd-jp'>高いでしょう</span></span><br>名詞、な形容詞：<b>把だ拿掉</b>再加。<span class='gd-pair'><span class='gd-jp'>学生だ</span> → <span class='gd-jp'>学生でしょう</span></span><span class='gd-pair'><span class='gd-jp'>元気だ</span> → <span class='gd-jp'>元気でしょう</span></span><br>過去的「だった」要留著：<span class='gd-pair'><span class='gd-jp'>学生だった</span> → <span class='gd-jp'>学生だったでしょう</span></span></div><div class='gd-h'>でしょう跟だろう怎麼選</div><div class='gd-sec'><b>でしょう</b>：有禮貌，對不熟的人、正式場合、新聞氣象都用它。<br><b>だろう</b>：普通說法，最常出現在<b>心裡想、自言自語、文章</b>裡。</div><div class='gd-ex-line'>・<span class='gd-jp'>明日は晴れるだろう。</span>（明天大概會放晴吧：自己在想）</div><div class='gd-sec'>直接對人講「<span class='gd-jp'>だろう</span>」「<span class='gd-jp'>だろ？</span>」聽起來偏男生、口氣比較衝。跟朋友聊天，很多人（尤其女生）都說「<span class='gd-jp'>でしょ？</span>」。</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・名詞、な形容詞後面不要留だ：說<span class='gd-jp'>学生でしょう</span>，不是「学生だでしょう」。<br>・中文的「會」不一定是でしょう。「我明天會去」是自己決定的事，直接說<span class='gd-jp'>明日行きます</span>。用「行くでしょう」聽起來像在猜自己會不會去，很奇怪。<br>・確認用的「<span class='gd-jp'>でしょう？</span>」帶有「你應該知道吧」的感覺，對老師、主管講會有點沒禮貌，改成「<span class='gd-jp'>〜ですよね</span>」比較保險。<br>・でしょう要念長音（でしょー），短短的「でしょ」是口語縮短的版本。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'>同一件事：田中先生今天會不會來？<br>・<span class='gd-jp'>田中さんは来るでしょう。</span>（田中先生大概會來吧）→ 我覺得<b>八成會來</b>。<br>・<span class='gd-jp'>田中さんは来るかもしれません。</span>（田中先生說不定會來）→ <b>一半一半</b>，不來也不意外。<br>・<span class='gd-jp'>田中さんは来るはずです。</span>（田中先生應該會來）→ <b>有根據</b>，例如他昨天親口說會來。</div><div class='gd-warn'>判斷小訣竅：「說不定」用かもしれない，「大概吧」用でしょう，「照理說應該」用はずだ。</div><div class='gd-h'>學會之後可以接著學</div><div class='gd-sec'>後面加「と思います」更柔和，男女都很常用：<span class='gd-jp'>明日は寒くなるだろうと思います。</span>（我想明天大概會變冷）<br>把でしょう變成問句「でしょうか」，比「ですか」更客氣：<span class='gd-jp'>すみません、駅はどこでしょうか。</span>（不好意思，請問車站在哪裡？）</div>",
  "n4-1": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「〜までに」就是中文的<b>「最晚～之前（要做好）」</b>，也就是截止期限。像繳費單上寫「請於 5 月 10 日前繳費」，那個「前」就是までに。重點是<b>在那個時間點之前，把一件事做完</b>。</div><div class='gd-h'>什麼時候用</div><div class='gd-sec'><span class='gd-tag'>交代期限</span>老師、主管、店家跟你說「最晚什麼時候要做好」。</div><div class='gd-ex-line'>・<span class='gd-jp'>レポートは金曜日までに出してください。</span>（報告請在週五之前交）</div><div class='gd-ex-line'>・<span class='gd-jp'>明日までにお願いします。</span>（麻煩明天之前給我）</div><div class='gd-sec'><span class='gd-tag'>自己的目標</span>給自己設一個期限。</div><div class='gd-ex-line'>・<span class='gd-jp'>5時までに駅に着きたい。</span>（我想在 5 點前到車站）</div><div class='gd-ex-line'>・<span class='gd-jp'>夏までに5キロやせたい。</span>（我想在夏天之前瘦 5 公斤）</div><div class='gd-h'>怎麼接</div><div class='gd-sec'><b>時間、日子、事件</b>直接加までに：<br><span class='gd-pair'><span class='gd-jp'>3時</span> → <span class='gd-jp'>3時までに</span></span><span class='gd-pair'><span class='gd-jp'>試験</span> → <span class='gd-jp'>試験までに</span></span><br><b>動詞</b>用原本字典裡的樣子（辭書形）加までに，意思是「在～發生之前」：<br><span class='gd-pair'><span class='gd-jp'>帰る</span> → <span class='gd-jp'>帰るまでに</span></span></div><div class='gd-ex-line'>・<span class='gd-jp'>母が帰るまでに部屋を片付けます。</span>（我要在媽媽回來之前把房間整理好）</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'>只差一個「に」，意思差很多。<br><b>まで</b>＝動作<b>一直持續</b>到那個時間才停。<br><b>までに</b>＝在那個時間<b>之前做好</b>一件事，做完就結束了。</div><div class='gd-ex-line'>・<span class='gd-jp'>5時まで待ちます。</span>（我等到 5 點：從現在一直等，等到 5 點）</div><div class='gd-ex-line'>・<span class='gd-jp'>5時までに来てください。</span>（請在 5 點之前來：4 點來、4 點半來都可以）</div><div class='gd-ex-line'>・<span class='gd-jp'>10時まで勉強します。</span>（我念書念到 10 點）</div><div class='gd-ex-line'>・<span class='gd-jp'>10時までにお風呂に入ります。</span>（我 10 點前會去洗澡）</div><div class='gd-warn'>判斷小訣竅：中文能說「一直～到…」就用<b>まで</b>；能說「最晚…之前要～好」就用<b>までに</b>。</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・表示「一直持續做到那個時間」時（像等到 5 點、念書念到 10 點），要用まで，不能用までに。例如<span class='gd-jp'>5時までに待ちます</span>是錯的，要說<span class='gd-jp'>5時まで待ちます</span>。但如果是「在某時間前先做好」，就可以用までに，像<span class='gd-jp'>試験までに勉強しておきます</span>（考試前先把書念好），日本人很常講。<br>・<span class='gd-jp'>金曜日までに</span>通常包含星期五當天，週五交也算準時，不是一定要週四交。<br>・前面接動詞要用辭書形：說<span class='gd-jp'>日本に来るまでに</span>，不會說「来たまでに」。</div><div class='gd-h'>學會之後可以接著學</div><div class='gd-sec'>後面加「は」變成<span class='gd-jp'>までには</span>，語氣變成「至少在～之前」：<span class='gd-jp'>夜までには帰ります。</span>（最晚晚上前一定會回來）</div>",
  "n4-4": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「AはBより～」就是中文的<b>「A比B～」</b>。<span class='gd-jp'>東京は大阪より人が多い。</span>就是「東京人比大阪多」。<br>最大的差別在<b>順序</b>：中文是「比」放在B前面，日文的<span class='gd-jp'>より</span>是放在B<b>後面</b>，有點像中文的「比起B」倒過來黏在B身上。</div><div class='gd-h'>怎麼接</div><div class='gd-sec'>主角A加<span class='gd-jp'>は</span>，被比的B加<span class='gd-jp'>より</span>，最後放形容詞。<br><span class='gd-tag'>い形容詞</span>後面直接加です。</div><div class='gd-ex-line'>・<span class='gd-jp'>今日は昨日より暑いです。</span>（今天比昨天熱）</div><div class='gd-sec'><span class='gd-tag'>な形容詞</span>後面直接加です，朋友間講就換成だ或什麼都不加。</div><div class='gd-ex-line'>・<span class='gd-jp'>電車はバスより便利です。</span>（電車比公車方便）</div><div class='gd-sec'><span class='gd-tag'>比某一點</span>要比的是「哪一方面」，就用「～が＋形容詞」。</div><div class='gd-ex-line'>・<span class='gd-jp'>兄は私より背が高いです。</span>（哥哥比我高）</div><div class='gd-ex-line'>・<span class='gd-jp'>姉は私より料理が上手です。</span>（姊姊煮菜比我厲害）</div><div class='gd-sec'><span class='gd-tag'>也能接動作</span>後面不一定是形容詞，也可以是「怎麼做」。</div><div class='gd-ex-line'>・<span class='gd-jp'>弟は私よりよく食べます。</span>（弟弟比我會吃）</div><div class='gd-sec'>你也會聽到<span class='gd-jp'>よりも</span>，意思一樣，只是語氣比較強調。</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・<b>より黏在誰後面，誰就是被比下去的那個。</b>照中文順序直接翻很容易放錯：<span class='gd-jp'>東京より大阪は人が多い</span>變成「大阪人比東京多」，意思整個反過來。<br>・形容詞<b>不用變形</b>，也不用硬加「更」。中文常說「更高」，但日文<span class='gd-jp'>高いです</span>就夠了。加上<span class='gd-jp'>もっと</span>反而會變成「兩個都很高，A又更高」的意思。<br>・比哪一方面要用<span class='gd-jp'>が</span>：是<span class='gd-jp'>背が高い</span>、<span class='gd-jp'>気温が高い</span>，不要寫成を。<br>・想說「A沒有B那麼～」時，日本人通常用<span class='gd-jp'>ほど…ない</span>，比較少說「より～くない」。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'>同樣是東京跟大阪比人數：<br><b>AはBより</b>＝在介紹A這個主角，順便拿B來比：<span class='gd-jp'>東京は大阪より人が多いです。</span>（東京人比大阪多）<br><b>BよりAのほうが</b>＝兩個擺在一起，<b>選出A</b>，常拿來回答「哪一個比較～？」：<span class='gd-jp'>大阪より東京のほうが人が多いです。</span>（比起大阪，東京人比較多）<br><b>BほどAない</b>＝反過來講「沒那麼～」：<span class='gd-jp'>大阪は東京ほど人が多くないです。</span>（大阪人沒有東京那麼多）</div><div class='gd-warn'>判斷小訣竅：單純描述「A比B～」用<span class='gd-jp'>AはBより</span>；要從兩個裡面挑一個用<span class='gd-jp'>のほうが</span>；要說「沒那麼～」用<span class='gd-jp'>ほど…ない</span>。</div><div class='gd-h'>學會之後可以接著學</div><div class='gd-sec'>問別人「哪一個比較～？」：<span class='gd-jp'>電車とバスとどちらが便利ですか。</span>（電車跟公車哪個方便？）回答就用<span class='gd-jp'>～より…ほうが</span>。三個以上要選第一名，就接著學<span class='gd-jp'>～でいちばん</span>。</div>",
  "n4-6": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「〜方」就是中文的<b>「～法」</b>：寫法、念法、用法、吃法。把一個動作變成「做這件事的方法」，問人「這個怎麼用」「那裡怎麼去」的時候超常用。</div><div class='gd-h'>怎麼接</div><div class='gd-sec'>先把動詞變成ます形，<b>把ます拿掉</b>，再加上<b>方（かた）</b>。<br><b>第一類（五段動詞）、第二類（一段動詞）</b>都是同一個做法：<br><span class='gd-pair'><span class='gd-jp'>書きます</span> → 把ます拿掉 → <span class='gd-jp'>書き方</span></span>（寫法）<br><span class='gd-pair'><span class='gd-jp'>読みます</span> → <span class='gd-jp'>読み方</span></span>（念法）<span class='gd-pair'><span class='gd-jp'>使います</span> → <span class='gd-jp'>使い方</span></span>（用法）<br><span class='gd-pair'><span class='gd-jp'>食べます</span> → <span class='gd-jp'>食べ方</span></span>（吃法）<span class='gd-pair'><span class='gd-jp'>見ます</span> → <span class='gd-jp'>見方</span></span>（看法）</div><div class='gd-sec'><b>第三類（する・来る）要另外記</b>：<br>・<span class='gd-jp'>する</span>要變成<span class='gd-jp'>仕方</span>（しかた）。<br>・「名詞＋する」的動詞，要說<b>名詞＋の＋仕方</b>：<span class='gd-pair'><span class='gd-jp'>勉強する</span> → <span class='gd-jp'>勉強の仕方</span></span><span class='gd-pair'><span class='gd-jp'>掃除する</span> → <span class='gd-jp'>掃除の仕方</span></span><br>・<span class='gd-jp'>来る</span>是<span class='gd-jp'>来方</span>（きかた），不過平常比較常聽到<span class='gd-jp'>行き方</span>。</div><div class='gd-h'>最常聽到的樣子</div><div class='gd-sec'><span class='gd-tag'>問方法</span>不知道怎麼做，請別人教你。</div><div class='gd-ex-line'>・<span class='gd-jp'>この漢字の読み方を教えてください。</span>（請告訴我這個漢字怎麼念）</div><div class='gd-ex-line'>・<span class='gd-jp'>駅への行き方がわかりません。</span>（我不知道怎麼去車站）</div><div class='gd-ex-line'>・<span class='gd-jp'>日本語の勉強の仕方を教えてください。</span>（請教我怎麼學日文）</div><div class='gd-sec'><span class='gd-tag'>講某人的方式</span>不一定是「方法」，也可以是一個人做這件事的<b>樣子、習慣</b>。</div><div class='gd-ex-line'>・<span class='gd-jp'>彼は話し方がやさしいです。</span>（他講話的方式很溫柔）</div><div class='gd-ex-line'>・<span class='gd-jp'>箸の持ち方がきれいですね。</span>（你拿筷子的樣子很標準耶）</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・<b>を要換成の</b>。「〜方」已經變成名詞了，前面不能再用を：<span class='gd-pair'><span class='gd-jp'>本を読む</span> → <span class='gd-jp'>本の読み方</span></span>，不是「本を読み方」。<br>・「に／へ」通常變成「への」：<span class='gd-pair'><span class='gd-jp'>駅に行く</span> → <span class='gd-jp'>駅への行き方</span></span>。<br>・既然是名詞，後面就接<span class='gd-jp'>が</span>、<span class='gd-jp'>を</span>：<span class='gd-jp'>使い方がわかりません</span>、<span class='gd-jp'>書き方を教えてください</span>。<br>・這裡的方念<b>かた</b>，不會變成がた：<span class='gd-jp'>書き方</span>念かきかた。<br>・勉強する、掃除する這種動詞，不要照公式做出「勉強し方」，要說<span class='gd-jp'>勉強の仕方</span>。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'>同一個漢字「方」，在<span class='gd-jp'>〜ほうがいいです</span>裡念<b>ほう</b>，意思完全不同。<br><span class='gd-jp'>書き方を教えてください。</span>（請教我怎麼寫：方法）<br><span class='gd-jp'>名前を書いたほうがいいです。</span>（最好把名字寫上去：建議）</div><div class='gd-warn'>判斷小訣竅：前面是「ます形把ます拿掉」（書き、読み）就念かた＝～法；前面是た形、ない形或辭書形（書いた、書かない）就念ほう＝比較、建議。</div><div class='gd-h'>學會之後可以接著學</div><div class='gd-sec'>「〜やすい・〜にくい」也是ます形把ます拿掉再接，可以順便一起記：<span class='gd-jp'>このペンは書きやすいです。</span>（這支筆很好寫）</div>",
  "n4-9": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「〜ことができます」就是中文的<b>「會～」「可以～」「能～」</b>。做法很簡單：把動作加上「こと」變成「這件事」，後面再說「辦得到（できます）」。</div><div class='gd-h'>什麼時候用</div><div class='gd-sec'><span class='gd-tag'>能力</span>你學過、練過，所以會做。</div><div class='gd-ex-line'>・<span class='gd-jp'>私は日本語を話すことができます。</span>（我會說日文）</div><div class='gd-ex-line'>・<span class='gd-jp'>ピアノを弾くことができます。</span>（我會彈鋼琴）</div><div class='gd-sec'><span class='gd-tag'>環境允許</span>不是你會不會，是那個地方、那個規定讓你可以做。</div><div class='gd-ex-line'>・<span class='gd-jp'>この図書館ではWi-Fiを使うことができます。</span>（這間圖書館可以用 Wi-Fi）</div><div class='gd-ex-line'>・<span class='gd-jp'>このカードはコンビニでも使うことができます。</span>（這張卡在便利商店也能用）</div><div class='gd-h'>怎麼接</div><div class='gd-sec'>動詞用<b>辭書形</b>（字典上查到的那個樣子），後面加「ことができます」。三類動詞都一樣，不用另外變化。<br>如果你只記得ます形，就先變回辭書形：<span class='gd-pair'><span class='gd-jp'>書きます</span> → <span class='gd-jp'>書く</span> → <span class='gd-jp'>書くことができます</span></span><br><span class='gd-pair'><span class='gd-jp'>食べる</span> → <span class='gd-jp'>食べることができます</span></span><span class='gd-pair'><span class='gd-jp'>する</span> → <span class='gd-jp'>することができます</span></span><span class='gd-pair'><span class='gd-jp'>来る</span> → <span class='gd-jp'>来ることができます</span>（くる）</span></div><div class='gd-sec'>「不會、不能」把ます換成ません；「（那時）做到了」換成ました：<br><span class='gd-jp'>漢字を書くことができません。</span>（我不會寫漢字）<br><span class='gd-jp'>昨日はゆっくり休むことができました。</span>（昨天有好好休息到）</div><div class='gd-sec'>表示<b>技能、運動、語言</b>這類的名詞，也可以直接接「ができます」：<span class='gd-jp'>日本語ができます。</span>（我會日文）、<span class='gd-jp'>テニスができます。</span>（我會打網球）<br>一般名詞不能這樣接，例如不說「電車ができます」，要說<span class='gd-jp'>電車に乗ることができます</span>。</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・前面一定是辭書形，不能直接用ます形：不說「行きますことができます」，是<span class='gd-jp'>行くことができます</span>。<br>・原本的「を」照樣保留：<span class='gd-jp'>ピアノを弾くことができます</span>。不用改成が。<br>・中文的「會」也有「將會」的意思，這個不能用ことができます。「明天會下雨」要說<span class='gd-jp'>明日は雨が降るでしょう</span>或<span class='gd-jp'>雨が降るかもしれません</span>。<br>・<span class='gd-jp'>わかる</span>本身就帶有「懂得、能理解」的意思，不要再加ことができます：直接說<span class='gd-jp'>日本語がわかります</span>。<br>・想當場問「我可以～嗎？」徵求對方同意，一般用<span class='gd-jp'>〜てもいいですか</span>比較自然。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'><b>可能形</b>（話せる、書ける）意思跟ことができます幾乎一樣：<br><span class='gd-jp'>日本語を話すことができます。</span>（我會說日文：比較正式、比較硬）<br><span class='gd-jp'>日本語が話せます。</span>（我會說日文：日常講話比較常用）<br>公告、說明書、正式自我介紹常看到ことができます；跟朋友聊天多半用可能形。還不會變可能形的時候，用ことができます一定不會錯。</div><div class='gd-sec'><b>〜てもいいです</b>是「（我）允許你做」：<br><span class='gd-jp'>ここで写真を撮ることができます。</span>（這裡可以拍照：介紹規定、說明狀況）<br><span class='gd-jp'>ここで写真を撮ってもいいですよ。</span>（你可以在這裡拍喔：說話的人准許你）</div><div class='gd-warn'>判斷小訣竅：講「會不會、能不能」用ことができます或可能形；講「准不准、給不給做」用てもいいです。</div><div class='gd-h'>學會之後可以接著學</div><div class='gd-sec'>同樣意思更口語的說法：可能形，例如<span class='gd-pair'><span class='gd-jp'>話す</span> → <span class='gd-jp'>話せる</span></span>。</div>",
  "n4-23": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「〜てみる」就是中文的<b>「～看看」</b>：吃吃看、穿穿看、問問看。還不知道結果，先做一下試試，看會怎樣。用法是動詞的て形後面加「みる」，禮貌一點就說「みます」。</div><div class='gd-h'>什麼時候用</div><div class='gd-sec'><span class='gd-tag'>試試看</span>第一次做、不知道結果，先試一下。</div><div class='gd-ex-line'>・<span class='gd-jp'>納豆を食べてみた。</span>（我吃吃看了納豆）</div><div class='gd-ex-line'>・<span class='gd-jp'>わからないから、駅員さんに聞いてみます。</span>（不知道，我去問問看站務員）</div><div class='gd-sec'><span class='gd-tag'>試穿・試用</span>在店裡最常講，後面接「〜てもいいですか」問可不可以。</div><div class='gd-ex-line'>・<span class='gd-jp'>この服、着てみてもいいですか。</span>（這件衣服可以試穿嗎）</div><div class='gd-sec'><span class='gd-tag'>請對方試試</span>「〜てみてください」＝請你～看看。</div><div class='gd-ex-line'>・<span class='gd-jp'>この靴、はいてみてください。</span>（這雙鞋請穿穿看）</div><div class='gd-sec'><span class='gd-tag'>想試試</span>「〜てみたい」＝想～看看，講沒做過、很好奇的事。</div><div class='gd-ex-line'>・<span class='gd-jp'>一度、富士山に登ってみたい。</span>（想爬一次富士山看看）</div><div class='gd-h'>怎麼接</div><div class='gd-sec'>先把動詞變成て形，再加「みる」。<br><span class='gd-pair'><span class='gd-jp'>行く</span> → <span class='gd-jp'>行って</span> → <span class='gd-jp'>行ってみる</span></span><br><span class='gd-pair'><span class='gd-jp'>食べる</span> → <span class='gd-jp'>食べて</span> → <span class='gd-jp'>食べてみる</span></span><br><span class='gd-pair'><span class='gd-jp'>する</span> → <span class='gd-jp'>して</span> → <span class='gd-jp'>してみる</span></span><br>「みる」本身是<b>第二類（一段動詞）</b>，所以後面照第二類的規則變：把る拿掉再接東西。<br><span class='gd-pair'><span class='gd-jp'>やってみる</span> → <span class='gd-jp'>やってみます</span></span><span class='gd-pair'><span class='gd-jp'>やってみた</span></span><span class='gd-pair'><span class='gd-jp'>やってみたい</span></span><span class='gd-pair'><span class='gd-jp'>やってみて</span></span></div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・這個「みる」一般<b>寫平假名</b>，不寫成見る。它已經不是「用眼睛看」的意思了，所以<span class='gd-jp'>聞いてみる</span>是「問問看」，跟眼睛沒關係。<br>・真的要說「看看」，就是<span class='gd-jp'>見てみる</span>，前面那個見る是「看」，後面那個みる是「試試」，不是重複寫錯。<br>・只能用在<b>人自己決定要做</b>的事。下雨、生病這種控制不了的事不能加てみる，不能說「雨が降ってみる」。<br>・<span class='gd-jp'>試してみる</span>雖然兩個都有「試」，但日本人真的這樣講，很自然。<br>・在店裡說<span class='gd-jp'>ちょっと考えてみます</span>（我再考慮看看），很多時候是委婉的「先不要」，聽到別太期待對方會回來買。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'><b>てみた</b>＝重點在「<b>試了</b>」，通常在講那一次的事、接著說感想：<br><span class='gd-jp'>納豆を食べてみた。けっこうおいしかった。</span>（我吃吃看納豆，結果還滿好吃的）<br><b>たことがある</b>＝重點在「<b>有沒有這個經驗</b>」：<br><span class='gd-jp'>納豆を食べたことがある。</span>（我吃過納豆）</div><div class='gd-sec'><b>たい</b>＝單純「想做」：<span class='gd-jp'>沖縄に行きたい。</span>（我想去沖繩）<br><b>てみたい</b>＝沒做過、好奇，想「試一次看看」：<span class='gd-jp'>沖縄に行ってみたい。</span>（我想去沖繩看看）</div><div class='gd-warn'>判斷小訣竅：中文講得出「～看看」就用てみる；講「～過」用たことがある；只是「想～」用たい，帶點好奇、想體驗一次就用てみたい。</div><div class='gd-h'>學會之後可以接著學</div><div class='gd-sec'>同樣是「て形＋一個動詞」的組合，接著可以學<span class='gd-jp'>〜てしまう</span>（不小心～了／～完了）、<span class='gd-jp'>〜ておく</span>（先～好），接法都一樣，只是意思不同。</div>",
  "n4-25": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「〜ておきます」就是中文的<b>「先把～弄好」</b>。出門旅行前先把票買好、朋友來之前先把啤酒冰好，這種「為了等一下、為了之後，現在先做」的動作，日文就用「〜ておく」。另外它也可以表示<b>「就那樣放著，不要動」</b>。</div><div class='gd-h'>什麼時候用</div><div class='gd-sec'><span class='gd-tag'>事先準備</span>為了之後的某件事，現在先做好。最常用的就是這個。</div><div class='gd-ex-line'>・<span class='gd-jp'>出張の前に切符を買っておきます。</span>（出差前先把票買好）</div><div class='gd-ex-line'>・<span class='gd-jp'>会議の前に資料を読んでおきます。</span>（開會前我會先把資料看過）</div><div class='gd-ex-line'>・<span class='gd-jp'>ホテルはもう予約しておきました。</span>（飯店我已經先訂好了）</div><div class='gd-sec'><span class='gd-tag'>維持原狀</span>刻意讓東西保持現在的樣子，不要去動它。</div><div class='gd-ex-line'>・<span class='gd-jp'>窓を開けておいてください。</span>（請讓窗戶開著）</div><div class='gd-ex-line'>・<span class='gd-jp'>そのままにしておいてください。</span>（就那樣放著，不用動）</div><div class='gd-h'>怎麼接</div><div class='gd-sec'>先把動詞變成て形，後面加「おく」（禮貌一點就是「おきます」）。<br><span class='gd-pair'><span class='gd-jp'>買う</span> → <span class='gd-jp'>買って</span> → <span class='gd-jp'>買っておく</span></span><br><span class='gd-pair'><span class='gd-jp'>読む</span> → <span class='gd-jp'>読んで</span> → <span class='gd-jp'>読んでおく</span></span><br><span class='gd-pair'><span class='gd-jp'>食べる</span> → <span class='gd-jp'>食べて</span> → <span class='gd-jp'>食べておく</span></span><br><span class='gd-pair'><span class='gd-jp'>する</span> → <span class='gd-jp'>して</span> → <span class='gd-jp'>しておく</span></span></div><div class='gd-sec'>後面的「おく」自己也會變化，跟第一類（五段動詞）的<span class='gd-jp'>置く</span>變法一樣：<br>過去：<span class='gd-jp'>買っておきました</span>（已經先買好了）<br>拜託別人：<span class='gd-jp'>買っておいてください</span>（請先幫我買好）</div><div class='gd-h'>最常聽到的樣子</div><div class='gd-sec'><span class='gd-tag'>口語縮短</span>跟朋友講話時，「ておく」常常縮成「とく」，「でおく」縮成「どく」：<br><span class='gd-pair'><span class='gd-jp'>買っておく</span> → <span class='gd-jp'>買っとく</span></span><br><span class='gd-pair'><span class='gd-jp'>置いておく</span> → <span class='gd-jp'>置いとく</span></span><br><span class='gd-pair'><span class='gd-jp'>読んでおく</span> → <span class='gd-jp'>読んどく</span></span><br>拜託朋友時的「ておいて」也會縮成「といて」：<br><span class='gd-pair'><span class='gd-jp'>言っておいて</span> → <span class='gd-jp'>言っといて</span></span></div><div class='gd-ex-line'>・<span class='gd-jp'>ビール、冷やしとくね。</span>（啤酒我先冰起來喔）</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・<span class='gd-jp'>置いておいてください</span>不是打錯字重複了。前面的<span class='gd-jp'>置いて</span>是「放」這個動作，後面的<span class='gd-jp'>おいて</span>是「先放著」的ておく，意思是「請先放著」。<br>・接在「ん」後面的て形是「で」，所以是<span class='gd-jp'>読んでおく</span>，不是読んておく。<br>・中文說「先買票」，日文只講<span class='gd-jp'>切符を買います</span>只是「買票」，沒有「事先準備好」的感覺，要加ておく才對味。<br>・縮短後的<span class='gd-jp'>買っとく</span>（先買好）跟<span class='gd-jp'>買っちゃう</span>（買下去了／不小心買了）長得像，意思完全不同，不要聽混。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'>「維持原狀」的ておく，跟「〜まま」都可以翻成「開著」，但感覺不一樣。同樣是窗戶開著：<br><b>ておく</b>＝<b>故意</b>讓它開著，有目的：<span class='gd-jp'>暑いから、窓を開けておきました。</span>（因為很熱，我刻意讓窗戶開著）<br><b>まま</b>＝沒改變狀態，就這樣接著做別的事，常用在忘記或不該這樣的情況：<span class='gd-jp'>窓を開けたまま出かけてしまった。</span>（窗戶沒關就出門了）</div><div class='gd-warn'>判斷小訣竅：有目的、是你決定讓它這樣的，用ておく；沒改變狀態，就這樣繼續下去（常常是沒注意到），用まま。</div><div class='gd-h'>學會之後可以接著學</div><div class='gd-sec'>同樣是「て形＋一個動詞」的組合，還有<span class='gd-jp'>〜てみる</span>（試試看）、<span class='gd-jp'>〜てしまう</span>（做完了／糟了），放在一起學，很快就會習慣這種接法。</div>",
  "n4-26": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「〜てくる」「〜ていく」很像中文的<b>「～過來」「～下去」</b>。「跑過來」是<span class='gd-jp'>走ってくる</span>，「帶過去」是<span class='gd-jp'>持っていく</span>。講時間也一樣：「冷起來了」用てくる，「一直做下去」用ていく。<br>先記一句：<b>くる＝往我這邊、一路到現在；いく＝離開我、從現在往後</b>。</div><div class='gd-h'>怎麼接</div><div class='gd-sec'>動詞先變成て形，後面接くる或いく。<br><span class='gd-pair'><span class='gd-jp'>降る</span> → <span class='gd-jp'>降って</span> → <span class='gd-jp'>降ってきた</span></span><br><span class='gd-pair'><span class='gd-jp'>持つ</span> → <span class='gd-jp'>持って</span> → <span class='gd-jp'>持っていきます</span></span><br>後面的くる照「来る」平常的變法：<span class='gd-jp'>てきます</span>、<span class='gd-jp'>てきました</span>、<span class='gd-jp'>てこない</span>。在這個句型裡多半直接寫平假名。</div><div class='gd-h'>什麼時候用</div><div class='gd-sec'><span class='gd-tag'>往這邊／往那邊</span>動作朝說話的人靠近用てくる，離開說話的人用ていく。</div><div class='gd-ex-line'>・<span class='gd-jp'>弟が走ってきた。</span>（弟弟跑過來了）</div><div class='gd-ex-line'>・<span class='gd-jp'>雨が降りそうだから、傘を持っていきます。</span>（好像要下雨，我帶傘去）</div><div class='gd-sec'><span class='gd-tag'>去一下就回來</span>てくる也可以是「去做完某件事，再回到這裡」。</div><div class='gd-ex-line'>・<span class='gd-jp'>ちょっと飲み物を買ってきます。</span>（我去買個飲料就回來）</div><div class='gd-sec'><span class='gd-tag'>一路變到現在</span>從以前到現在慢慢變化，通常用過去式<span class='gd-jp'>てきました</span>。</div><div class='gd-ex-line'>・<span class='gd-jp'>最近、日本語が面白くなってきました。</span>（最近覺得日文越來越有趣了）</div><div class='gd-sec'><span class='gd-tag'>從現在往後</span>從現在開始持續下去，或越來越～。</div><div class='gd-ex-line'>・<span class='gd-jp'>これからも日本語を勉強していきます。</span>（之後我也會繼續學日文下去）</div><div class='gd-sec'><span class='gd-tag'>冒出來、感覺到</span>某個變化開始出現，被你注意到了，像下雨、肚子餓、想睡。</div><div class='gd-ex-line'>・<span class='gd-jp'>あ、雨が降ってきた。</span>（啊，下起雨來了）</div><div class='gd-ex-line'>・<span class='gd-jp'>お腹がすいてきた。</span>（肚子開始餓了）</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・出門說的<span class='gd-jp'>行ってきます</span>就是「去了會再回來」，所以是「我出門了」的意思，不是「我去來」。<br>・來或去要看<b>說話的人在哪裡</b>。拿東西去對方家，中文常說「我帶過來給你」，日文通常說<span class='gd-jp'>持っていきます</span>，因為東西是離開你這邊。<br>・<span class='gd-jp'>雨が降ってきた</span>是「開始下雨了」，不是「雨朝我這邊飄過來」。<br>・<span class='gd-jp'>てきた</span>的「きた」念きた，否定<span class='gd-jp'>てこない</span>念こない。<br>・聊天時<span class='gd-jp'>ていく</span>常縮成<span class='gd-jp'>てく</span>，例如<span class='gd-jp'>持ってく</span>，這是口語的說法。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'>同樣講天氣變冷：<br>・<span class='gd-jp'>寒くなった。</span>（變冷了：只講結果）<br>・<span class='gd-jp'>寒くなってきた。</span>（漸漸冷起來了：感覺到一路在變）<br>・<span class='gd-jp'>これから寒くなっていく。</span>（接下來會越來越冷：看向之後）<br><br>同樣講開始下雨：<br>・<span class='gd-jp'>雨が降り始めた。</span>（雨開始下了：單純說開始）<br>・<span class='gd-jp'>雨が降ってきた。</span>（下起雨來了：帶著「我發現了」的感覺，抬頭看到下雨時最常這樣講）</div><div class='gd-warn'>判斷小訣竅：只講結果用「なった」；感覺「一路變過來」用「てきた」；眼光放在「接下來」用「ていく」。</div><div class='gd-h'>學會之後可以接著學</div><div class='gd-sec'>跟「ようになる」合起來，可以說能力慢慢養成：<span class='gd-jp'>日本語が少し話せるようになってきた。</span>（我漸漸可以講一點日文了）</div>",
  "n4-27": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>這三個就像中文的<b>「開始～」「一直～」「～完」</b>。把一個動作切成三段：剛開始、持續中、做完了。<br><span class='gd-jp'>読みはじめる</span>＝開始看<br><span class='gd-jp'>読み続ける</span>＝一直看、繼續看<br><span class='gd-jp'>読み終わる</span>＝看完</div><div class='gd-h'>怎麼接</div><div class='gd-sec'>先把動詞變成ます形，<b>把ます拿掉</b>，剩下的部分直接黏上<span class='gd-jp'>はじめる</span>、<span class='gd-jp'>続ける</span>或<span class='gd-jp'>終わる</span>。<br><span class='gd-pair'><span class='gd-jp'>読む</span> → <span class='gd-jp'>読みます</span></span> → 把ます拿掉 → <span class='gd-pair'><span class='gd-jp'>読み</span> → <span class='gd-jp'>読みはじめる</span></span><br><span class='gd-pair'><span class='gd-jp'>食べる</span> → <span class='gd-jp'>食べます</span></span> → 把ます拿掉 → <span class='gd-pair'><span class='gd-jp'>食べ</span> → <span class='gd-jp'>食べ続ける</span></span><br><span class='gd-pair'><span class='gd-jp'>勉強する</span> → <span class='gd-jp'>勉強します</span></span> → 把ます拿掉 → <span class='gd-pair'><span class='gd-jp'>勉強し</span> → <span class='gd-jp'>勉強し終わる</span></span></div><div class='gd-sec'>黏好之後，後面那個字照自己的規則變：<br><span class='gd-jp'>はじめる</span>、<span class='gd-jp'>続ける</span>是第二類（一段動詞）：<span class='gd-pair'><span class='gd-jp'>読みはじめる</span> → <span class='gd-jp'>読みはじめました</span></span><br><span class='gd-jp'>終わる</span>是第一類（五段動詞）：<span class='gd-pair'><span class='gd-jp'>読み終わる</span> → <span class='gd-jp'>読み終わりました</span></span><br>「はじめる」寫漢字<span class='gd-jp'>始める</span>也可以，接在動詞後面時常寫成平假名。</div><div class='gd-h'>什麼時候用</div><div class='gd-sec'><span class='gd-tag'>はじめる：開始</span>一個動作從這一刻開始了。人做的事、天氣自然變化都可以用。</div><div class='gd-ex-line'>・<span class='gd-jp'>去年から日本語を勉強しはじめました。</span>（我從去年開始學日文）</div><div class='gd-ex-line'>・<span class='gd-jp'>あ、雨が降りはじめた。</span>（啊，開始下雨了）</div><div class='gd-sec'><span class='gd-tag'>続ける：一直、繼續</span>動作沒有停下來，一直做下去。常跟「ずっと」或時間長度一起出現。</div><div class='gd-ex-line'>・<span class='gd-jp'>彼は1時間も話し続けた。</span>（他整整講了一個小時）</div><div class='gd-ex-line'>・<span class='gd-jp'>これからも日本語を勉強し続けたいです。</span>（以後我也想繼續學日文）</div><div class='gd-sec'><span class='gd-tag'>終わる：做完</span>一件有終點的事做到最後了，像看完一本書、吃完一頓飯。</div><div class='gd-ex-line'>・<span class='gd-jp'>この本、やっと読み終わった。</span>（這本書終於看完了）</div><div class='gd-ex-line'>・<span class='gd-jp'>食べ終わったら、お皿を洗ってね。</span>（吃完之後把盤子洗一洗喔）</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・一定要接<b>ます形把ます拿掉</b>的樣子。<span class='gd-jp'>読むはじめる</span>、<span class='gd-jp'>読んではじめる</span>都是錯的，要說<span class='gd-jp'>読みはじめる</span>。<br>・就算主角是雨、風這種自然現象，還是用<span class='gd-jp'>はじめる</span>：<span class='gd-jp'>雨が降りはじめた</span>，不會說「降りはじまった」。<br>・<span class='gd-jp'>終わる</span>用在有「做完」這個終點的動作，像讀、吃、寫、看。雨停了不說「降り終わった」，要用<span class='gd-jp'>雨がやんだ</span>。<br>・<span class='gd-jp'>終わる</span>是第一類，ます形是<span class='gd-jp'>終わります</span>；<span class='gd-jp'>はじめる</span>、<span class='gd-jp'>続ける</span>是第二類，是<span class='gd-jp'>はじめます</span>、<span class='gd-jp'>続けます</span>，不要混在一起變。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'><b>〜ている 和 〜続けている</b><br><span class='gd-jp'>子どもが泣いている。</span>（小孩在哭）：只是描述現在正在哭。<br><span class='gd-jp'>子どもがずっと泣き続けている。</span>（小孩一直哭個不停）：強調哭了很久還沒停。</div><div class='gd-sec'><b>〜終わる 和 〜てしまう</b><br>中文都可能翻成「吃完了」，但重點不一樣。<br><span class='gd-jp'>ケーキを食べ終わった。</span>（蛋糕吃完了）：只是說吃這個動作結束了，口氣中性。<br><span class='gd-jp'>弟のケーキを食べてしまった。</span>（我把弟弟的蛋糕吃掉了）：帶有「吃光了」或「糟糕、不小心」的感覺。</div><div class='gd-warn'>判斷小訣竅：只是在說「正在做」用ている，想強調「一直沒停」用続ける；單純說「做完了」用終わる，帶有「吃光了」或「糟了」的心情用てしまう。</div><div class='gd-h'>學會之後可以接著學</div><div class='gd-sec'>想說「正要開始」「正在做」「剛做完」這種更細的時間點，可以接著學<span class='gd-jp'>〜ところです</span>：<span class='gd-jp'>今から食べるところです。</span>（我正要開始吃）</div>",
  "n4-29": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「〜たばかりです」就是中文的<b>「才剛～而已」</b>。重點是說話的人<b>覺得</b>「這件事還沒過多久」。像你跟同事說「我才剛進公司」，可能已經進去三個月了，但你心裡覺得還很新，就可以這樣講。</div><div class='gd-h'>怎麼接</div><div class='gd-sec'>動詞的<b>た形</b>後面加「ばかりです」。<br>た形跟て形變法一樣，把「て」換成「た」、「で」換成「だ」就好。<br><span class='gd-pair'><span class='gd-jp'>入って</span> → <span class='gd-jp'>入った</span> → <span class='gd-jp'>入ったばかりです</span></span><br><span class='gd-pair'><span class='gd-jp'>飲んで</span> → <span class='gd-jp'>飲んだ</span> → <span class='gd-jp'>飲んだばかりです</span></span><br><span class='gd-pair'><span class='gd-jp'>食べて</span> → <span class='gd-jp'>食べた</span> → <span class='gd-jp'>食べたばかりです</span></span><br><span class='gd-pair'><span class='gd-jp'>来て</span> → <span class='gd-jp'>来た</span>（きた）→ <span class='gd-jp'>来たばかりです</span></span><br>跟朋友講就把「です」拿掉，或換成「だ」：<span class='gd-jp'>来たばかりだよ。</span></div><div class='gd-h'>什麼時候用</div><div class='gd-sec'><span class='gd-tag'>真的剛剛</span>幾分鐘、幾小時前的事。</div><div class='gd-ex-line'>・<span class='gd-jp'>さっきご飯を食べたばかりです。</span>（我剛剛才吃過飯）</div><div class='gd-sec'><span class='gd-tag'>心裡覺得還很新</span>實際上過了好幾個月甚至一年，但你覺得還沒多久。</div><div class='gd-ex-line'>・<span class='gd-jp'>去年大学を卒業したばかりです。</span>（我去年才剛大學畢業）</div><div class='gd-h'>最常聽到的樣子</div><div class='gd-sec'><span class='gd-tag'>ばかりの＋名詞</span>「剛～的東西」。</div><div class='gd-ex-line'>・<span class='gd-jp'>買ったばかりの傘をなくしました。</span>（我把剛買的傘弄丟了）</div><div class='gd-sec'><span class='gd-tag'>ばかりで</span>「因為才剛～，所以…」，常拿來解釋自己還不熟。</div><div class='gd-ex-line'>・<span class='gd-jp'>日本に来たばかりで、まだよくわかりません。</span>（我才剛來日本，還不太清楚）</div><div class='gd-sec'><span class='gd-tag'>ばかりなのに</span>「明明才剛～」，帶點不甘心、抱怨。</div><div class='gd-ex-line'>・<span class='gd-jp'>昨日洗ったばかりなのに、もう汚れた。</span>（明明昨天才剛洗，已經髒了）</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・後面接名詞要加<b>の</b>：是<span class='gd-jp'>買ったばかりの靴</span>，不是「買ったばかり靴」。<br>・一定要用<b>た形</b>。<span class='gd-jp'>食べたばかり</span>是「剛吃完」，<span class='gd-jp'>食べてばかり</span>是「一直在吃、光是吃」，意思差很多。<br>・只能講已經發生的事。「正要去」「等一下才要做」不能用它。<br>・朋友之間常講成<b>ばっか</b>：<span class='gd-jp'>来たばっかだよ。</span>（我才剛到啦）對長輩不要這樣講。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'><b>たところです</b>（n4-28）也是「剛～」，但它講的是<b>客觀上就在剛剛那一刻</b>，通常是幾分鐘內的事。<b>たばかりです</b>看的是你<b>心裡的感覺</b>，時間可長可短。<br>很近的事兩個都可以：<br>・<span class='gd-jp'>今、家に着いたところです。</span>（我現在剛到家）<br>・<span class='gd-jp'>今、家に着いたばかりです。</span>（我才剛到家而已）<br>時間拉長，就只能用ばかり：<br>・<span class='gd-jp'>先月、日本に来たばかりです。</span>（我上個月才剛來日本）○<br>・「先月、日本に来たところです」×</div><div class='gd-warn'>判斷小訣竅：前面出現「先月」「去年」這種比較久的時間，用ばかり；「現在剛好剛弄完」用ところ也可以。</div><div class='gd-h'>學會之後可以接著學</div><div class='gd-sec'>同樣用「ばかり」，但意思是「光是～、老是～」的 n4-49：<span class='gd-jp'>弟はゲームばかりしている。</span>（我弟老是在打電動）</div>",
  "n4-37": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「BよりAのほうが～」就是中文的<b>「比起B，A比較～」</b>。把兩樣東西放在一起比，挑出「比較～」的那一邊來講。</div><div class='gd-ex-line'>・<span class='gd-jp'>バスより電車のほうが速いです。</span>（比起公車，電車比較快）</div><div class='gd-h'>怎麼接</div><div class='gd-sec'><span class='gd-tag'>名詞</span>名詞＋より、名詞＋<b>の</b>ほうが</div><div class='gd-ex-line'>・<span class='gd-jp'>夏より冬のほうが好きです。</span>（比起夏天，我比較喜歡冬天）</div><div class='gd-sec'><span class='gd-tag'>動詞</span>辭書形＋より、辭書形＋ほうが（中間<b>不加の</b>）</div><div class='gd-ex-line'>・<span class='gd-jp'>外で食べるより、家で作るほうが安いです。</span>（比起在外面吃，自己在家煮比較便宜）</div><div class='gd-sec'>ほうが後面可以接形容詞，也可以接<span class='gd-jp'>好きです</span>、<span class='gd-jp'>落ち着きます</span>這類講感覺的說法。<br>前後兩段也可以對調，意思不變，重點一樣在ほうが那一邊：<span class='gd-jp'>電車のほうがバスより速いです。</span></div><div class='gd-h'>最常聽到的樣子</div><div class='gd-sec'><span class='gd-tag'>回答「哪一個」</span>對方問「AとBと、どちらが～ですか」（A和B哪個比較～），回答用「Aのほうが～です」。這時候兩樣東西剛剛已經講過了，より通常省略。</div><div class='gd-ex-line'>・<span class='gd-jp'>電車とバスと、どちらが速いですか。</span>（電車和公車，哪個比較快？）</div><div class='gd-ex-line'>・<span class='gd-jp'>電車のほうが速いです。</span>（電車比較快）</div><div class='gd-ex-line'>・<span class='gd-jp'>コーヒーと紅茶と、どちらがいいですか。</span>（咖啡和紅茶，你要哪個？）</div><div class='gd-ex-line'>・<span class='gd-jp'>紅茶のほうがいいです。</span>（紅茶比較好）</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・より跟在<b>「比較基準」</b>後面，也就是「比較沒那麼～」的那一邊；ほうが跟在「比較～」的那一邊後面。不要用「誰贏誰輸」來想：<span class='gd-jp'>兄より弟のほうが下手です。</span>（比起哥哥，弟弟比較不會）這句より後面的哥哥，其實是比較厲害的人。<br>・中文說「電車比公車快」，「比」放在公車<b>前面</b>；日文的より要放在バス<b>後面</b>，寫成<span class='gd-jp'>バスより</span>。<br>・動詞直接接ほうが，不要加の：×<span class='gd-jp'>歩くのほうが</span>　○<span class='gd-jp'>歩くほうが</span>。名詞才要の：<span class='gd-jp'>電車のほうが</span>。<br>・ほう寫成漢字是<span class='gd-jp'>方</span>，但這裡念ほう，意思是「那一邊」，跟<span class='gd-jp'>読み方</span>的<span class='gd-jp'>方</span>（かた，方法）不一樣。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'><b>AはBより～</b>：單純描述A這個東西。<br><span class='gd-jp'>電車はバスより速いです。</span>（電車比公車快）<br><b>BよりAのほうが～</b>：兩個擺在一起，強調「是A這一邊」。<br><span class='gd-jp'>バスより電車のほうが速いです。</span>（比起公車，電車比較快）<br>這兩句意思幾乎一樣，但回答「どちら？」的時候要用<b>ほうが</b>。</div><div class='gd-sec'><b>動詞た形＋ほうがいい</b>：給建議，「最好～」。<br><span class='gd-jp'>疲れているなら、休んだほうがいいですよ。</span>（累的話最好休息一下喔）<br><span class='gd-jp'>タクシーより歩いたほうがいいですよ。</span>（與其搭計程車，不如用走的比較好喔）←有より，但用た形，還是在給建議<br><b>AよりBのほうがいい</b>：比較、說偏好。<br><span class='gd-jp'>コーヒーより紅茶のほうがいいです。</span>（比起咖啡，紅茶比較好）</div><div class='gd-warn'>判斷小訣竅：看動詞的形。「動詞た形＋ほうがいい」（<span class='gd-jp'>休んだほうがいい</span>）是給建議；「辭書形＋ほうが＋形容詞」（<span class='gd-jp'>歩くほうが早い</span>）或「名詞のほうが～」是在比較。注意「AよりBのほうがいいです」也是比較（B比較好）。</div><div class='gd-h'>學會之後可以接著學</div><div class='gd-sec'>反過來說「B沒有A那麼～」用「ほど…ない」：<span class='gd-jp'>バスは電車ほど速くないです。</span>（公車沒有電車那麼快）<br>三個以上比，要說「最～」就用「でいちばん」：<span class='gd-jp'>クラスで田中さんがいちばん背が高いです。</span>（班上田中最高）</div>",
  "n4-38": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「AはBほど～ない」就是中文的<b>「A 沒有 B 那麼～」</b>。順序跟中文幾乎一樣：<span class='gd-jp'>京都は東京ほど人が多くない</span>＝京都<b>沒有</b>東京<b>那麼</b>多人。<span class='gd-jp'>ほど</span>就是「那麼（那個程度）」，後面一定要接否定。</div><div class='gd-h'>怎麼接</div><div class='gd-sec'>A（主角）は B（拿來比的）ほど ＋ 否定的說法<br>否定的說法要先變好：</div><div class='gd-sec'><span class='gd-tag'>い形容詞</span>把最後的「い」換成「くない」。<br><span class='gd-pair'><span class='gd-jp'>高い</span> → い換成くない → <span class='gd-jp'>高くない</span></span><span class='gd-pair'><span class='gd-jp'>寒い</span> → <span class='gd-jp'>寒くない</span></span><br><b>例外：</b><span class='gd-pair'><span class='gd-jp'>いい</span> → <span class='gd-jp'>よくない</span></span>（不能說いくない）</div><div class='gd-ex-line'>・<span class='gd-jp'>この店の料理は前ほどよくない。</span>（這家店的菜沒有以前那麼好）</div><div class='gd-sec'><span class='gd-tag'>な形容詞</span>後面加「じゃない」，正式一點用「ではない」。<br><span class='gd-pair'><span class='gd-jp'>便利</span> → <span class='gd-jp'>便利じゃない</span></span></div><div class='gd-ex-line'>・<span class='gd-jp'>このアプリは前のほど便利じゃない。</span>（這個 App 沒有之前那個那麼方便）</div><div class='gd-sec'><span class='gd-tag'>動詞</span>用ない形就好。<br><span class='gd-pair'><span class='gd-jp'>食べる</span> → <span class='gd-jp'>食べない</span></span></div><div class='gd-ex-line'>・<span class='gd-jp'>私は兄ほど食べない。</span>（我沒有我哥那麼會吃）</div><div class='gd-sec'>要講得有禮貌，在後面加です就好：<span class='gd-pair'><span class='gd-jp'>寒くない</span> → <span class='gd-jp'>寒くないです</span></span></div><div class='gd-h'>最常聽到的樣子</div><div class='gd-sec'><span class='gd-tag'>思ったほど～ない</span>「沒有想像中那麼～」，日常超常用。</div><div class='gd-ex-line'>・<span class='gd-jp'>テストは思ったほど難しくなかった。</span>（考試沒有我想的那麼難）</div><div class='gd-sec'><span class='gd-tag'>前ほど～ない</span>「沒有以前那麼～」。</div><div class='gd-ex-line'>・<span class='gd-jp'>最近は前ほど忙しくないです。</span>（最近沒有以前那麼忙）</div><div class='gd-sec'><span class='gd-tag'>それほど～ない</span>不講B，直接說「沒那麼～」，回答別人時很好用。</div><div class='gd-ex-line'>・<span class='gd-jp'>日本語、難しい？</span>（日文難嗎？）</div><div class='gd-ex-line'>・<span class='gd-jp'>いや、それほど難しくないよ。</span>（不會，沒那麼難啦）</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・這個句型後面<b>一定是否定</b>。<span class='gd-jp'>京都は東京ほど人が多いです</span>是錯的，想說「比較多」要改用より。<br>・<span class='gd-jp'>ほど</span>前面放的是<b>比較厲害的那一邊</b>。<span class='gd-jp'>今日は昨日ほど暑くない</span>是說昨天比較熱，不要看反了。<br>・<span class='gd-jp'>いい</span>的否定是<span class='gd-jp'>よくない</span>，寫成いくない是錯的。<br>・它的口氣比較委婉：<span class='gd-jp'>私の部屋は田中さんの部屋ほど広くない</span>（沒有田中的房間那麼大）聽起來比直接說「比較小」客氣。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'>同一個情境：昨天很熱，今天稍微涼一點。<br><b>より（～ほうが）</b>＝直接說誰「比較」怎樣，可以接肯定：<br><span class='gd-jp'>昨日より今日のほうが涼しい。</span>（今天比昨天涼）<br><span class='gd-jp'>今日は昨日より涼しい。</span>（今天比昨天涼）<br><b>ほど～ない</b>＝說A「沒到B那個程度」，一定接否定：<br><span class='gd-jp'>今日は昨日ほど暑くない。</span>（今天沒有昨天那麼熱）</div><div class='gd-warn'>判斷小訣竅：中文想講「比」就用より；想講「沒有…那麼…」就用ほど＋否定。</div><div class='gd-h'>學會之後可以接著學</div><div class='gd-sec'>比完兩個，接著學「在一群裡面最～」：<span class='gd-jp'>クラスでいちばん背が高い。</span>（班上最高）</div>",
  "n4-39": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「〜でいちばん」就是中文的<b>「在～裡面最～」</b>。先用「で」把範圍圈起來（班上、日本、家裡），再用「いちばん」說「最」。像中文說「全班最高的是小明」，日文就是<span class='gd-jp'>クラスでいちばん背が高いのは田中さんです</span>。</div><div class='gd-h'>怎麼接</div><div class='gd-sec'>範圍＋<b>で</b>＋<b>いちばん</b>＋形容詞<br><span class='gd-pair'><span class='gd-jp'>高い山</span> → <span class='gd-jp'>日本でいちばん高い山</span></span>（日本最高的山）</div><div class='gd-ex-line'>・<span class='gd-jp'>富士山は日本でいちばん高い山です。</span>（富士山是日本最高的山）</div><div class='gd-ex-line'>・<span class='gd-jp'>クラスで田中さんがいちばん背が高いです。</span>（班上田中同學個子最高）</div><div class='gd-sec'>「いちばん」後面不只能接形容詞，也可以接動作，表示「最～地做」：</div><div class='gd-ex-line'>・<span class='gd-jp'>家族で父がいちばん早く起きます。</span>（家裡爸爸最早起）</div><div class='gd-sec'>如果範圍是「一類東西」或你先列出幾個選項，常用<b>の中で</b>（～之中）：</div><div class='gd-ex-line'>・<span class='gd-jp'>スポーツの中で、サッカーがいちばん好きです。</span>（運動裡面我最喜歡足球）</div><div class='gd-h'>最常聽到的樣子</div><div class='gd-sec'><span class='gd-tag'>問「最～的是哪個」</span>範圍＋で＋疑問詞＋が＋いちばん～ですか。疑問詞照對象換：東西用<span class='gd-jp'>何</span>（列出選項時用<span class='gd-jp'>どれ</span>）、人用<span class='gd-jp'>だれ</span>、地方用<span class='gd-jp'>どこ</span>、時間用<span class='gd-jp'>いつ</span>。</div><div class='gd-ex-line'>・<span class='gd-jp'>一年でいつがいちばん好きですか。</span>（一年裡你最喜歡什麼時候？）</div><div class='gd-ex-line'>・<span class='gd-jp'>夏がいちばん好きです。</span>（我最喜歡夏天）</div><div class='gd-ex-line'>・<span class='gd-jp'>日本でどこがいちばんよかったですか。</span>（在日本你覺得哪裡最棒？）</div><div class='gd-sec'><span class='gd-tag'>「最～的是X」</span>把答案放最後面，聽起來更有強調感：</div><div class='gd-ex-line'>・<span class='gd-jp'>家族でいちばん料理が上手なのは母です。</span>（家裡最會做菜的是媽媽）</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・範圍要用<b>で</b>，不能用に：是<span class='gd-jp'>日本でいちばん</span>，不是日本にいちばん。<br>・問句裡疑問詞後面要用<b>が</b>，不能用は：是<span class='gd-jp'>何がいちばん好きですか</span>，不是何はいちばん。回答時也習慣用が：<span class='gd-jp'>夏がいちばん好きです</span>。<br>・「好き」「上手」的對象一樣用が：<span class='gd-jp'>料理がいちばん上手です</span>，不是料理をいちばん上手。<br>・「いちばん」本身就是「最」，前面不要再加とても。<br>・漢字寫成<span class='gd-jp'>一番</span>也是同一個字，念法一樣。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'>關鍵在<b>比幾個</b>。同樣是問喜歡喝什麼：<br><b>兩個比</b>用「どちら」＋「ほうが」（〜より…ほうが）：<br><span class='gd-jp'>コーヒーと紅茶とどちらが好きですか。</span>（咖啡和紅茶你比較喜歡哪個？）<br><span class='gd-jp'>コーヒーのほうが好きです。</span>（我比較喜歡咖啡）<br><b>三個以上比</b>用「どれ／何」＋「いちばん」：<br><span class='gd-jp'>コーヒーと紅茶とジュースの中で、どれがいちばん好きですか。</span>（咖啡、紅茶、果汁裡你最喜歡哪個？）<br><span class='gd-jp'>コーヒーがいちばん好きです。</span>（我最喜歡咖啡）</div><div class='gd-warn'>判斷小訣竅：中文說「比較～」是兩個比，用ほうが；說「最～」是三個以上或整個範圍比，用いちばん。</div><div class='gd-h'>學會之後可以接著學</div><div class='gd-sec'>「今まで～た中で、いちばん…」＝我到目前為止～過最…的：<span class='gd-jp'>今まで食べた中で、これがいちばんおいしいです。</span>（這是我目前吃過最好吃的）</div>",
  "n4-40": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「〜と言います」就是中文的<b>「某某人說～」</b>。<span class='gd-jp'>言う</span>是「說」，前面的<span class='gd-jp'>と</span>是一個記號，告訴對方「說的內容到這裡為止」，作用跟中文的引號差不多。</div><div class='gd-h'>兩種講法：照原話講、用自己的話轉述</div><div class='gd-sec'><span class='gd-tag'>照原話講</span>把對方講的話一字不改放進「」，後面加<span class='gd-jp'>と言いました</span>。原話有ます就留著ます。</div><div class='gd-ex-line'>・<span class='gd-jp'>先生は「明日テストをします」と言いました。</span>（老師說：「明天要考試。」）</div><div class='gd-sec'><span class='gd-tag'>用自己的話轉述</span>不用「」，把內容改成<b>普通形</b>（就是沒有ます、です的朋友講法）再接<span class='gd-jp'>と</span>。<br><span class='gd-pair'><span class='gd-jp'>テストをします</span> → <span class='gd-jp'>テストをする</span></span><br><span class='gd-pair'><span class='gd-jp'>行きません</span> → <span class='gd-jp'>行かない</span></span></div><div class='gd-ex-line'>・<span class='gd-jp'>先生は明日テストをすると言いました。</span>（老師說明天要考試）</div><div class='gd-ex-line'>・<span class='gd-jp'>彼は行かないと言いました。</span>（他說他不去）</div><div class='gd-h'>怎麼接</div><div class='gd-sec'>轉述的時候，動詞、い形容詞用普通形直接接<span class='gd-jp'>と</span>；<b>名詞和な形容詞要多加一個「だ」</b>。<br><span class='gd-pair'><span class='gd-jp'>寒い</span> → <span class='gd-jp'>寒いと言いました</span></span><br><span class='gd-pair'><span class='gd-jp'>好きです</span> → <span class='gd-jp'>好きだと言いました</span></span><br><span class='gd-pair'><span class='gd-jp'>学生です</span> → <span class='gd-jp'>学生だと言いました</span></span></div><div class='gd-h'>最常聽到的樣子</div><div class='gd-sec'><span class='gd-tag'>と言っていました</span>幫別人傳話時最自然。意思是「他（之前）有說～喔」。</div><div class='gd-ex-line'>・<span class='gd-jp'>田中さんは今日は来ないと言っていました。</span>（田中先生說他今天不會來）</div><div class='gd-sec'><span class='gd-tag'>自我介紹</span>說自己的名字。</div><div class='gd-ex-line'>・<span class='gd-jp'>はじめまして、林と言います。</span>（初次見面，我姓林）</div><div class='gd-sec'><span class='gd-tag'>問怎麼說</span>學日文一定會用到。</div><div class='gd-ex-line'>・<span class='gd-jp'>これは日本語で何と言いますか。</span>（這個用日文怎麼說？）</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・引用說話的<b>內容</b>（一句話、一段話）後面用<b>と</b>，不是を：× <span class='gd-jp'>明日テストをするを言いました</span> → ○ <span class='gd-jp'>明日テストをすると言いました</span>。不過如果前面是名詞，像<span class='gd-jp'>名前を言う</span>（說名字）、<span class='gd-jp'>お礼を言う</span>（道謝），就用を，這兩種要分清楚。<br>・<span class='gd-jp'>言う</span>雖然寫成いう，實際念<b>ゆう</b>。<br>・轉述時名詞、な形容詞忘了加だ是最常見的錯：要說<span class='gd-jp'>雨だと言っていました</span>。<br>・轉述時「我」要換人：他原話「<span class='gd-jp'>私は行きません</span>」，你轉述就變成「他說<b>他</b>不去」，日文直接講<span class='gd-jp'>彼は行かないと言いました</span>就好，不用再放「私」。<br>・講老師、主管說的話，在正式場合會換成更尊敬的<span class='gd-jp'>おっしゃいました</span>，之後學尊敬語會再碰到。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'>同樣是轉述「田中先生不來」：<br><span class='gd-jp'>田中さんは来ないと言っていました。</span>（田中先生<b>親口說</b>他不來）<br><span class='gd-jp'>田中さんは来ないそうです。</span>（<b>聽說</b>田中先生不來）<br>「と言う」會清楚交代<b>是誰說的</b>；「そうです」只是「聽說」，消息可能是田中本人講的，也可能是別人傳的，重點不在誰說。</div><div class='gd-warn'>判斷小訣竅：想講「某某人說～」用と言う；只想講「聽說～」用そうです。</div><div class='gd-h'>學會之後可以接著學</div><div class='gd-sec'>把<span class='gd-jp'>言います</span>換成<span class='gd-jp'>思います</span>就是「我覺得～」：<span class='gd-jp'>明日は雨だと思います。</span>（我覺得明天會下雨）。接法完全一樣，也要加だ。<br>朋友之間傳話，常把<span class='gd-jp'>と言っていた</span>縮成<span class='gd-jp'>って</span>：<span class='gd-jp'>田中さん、来ないって。</span>（田中說他不來喔）</div>",
  "n4-41": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「〜と思います」就是中文的<b>「我覺得～」「我想～」</b>。說自己的看法、猜一件事會怎樣，都用它。日本人很愛用，就算很有把握，也常加一句と思います，讓話聽起來不會太硬。</div><div class='gd-h'>什麼時候用</div><div class='gd-sec'><span class='gd-tag'>說看法</span>對一件事的感想、評價。</div><div class='gd-ex-line'>・<span class='gd-jp'>このラーメンはおいしいと思います。</span>（我覺得這碗拉麵很好吃）</div><div class='gd-sec'><span class='gd-tag'>猜測</span>不是百分之百確定，但你覺得應該是這樣。</div><div class='gd-ex-line'>・<span class='gd-jp'>明日は雨が降ると思います。</span>（我覺得明天會下雨）</div><div class='gd-ex-line'>・<span class='gd-jp'>田中さんはもう帰ったと思います。</span>（我想田中先生應該已經回去了）</div><div class='gd-sec'><span class='gd-tag'>問對方意見</span>用「どう思いますか」，不用另外背句型。</div><div class='gd-ex-line'>・<span class='gd-jp'>この服、どう思いますか。</span>（你覺得這件衣服怎麼樣？）</div><div class='gd-h'>怎麼接</div><div class='gd-sec'>前面要放<b>普通形</b>，也就是沒有です、ます的說法（字典上的樣子、ない、た這些）。<br>動詞、い形容詞直接接：<br><span class='gd-pair'><span class='gd-jp'>行く</span> → <span class='gd-jp'>行くと思います</span></span><span class='gd-pair'><span class='gd-jp'>行かない</span> → <span class='gd-jp'>行かないと思います</span></span><span class='gd-pair'><span class='gd-jp'>高い</span> → <span class='gd-jp'>高いと思います</span></span><br>名詞、な形容詞要<b>先加だ</b>：<br><span class='gd-pair'><span class='gd-jp'>学生</span> → <span class='gd-jp'>学生だと思います</span></span><span class='gd-pair'><span class='gd-jp'>静か</span> → <span class='gd-jp'>静かだと思います</span></span><br>跟朋友講就把思います換成<b>思う</b>：<span class='gd-jp'>おいしいと思う。</span></div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・名詞、な形容詞忘了加だ：說<span class='gd-jp'>学生だと思います</span>，不是「学生と思います」。<br>・と的前面不放です、ます：說<span class='gd-jp'>おいしいと思います</span>，不是「おいしいですと思います」。禮貌程度靠最後的「思います」就夠了。<br>・「我覺得他不會來」，日文習慣把「不」放在前面：<span class='gd-jp'>彼は来ないと思います。</span>如果說<span class='gd-jp'>来るとは思いません</span>，是「我才不覺得他會來」，語氣強很多，像在反駁。<br>・「と思います」只用來講<b>我</b>自己怎麼想。講別人覺得怎樣，要用「と思っています」：<span class='gd-jp'>母は私がまだ子どもだと思っています。</span>（我媽覺得我還是小孩）</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'><b>行くと思います vs 行こうと思います</b>：只差一個字，意思差很多。</div><div class='gd-ex-line'>・<span class='gd-jp'>明日のパーティー、田中さんは行くと思います。</span>（明天的派對，我猜田中先生會去）</div><div class='gd-ex-line'>・<span class='gd-jp'>明日のパーティー、私も行こうと思います。</span>（明天的派對，我也打算去）</div><div class='gd-sec'>前面是普通形＝<b>猜</b>會怎樣；前面是意向形（行こう、食べよう）＝<b>我打算</b>做。</div><div class='gd-sec'><b>と思います vs かもしれません</b>：把握程度不同。</div><div class='gd-ex-line'>・<span class='gd-jp'>明日は雨が降ると思います。</span>（我覺得明天會下雨：滿有把握）</div><div class='gd-ex-line'>・<span class='gd-jp'>明日は雨が降るかもしれません。</span>（明天說不定會下雨：一半一半）</div><div class='gd-warn'>判斷小訣竅：「我覺得、我猜」用普通形＋と思います；「我打算」用意向形＋と思います；只是「說不定」就用かもしれません。</div><div class='gd-h'>學會之後可以接著學</div><div class='gd-sec'>把前面換成意向形，就是「我打算～」：<span class='gd-jp'>来年、日本へ行こうと思います。</span>（我打算明年去日本）</div>",
  "n4-42": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「〜ようと思います」就是中文的<b>「我打算～」「我想說要～」</b>。用來跟別人講你心裡已經有的計畫，像「我打算這週末打掃房間」。</div><div class='gd-ex-line'>・<span class='gd-jp'>週末は部屋を掃除しようと思います。</span>（我打算週末打掃房間）</div><div class='gd-h'>怎麼接</div><div class='gd-sec'>動詞先變成<b>意向形</b>（就是「〜よう」「〜こう」那個「～吧」的形），後面再加<span class='gd-jp'>と思います</span>。意向形怎麼變，請看 n4-51，這裡快速複習：<br><b>第一類（五段動詞）</b>：<span class='gd-pair'><span class='gd-jp'>行く</span> → く換成こ，加う → <span class='gd-jp'>行こうと思います</span></span><br><b>第二類（一段動詞）</b>：<span class='gd-pair'><span class='gd-jp'>寝る</span> → 把る拿掉，加よう → <span class='gd-jp'>寝ようと思います</span></span><br><b>第三類（する・来る）</b>：<span class='gd-pair'><span class='gd-jp'>する</span> → <span class='gd-jp'>しようと思います</span></span><span class='gd-pair'><span class='gd-jp'>来る</span> → <span class='gd-jp'>来ようと思います</span>（こよう）</span></div><div class='gd-h'>最常聽到的樣子</div><div class='gd-sec'><span class='gd-tag'>ようと思います</span>現在表明自己的打算，常常是剛下的念頭。</div><div class='gd-ex-line'>・<span class='gd-jp'>今日は早く寝ようと思います。</span>（我今天打算早點睡）</div><div class='gd-sec'><span class='gd-tag'>ようと思っています</span>這個打算<b>已經放在心裡一陣子了</b>，講比較長遠的計畫很常用。</div><div class='gd-ex-line'>・<span class='gd-jp'>来年、日本へ留学しようと思っています。</span>（我打算明年去日本留學）</div><div class='gd-sec'><span class='gd-tag'>ようかと思っています</span>中間多一個「か」，意思變成<b>「我在想要不要～」</b>，還在猶豫。</div><div class='gd-ex-line'>・<span class='gd-jp'>仕事を辞めようかと思っています。</span>（我在想要不要辭職）</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・<span class='gd-jp'>行くと思います</span>和<span class='gd-jp'>行こうと思います</span>差一個字，意思差很多：前者是「我覺得（他）會去」，是猜測；後者才是「我打算去」。<br>・「我<b>不</b>打算去」不能說成<span class='gd-jp'>行かないと思います</span>，那是「我覺得不會去」。要說「不打算」，用<span class='gd-jp'>行かないつもりです</span>。<br>・<span class='gd-jp'>〜ようと思います</span>只能講<b>自己</b>的打算。要講別人的打算，改用<span class='gd-jp'>〜ようと思っています</span>：<span class='gd-jp'>兄は車を買おうと思っています。</span>（我哥打算買車）<br>・問對方打算做什麼，用<span class='gd-jp'>思っています</span>比較自然：<span class='gd-jp'>夏休みは何をしようと思っていますか。</span>（暑假你打算做什麼？）</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'>同樣講「去日本」，三種說法給人的感覺不一樣：<br><b>たい</b>＝單純「想」，是心裡的願望，不一定有計畫：<span class='gd-jp'>日本へ行きたいです。</span>（我想去日本）<br><b>ようと思う</b>＝「打算」，已經有這個念頭，比較軟、留一點彈性：<span class='gd-jp'>日本へ行こうと思います。</span>（我打算去日本）<br><b>つもり</b>＝計畫比較確定，差不多已經定下來了：<span class='gd-jp'>日本へ行くつもりです。</span>（我預計要去日本）</div><div class='gd-warn'>判斷小訣竅：只是「好想～」用たい；「打算～」用ようと思う；「已經計畫好要～」用つもり。中文說「我想要去」時要先想一下，是願望還是打算。</div><div class='gd-h'>學會之後可以接著學</div><div class='gd-sec'>計畫真的拍板定案了，可以用「〜ことにします」：<span class='gd-jp'>来年、日本へ行くことにしました。</span>（我決定明年去日本了）</div>",
  "n4-43": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「〜か（どうか）」是把<b>一個問題塞進句子裡</b>。中文說「我不知道<b>他會不會來</b>」，中間那段其實是個問題，只是沒有單獨問出來。日文這時要在那段後面加「か」或「かどうか」，告訴對方：這裡是一個問題。</div><div class='gd-ex-line'>・<span class='gd-jp'>彼が来るかどうか、分かりません。</span>（我不知道他會不會來）</div><div class='gd-h'>先分兩種：有沒有「誰、哪裡、什麼」這種字</div><div class='gd-sec'><span class='gd-tag'>沒有疑問詞</span>問題的答案只有「是／不是」，就用<b>かどうか</b>，等於中文的「是不是～、會不會～、有沒有～」。只寫「か」也可以，口語常這樣講。</div><div class='gd-ex-line'>・<span class='gd-jp'>鍵をかけたかどうか、覚えていない。</span>（我不記得有沒有鎖門）</div><div class='gd-ex-line'>・<span class='gd-jp'>週末に時間があるか、確認してください。</span>（請確認一下週末有沒有空）</div><div class='gd-sec'><span class='gd-tag'>有疑問詞</span>句子裡已經有<span class='gd-jp'>誰</span>、<span class='gd-jp'>どこ</span>、<span class='gd-jp'>何</span>、<span class='gd-jp'>いつ</span>這種字，就<b>只加「か」</b>，不加どうか。</div><div class='gd-ex-line'>・<span class='gd-jp'>会議が何時に始まるか、知っていますか。</span>（你知道會議幾點開始嗎？）</div><div class='gd-ex-line'>・<span class='gd-jp'>トイレがどこか、教えてください。</span>（請告訴我廁所在哪裡）</div><div class='gd-sec'>後面最常接的動詞：<span class='gd-jp'>分からない</span>、<span class='gd-jp'>知っている</span>、<span class='gd-jp'>決まる</span>、<span class='gd-jp'>確認する</span>、<span class='gd-jp'>聞く</span>、<span class='gd-jp'>考える</span>、<span class='gd-jp'>覚えている</span>，都是「知道、確認、決定」這一類的意思。</div><div class='gd-h'>怎麼接</div><div class='gd-sec'>前面一律用<b>普通形</b>（也就是沒有ます、です的說法）。<br>動詞：<span class='gd-pair'><span class='gd-jp'>行きます</span> → <span class='gd-jp'>行くかどうか</span></span><span class='gd-pair'><span class='gd-jp'>行きました</span> → <span class='gd-jp'>行ったかどうか</span></span><br>い形容詞：<span class='gd-pair'><span class='gd-jp'>おいしいです</span> → <span class='gd-jp'>おいしいかどうか</span></span><br>名詞和な形容詞：<b>不加だ</b>，直接接か。<span class='gd-pair'><span class='gd-jp'>本当です</span> → <span class='gd-jp'>本当かどうか</span></span><span class='gd-pair'><span class='gd-jp'>静かです</span> → <span class='gd-jp'>静かかどうか</span></span><br>另外也可以說「<span class='gd-jp'>来るか来ないか</span>」，意思跟<span class='gd-jp'>来るかどうか</span>一樣。</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・中文直覺不用加任何東西，但日文<b>一定要有か</b>。說<span class='gd-jp'>彼が来る分かりません</span>是錯的。<br>・就算整句要講得有禮貌，中間那段還是普通形，禮貌放在句尾就好：要說<span class='gd-jp'>行くかどうか分かりません</span>，不能說「行きますかどうか」。<br>・名詞、な形容詞後面不要加だ：要說<span class='gd-jp'>学生かどうか</span>，不能說「学生だかどうか」。<br>・有疑問詞時不能再加どうか：要說<span class='gd-jp'>どこがいいか</span>，不能說「どこがいいかどうか」。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'>都有「か」、都帶點不確定，初學者常把它跟<b>かもしれない</b>搞混。<br><span class='gd-jp'>彼は来るかどうか分からない。</span>（不知道他會不會來：完全不知道，只是在說「這件事我不清楚」）<br><span class='gd-jp'>彼は来るかもしれない。</span>（他可能會來：你在猜，覺得有來的可能）</div><div class='gd-warn'>判斷小訣竅：後面還接著「分からない、確認する、教えて」這類動詞的，是かどうか；句子到這裡就結束、意思是「可能～」的，是かもしれない。</div><div class='gd-h'>學會之後可以接著學</div><div class='gd-sec'>跟「〜てみます」放在一起很好用：<span class='gd-jp'>行けるかどうか、先生に聞いてみます。</span>（我問問看老師能不能去）</div>",
  "n4-44": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「想要」「好怕」「好冷」這種心裡的感覺，只有本人自己知道。所以日文講<b>別人</b>的感覺時，不會直接說「他想要」，而是說「他<b>表現出</b>想要的樣子」，這就是「〜がる」。很像中文說「他一直吵著要～」「他一副很怕的樣子」。</div><div class='gd-h'>什麼時候用</div><div class='gd-sec'><span class='gd-tag'>別人想要什麼</span>弟弟、朋友、小孩，甚至寵物，看得出來他很想要、很想做。</div><div class='gd-ex-line'>・<span class='gd-jp'>弟が新しいゲーム機を欲しがっています。</span>（弟弟一直想要新的遊戲機）</div><div class='gd-ex-line'>・<span class='gd-jp'>彼女はずっと日本へ行きたがっています。</span>（她一直很想去日本）</div><div class='gd-sec'><span class='gd-tag'>別人的感覺</span>怕、冷、痛、討厭這些，從表情、動作看得出來。</div><div class='gd-ex-line'>・<span class='gd-jp'>子どもが注射を怖がっています。</span>（小孩很怕打針）</div><div class='gd-ex-line'>・<span class='gd-jp'>娘は野菜を嫌がって、食べません。</span>（女兒討厭蔬菜，不肯吃）</div><div class='gd-h'>怎麼接</div><div class='gd-sec'>只有表示感情、感覺的形容詞才能接「がる」（<span class='gd-jp'>欲しい</span>、<span class='gd-jp'>怖い</span>、<span class='gd-jp'>痛い</span>、<span class='gd-jp'>寒い</span>、<span class='gd-jp'>嫌だ</span>…）。<br><b>い形容詞</b>：把最後的「い」拿掉，加「がる」。<br><span class='gd-pair'><span class='gd-jp'>欲しい</span> → <span class='gd-jp'>欲しがる</span></span><span class='gd-pair'><span class='gd-jp'>怖い</span> → <span class='gd-jp'>怖がる</span></span><span class='gd-pair'><span class='gd-jp'>痛い</span> → <span class='gd-jp'>痛がる</span></span></div><div class='gd-sec'><b>想做某件事</b>：先變成「〜たい」，再把「い」拿掉，加「がる」。<br><span class='gd-pair'><span class='gd-jp'>行く</span> → <span class='gd-jp'>行きたい</span> → <span class='gd-jp'>行きたがる</span></span><span class='gd-pair'><span class='gd-jp'>働く</span> → <span class='gd-jp'>働きたい</span> → <span class='gd-jp'>働きたがる</span></span></div><div class='gd-sec'><b>な形容詞</b>：先把「だ」拿掉，再加「がる」，例如<span class='gd-pair'><span class='gd-jp'>嫌だ</span> → <span class='gd-jp'>嫌がる</span></span><span class='gd-pair'><span class='gd-jp'>残念だ</span> → <span class='gd-jp'>残念がる</span></span>。能這樣用的な形容詞不多，常見的就是<span class='gd-jp'>嫌がる</span>、<span class='gd-jp'>残念がる</span>、<span class='gd-jp'>不思議がる</span>、<span class='gd-jp'>面倒がる</span>這幾個。<br>注意：<span class='gd-jp'>大きい</span>不是感覺，不能說×<span class='gd-jp'>大きがる</span>；<span class='gd-jp'>好き</span>雖然是心情，也不說×<span class='gd-jp'>好きがる</span>。</div><div class='gd-sec'>變成「がる」之後，它就跟<span class='gd-jp'>帰る</span>一樣，當第一類（五段動詞）變化：<span class='gd-jp'>がります</span>、<span class='gd-jp'>がりません</span>、<span class='gd-jp'>がっています</span>、<span class='gd-jp'>がった</span>。</div><div class='gd-h'>最常聽到的樣子</div><div class='gd-sec'><span class='gd-tag'>がっています</span>講「現在他很想要、很怕」，幾乎都用這個形。只說<span class='gd-jp'>欲しがります</span>，聽起來比較像「他平常就會這樣」的習慣、傾向。</div><div class='gd-ex-line'>・<span class='gd-jp'>犬が散歩に行きたがっている。</span>（狗狗想出去散步了）</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・<b>講自己不用がる</b>：自己的心情直接說<span class='gd-jp'>私は新しいスマホが欲しいです</span>，不說「私は欲しがっています」。反過來，中文說「他想要」很自然，但日文直接說<span class='gd-jp'>弟は欲しいです</span>會怪怪的，要用欲しがっています。<br>・<b>助詞會變</b>：<span class='gd-jp'>水が欲しい</span>變成がる之後要用「を」：<span class='gd-jp'>弟は水を欲しがっている</span>。<br>・<b>問對面的人不用がる</b>：跟朋友直接問<span class='gd-jp'>何が食べたい？</span>（你想吃什麼？）就好。<br>・<b>不要用在長輩、主管身上</b>：「〜がる」是從旁觀察、描述對方表現出來的樣子，用在老師、主管身上會像在評論對方的心情，不夠禮貌。這時別說先生が帰りたがっています，比較好的說法是<span class='gd-jp'>先生は帰りたいとおっしゃっていました。</span>（老師說他想回去了）</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'>同樣是「弟弟想要新手機」，三種說法差在<b>誰的心情、你怎麼知道的</b>：<br><b>欲しい</b>＝講自己的心情：<span class='gd-jp'>私は新しいスマホが欲しいです。</span>（我想要新手機）<br><b>欲しがっている</b>＝他已經說出口、表現出來了：<span class='gd-jp'>弟は新しいスマホを欲しがっています。</span>（弟弟一直吵著要新手機）<br><b>欲しそう</b>＝他沒說，是你看他樣子猜的：<span class='gd-jp'>弟は新しいスマホが欲しそうです。</span>（弟弟看起來好像想要新手機）</div><div class='gd-warn'>判斷小訣竅：自己的心情用「たい・欲しい」；別人已經表現出來的用「がっている」；只是看臉色猜的用「そう」。</div><div class='gd-h'>學會之後可以接著學</div><div class='gd-sec'>不想評論別人心情時，可以改用轉述的說法：<span class='gd-jp'>姉は留学したいと言っています。</span>（姊姊說她想去留學）</div>",
  "n4-46": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「〜なさい」就像台灣媽媽說的<b>「快去睡覺！」「把手洗乾淨！」</b>：有大人的威嚴，但不是在罵人。它是<b>上對下</b>的命令，父母對小孩、老師對學生最常講。</div><div class='gd-h'>什麼時候用</div><div class='gd-sec'><span class='gd-tag'>父母對小孩</span>叫小孩做該做的事，日劇、動畫裡的媽媽天天在講。</div><div class='gd-ex-line'>・<span class='gd-jp'>早く寝なさい。</span>（快去睡覺）</div><div class='gd-ex-line'>・<span class='gd-jp'>宿題を先にやりなさい。</span>（先去寫作業）</div><div class='gd-sec'><span class='gd-tag'>老師對學生</span>上課時的指示。</div><div class='gd-ex-line'>・<span class='gd-jp'>よく聞きなさい。</span>（好好聽）</div><div class='gd-sec'><span class='gd-tag'>考卷上的題目</span>日檢、日本學校的考題很常這樣寫，看到就知道是「請～」的指示。</div><div class='gd-ex-line'>・<span class='gd-jp'>正しいものを選びなさい。</span>（請選出正確的答案）</div><div class='gd-h'>怎麼接</div><div class='gd-sec'>先把動詞變成ます形，<b>把ます拿掉</b>，加上なさい。三類動詞都一樣，不用另外背規則。<br><span class='gd-pair'><span class='gd-jp'>行きます</span> → 把ます拿掉 → <span class='gd-jp'>行きなさい</span></span><br><span class='gd-pair'><span class='gd-jp'>洗います</span> → <span class='gd-jp'>洗いなさい</span></span><span class='gd-pair'><span class='gd-jp'>食べます</span> → <span class='gd-jp'>食べなさい</span></span><span class='gd-pair'><span class='gd-jp'>寝ます</span> → <span class='gd-jp'>寝なさい</span></span><br><span class='gd-pair'><span class='gd-jp'>勉強します</span> → <span class='gd-jp'>勉強しなさい</span></span><span class='gd-pair'><span class='gd-jp'>来ます</span> → <span class='gd-jp'>来なさい</span>（きなさい）</span></div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・它聽起來不兇，但<b>不是禮貌說法</b>。對老師、上司、客人講「<span class='gd-jp'>座りなさい</span>」會很失禮，請對方做事要用「<span class='gd-jp'>座ってください</span>」。<br>・<span class='gd-jp'>来なさい</span>念<b>きなさい</b>，不是こなさい。<br>・要叫人「不要～」，なさい沒有否定的變法，不能把ない硬接上去。改用「〜ないで」或「〜てはいけません」，例：<span class='gd-jp'>走らないで</span>（不要跑）。<br>・<span class='gd-jp'>おやすみなさい</span>、<span class='gd-jp'>おかえりなさい</span>、<span class='gd-jp'>ごめんなさい</span>雖然也有なさい，但已經是固定的招呼語，沒有命令的意思。不過<span class='gd-jp'>ごめんなさい</span>比較口語，對上司、客人道歉要用「<span class='gd-jp'>すみません</span>」或「<span class='gd-jp'>申し訳ありません</span>」。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'>同樣是叫對方早點睡，換個說法，口氣和身分關係就不一樣：<br><b>〜なさい</b>＝上對下、帶管教口氣（媽媽對小孩）：</div><div class='gd-ex-line'>・<span class='gd-jp'>もう11時だよ。早く寝なさい。</span>（已經 11 點了，快去睡）</div><div class='gd-sec'><b>命令形</b>＝直接、很衝，多半是男性用語，或吵架、緊急時才用：</div><div class='gd-ex-line'>・<span class='gd-jp'>早く寝ろ。</span>（快給我去睡）</div><div class='gd-sec'><b>〜てください</b>＝有禮貌地請對方做，醫生對病人、店員對客人等都用：</div><div class='gd-ex-line'>・<span class='gd-jp'>今日は早く寝てくださいね。</span>（今天請早點休息喔）</div><div class='gd-sec'><b>〜てね</b>＝朋友、家人之間輕鬆的叮嚀：</div><div class='gd-ex-line'>・<span class='gd-jp'>今日は早く寝てね。</span>（今天早點睡喔）</div><div class='gd-warn'>判斷小訣竅：大人在「管教」小孩用なさい；要客氣請人幫忙用てください；跟朋友隨口叮嚀用てね；ろ最兇，初學者先別亂用。</div><div class='gd-h'>學會之後可以接著學</div><div class='gd-sec'>接著學「命令形・禁止形」（<span class='gd-jp'>寝ろ</span>、<span class='gd-jp'>寝るな</span>），就能聽懂日劇裡更直接的命令，也更清楚なさい為什麼算「溫和」。</div>",
  "n4-49": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「〜ばかり」就是中文的<b>「老是～」「整天都在～」「淨是～」</b>。媽媽念小孩「你整天只會打電動」，日文就用ばかり。重點是：說話的人覺得<b>太多了、不太好</b>，所以常帶著抱怨或念人的口氣。</div><div class='gd-h'>怎麼接</div><div class='gd-sec'><span class='gd-tag'>動作本身太多</span>動詞て形＋ばかりいる：強調「一直在做這件事，別的都不做」。<br><span class='gd-pair'><span class='gd-jp'>遊ぶ</span> → <span class='gd-jp'>遊んで</span> → <span class='gd-jp'>遊んでばかりいる</span></span>（老是在玩）<br><span class='gd-pair'><span class='gd-jp'>寝る</span> → <span class='gd-jp'>寝て</span> → <span class='gd-jp'>寝てばかりいる</span></span>（老是在睡）</div><div class='gd-ex-line'>・<span class='gd-jp'>うちの犬は一日中寝てばかりいる。</span>（我家的狗整天都在睡）</div><div class='gd-sec'><span class='gd-tag'>對象都是同一個</span>名詞＋ばかり＋動詞：強調「做的都是這個東西」。</div><div class='gd-ex-line'>・<span class='gd-jp'>弟はゲームばかりしている。</span>（我弟整天都在打電動）</div><div class='gd-ex-line'>・<span class='gd-jp'>彼はいつも文句ばかり言っている。</span>（他老是在抱怨）</div><div class='gd-sec'>名詞後面也可以直接加「です／だ」，描述「放眼望去都是～」：</div><div class='gd-ex-line'>・<span class='gd-jp'>最近、雨ばかりですね。</span>（最近老是下雨耶）</div><div class='gd-h'>最常聽到的樣子</div><div class='gd-sec'><span class='gd-tag'>念人</span>「〜てばかりいないで」＝別老是～，後面常接<span class='gd-jp'>〜なさい</span>，是爸媽、老師的經典台詞。</div><div class='gd-ex-line'>・<span class='gd-jp'>遊んでばかりいないで、勉強しなさい。</span>（別老是在玩，去讀書）</div><div class='gd-ex-line'>・<span class='gd-jp'>泣いてばかりいないで、話してよ。</span>（別一直哭，跟我說嘛）</div><div class='gd-sec'><span class='gd-tag'>自嘲</span>講自己也可以，有「唉，我怎麼都這樣」的感覺。</div><div class='gd-ex-line'>・<span class='gd-jp'>最近、食べてばかりいる。</span>（最近一直在吃）</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・名詞加ばかり時，原本的「を」通常拿掉：說<span class='gd-jp'>漫画ばかり読む</span>，不要說成「漫画をばかり読む」。<br>・它講的是<b>一段時間裡一直重複</b>的狀態，只發生一次的事不能用。<br>・口氣帶批評，拿來講老師、主管、客人很失禮，小心使用。<br>・朋友聊天常會講成<span class='gd-jp'>ばっかり</span>，例如<span class='gd-jp'>遊んでばっかり</span>，意思一樣，只是比較口語。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'><b>たばかり</b>（n4-29）＝<b>剛剛</b>才做完，跟次數無關：<br><span class='gd-jp'>ご飯を食べたばかりです。</span>（我剛吃完飯）<br><b>てばかりいる</b>＝<b>老是</b>在做：<br><span class='gd-jp'>お菓子を食べてばかりいる。</span>（老是在吃零食）</div><div class='gd-sec'><b>だけ</b>＝<b>只有</b>這個，單純說事實，沒有不滿：<br><span class='gd-jp'>朝はコーヒーだけ飲みました。</span>（早上只喝了咖啡）<br><b>ばかり</b>＝<b>一直、太多</b>，帶抱怨：<br><span class='gd-jp'>コーヒーばかり飲んでいる。</span>（老是在喝咖啡）</div><div class='gd-warn'>判斷小訣竅：前面是「た」就是「剛剛」，前面是「て」就是「老是」；只是說「只有這個」用だけ，想念人「怎麼都這個」用ばかり。</div>",
  "n4-50": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「〜場合」就是<b>「如果遇到～的情況」</b>。你在捷運站、飯店房間、說明書上看到的「如遇火警，請～」「若有任何問題，請～」，日文就是用「場合」講的。它比「〜たら」正式，常常出現在規定、公告、店員或客服的說明裡。</div><div class='gd-h'>什麼時候用</div><div class='gd-sec'><span class='gd-tag'>規定・公告</span>先假設一種「可能會發生、也可能不會」的情況，告訴對方到時候該怎麼辦。後面常接「〜てください」或規則。</div><div class='gd-ex-line'>・<span class='gd-jp'>地震の場合は、机の下に隠れてください。</span>（發生地震的話，請躲到桌子底下）</div><div class='gd-ex-line'>・<span class='gd-jp'>雨の場合は、試合は中止です。</span>（下雨的話，比賽就取消）</div><div class='gd-ex-line'>・<span class='gd-jp'>分からない場合は、先生に聞いてください。</span>（不懂的話，請問老師）</div><div class='gd-sec'>「場合」後面幾乎都會加「は」，變成「〜場合は」，你直接把它當成一組來記就好。</div><div class='gd-h'>怎麼接</div><div class='gd-sec'><b>動詞</b>：直接接辭書形、ない形、た形。<br><span class='gd-pair'><span class='gd-jp'>遅れる</span> → <span class='gd-jp'>遅れる場合</span></span><span class='gd-pair'><span class='gd-jp'>行けない</span> → <span class='gd-jp'>行けない場合</span></span><span class='gd-pair'><span class='gd-jp'>忘れた</span> → <span class='gd-jp'>忘れた場合</span></span><br><b>い形容詞</b>：直接接。<span class='gd-pair'><span class='gd-jp'>熱が高い</span> → <span class='gd-jp'>熱が高い場合</span></span><br><b>な形容詞</b>：保留「な」。<span class='gd-pair'><span class='gd-jp'>無理</span> → <span class='gd-jp'>無理な場合</span></span><br><b>名詞</b>：中間加「の」。<span class='gd-pair'><span class='gd-jp'>雨</span> → <span class='gd-jp'>雨の場合</span></span><span class='gd-pair'><span class='gd-jp'>火事</span> → <span class='gd-jp'>火事の場合</span></span></div><div class='gd-sec'><span class='gd-tag'>る和た的差別</span>動詞用辭書形還是た形，意思會差一點：<br>・<span class='gd-jp'>遅れる場合は、電話してください。</span>（如果會遲到，請先打電話：還沒遲到前就聯絡）<br>・<span class='gd-jp'>カードをなくした場合は、すぐ連絡してください。</span>（萬一卡片弄丟了，請馬上聯絡：事情發生之後）</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・「場合」念<b>ばあい</b>，不是ばしょ，也不要照中文念成じょうごう。<br>・名詞和な形容詞不能直接加「だ」：不是「雨だ場合」，是<span class='gd-jp'>雨の場合</span>；不是「無理だ場合」，是<span class='gd-jp'>無理な場合</span>。<br>・な形容詞要用<b>な</b>，不要跟名詞搞混而寫成「の」。<br>・「場合」只能用在<b>不一定會發生</b>的事。一定會到來的事，例如「10點到了的話」，不能說「10時になった場合」，要用<span class='gd-jp'>10時になったら</span>。<br>・已經發生過的事也不能用：「昨天下雨的時候」不能說「昨日雨が降った場合」。<br>・它的口氣偏正式，跟朋友聊天說「下雨的話就不去了」，用<span class='gd-jp'>雨だったら</span>比較自然。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'>同樣是「下雨的話」：<br><b>場合</b>：<span class='gd-jp'>雨の場合は、イベントは中止です。</span>（如遇雨天，活動取消）→ 像是寫在公告上的規定。<br><b>たら</b>：<span class='gd-jp'>雨が降ったら、家で映画を見よう。</span>（如果下雨，就在家看電影吧）→ 朋友之間隨口講的。<br>另外，「たら」可以用在一定會發生的事（<span class='gd-jp'>駅に着いたら、電話して。</span>到車站之後打給我），「場合」不行。</div><div class='gd-warn'>判斷小訣竅：能翻成「如遇～」「若發生～」，而且是在講規定或說明，就用「場合」；日常聊天，或是一定會發生的事，就用「たら」。</div><div class='gd-h'>學會之後可以接著學</div><div class='gd-sec'>其他「如果」的說法可以一起比較著學：<span class='gd-jp'>〜ば</span>（條件形）、<span class='gd-jp'>〜なら</span>、<span class='gd-jp'>〜と</span>。各自的語感不太一樣。</div>",
  "n4-51": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>意向形就是「〜ましょう」的<b>朋友版</b>。跟同事說<span class='gd-jp'>一緒に行きましょう</span>，跟朋友就說<span class='gd-jp'>一緒に行こう</span>。意思一樣是「～吧」，只是口氣比較隨興。</div><div class='gd-h'>什麼時候用</div><div class='gd-sec'><span class='gd-tag'>揪人</span>約對方跟你一起做某件事。</div><div class='gd-ex-line'>・<span class='gd-jp'>一緒に行こう。</span>（一起去吧）</div><div class='gd-ex-line'>・<span class='gd-jp'>ちょっと休もう。</span>（休息一下吧）</div><div class='gd-sec'><span class='gd-tag'>給自己打氣</span>心裡下決定、自言自語，旁邊沒人也可以用。</div><div class='gd-ex-line'>・<span class='gd-jp'>よし、明日から早く起きよう。</span>（好，明天開始早點起床）</div><div class='gd-sec'><span class='gd-tag'>主動幫忙</span>後面加「か」，變成「我來幫你～吧？」。</div><div class='gd-ex-line'>・<span class='gd-jp'>荷物、持とうか。</span>（行李我幫你拿吧？）</div><div class='gd-h'>怎麼變：先看動詞是哪一類</div><div class='gd-sec'><b>第一類（五段動詞）</b>：最後一個音換成同一行的「お」段音，再加「う」。<br><span class='gd-pair'><span class='gd-jp'>行く</span> → く換成こ → <span class='gd-jp'>行こう</span></span><br><span class='gd-pair'><span class='gd-jp'>飲む</span> → <span class='gd-jp'>飲もう</span></span><span class='gd-pair'><span class='gd-jp'>待つ</span> → <span class='gd-jp'>待とう</span></span><span class='gd-pair'><span class='gd-jp'>話す</span> → <span class='gd-jp'>話そう</span></span><span class='gd-pair'><span class='gd-jp'>帰る</span> → <span class='gd-jp'>帰ろう</span></span><span class='gd-pair'><span class='gd-jp'>会う</span> → <span class='gd-jp'>会おう</span></span><br>從ます形想也可以：<span class='gd-jp'>行きます</span>的「き」換成「こ」，再加「う」。</div><div class='gd-sec'><b>第二類（一段動詞）</b>：把最後的「る」拿掉，加「よう」。<br><span class='gd-pair'><span class='gd-jp'>食べる</span> → <span class='gd-jp'>食べよう</span></span><span class='gd-pair'><span class='gd-jp'>起きる</span> → <span class='gd-jp'>起きよう</span></span><span class='gd-pair'><span class='gd-jp'>見る</span> → <span class='gd-jp'>見よう</span></span></div><div class='gd-sec'><b>第三類（只有兩個，直接背）</b>：<span class='gd-pair'><span class='gd-jp'>する</span> → <span class='gd-jp'>しよう</span></span><span class='gd-pair'><span class='gd-jp'>来る</span> → <span class='gd-jp'>来よう</span>（こよう）</span></div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・「行こう」的こう要念長音，聽起來像「いこー」。念成短短的「いこ」是很撒嬌、很口語的說法，口氣不一樣。<br>・<span class='gd-jp'>会う</span>是<span class='gd-jp'>会おう</span>。不要跟ない形的<span class='gd-jp'>会わない</span>搞混，寫成「会わう」。<br>・<span class='gd-jp'>帰る</span>、<span class='gd-jp'>入る</span>長得像第二類，其實是第一類：是<span class='gd-jp'>帰ろう</span>，不是帰よう。<br>・来る的意向形念<b>こよう</b>，不是きよう。<br>・它只能講<b>自己</b>要做，或<b>揪對方跟你一起</b>做，不能拿來叫別人去做。想說「朋友也來吧」，要改成<span class='gd-jp'>友達も呼ぼう</span>（也把朋友叫來吧）。<br>・這是朋友之間講的話，對老師、客人要換回「〜ましょう」。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'>同樣是約朋友去看電影，有三種講法：<br><span class='gd-jp'>映画を見に行こう。</span>（去看電影吧）：直接揪，有點「就這麼說定囉」的感覺。<br><span class='gd-jp'>映画を見に行かない？</span>（要不要去看電影？）：先問對方想不想去，比較留餘地。<br><span class='gd-jp'>映画を見に行きましょう。</span>（我們去看電影吧）：禮貌版的「行こう」，對不熟的人或長輩用。</div><div class='gd-warn'>判斷小訣竅：對方是朋友，你也覺得他會答應，就用「行こう」；想先問問看，就用「行かない？」；對方需要客氣對待，就用「行きましょう」。</div><div class='gd-h'>學會之後可以接著學</div><div class='gd-sec'>後面加「と思います」就是「我打算～」：<span class='gd-jp'>来年、日本へ行こうと思います。</span>（我打算明年去日本）</div>",
  "n4-52": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>可能形就是中文的<b>「會～」「能～」「可以～」</b>，直接把意思加進動詞裡。<span class='gd-jp'>書く</span>是「寫」，變成<span class='gd-jp'>書ける</span>就是「會寫、寫得出來」。日本人平常講「會不會、能不能」，最常用的就是這個形。</div><div class='gd-h'>什麼時候用</div><div class='gd-sec'><span class='gd-tag'>會（學過的能力）</span>學過、練過，所以會做。</div><div class='gd-ex-line'>・<span class='gd-jp'>韓国語が書けます。</span>（我會寫韓文）</div><div class='gd-ex-line'>・<span class='gd-jp'>ピアノが弾けますか。</span>（你會彈鋼琴嗎？）</div><div class='gd-sec'><span class='gd-tag'>能／可以（情況允許）</span>不是會不會，而是時間、地點、規定允不允許。</div><div class='gd-ex-line'>・<span class='gd-jp'>ここで写真が撮れますか。</span>（這裡可以拍照嗎？）</div><div class='gd-ex-line'>・<span class='gd-jp'>明日は来られますか。</span>（你明天能來嗎？）</div><div class='gd-sec'><span class='gd-tag'>敢吃、能吃</span>講食物時，常常就是中文的「敢吃」。</div><div class='gd-ex-line'>・<span class='gd-jp'>納豆が食べられますか。</span>（你敢吃納豆嗎？）</div><div class='gd-h'>怎麼變：先看動詞是哪一類</div><div class='gd-sec'><b>第一類（五段動詞）</b>：最後一個音換成同一行的「え」段音，再加「る」。<br><span class='gd-pair'><span class='gd-jp'>書く</span> → く換成け → <span class='gd-jp'>書ける</span></span><br><span class='gd-pair'><span class='gd-jp'>話す</span> → <span class='gd-jp'>話せる</span></span><span class='gd-pair'><span class='gd-jp'>飲む</span> → <span class='gd-jp'>飲める</span></span><span class='gd-pair'><span class='gd-jp'>買う</span> → <span class='gd-jp'>買える</span></span><span class='gd-pair'><span class='gd-jp'>待つ</span> → <span class='gd-jp'>待てる</span></span><span class='gd-pair'><span class='gd-jp'>帰る</span> → <span class='gd-jp'>帰れる</span></span><br>從ます形想也可以：<span class='gd-jp'>書きます</span>的「き」換成「け」→ <span class='gd-jp'>書けます</span>。</div><div class='gd-sec'><b>第二類（一段動詞）</b>：把最後的「る」拿掉，加「られる」。<br><span class='gd-pair'><span class='gd-jp'>食べる</span> → <span class='gd-jp'>食べられる</span></span><span class='gd-pair'><span class='gd-jp'>見る</span> → <span class='gd-jp'>見られる</span></span><span class='gd-pair'><span class='gd-jp'>起きる</span> → <span class='gd-jp'>起きられる</span></span></div><div class='gd-sec'><b>第三類（只有兩個，直接背）</b>：<span class='gd-pair'><span class='gd-jp'>する</span> → <span class='gd-jp'>できる</span></span><span class='gd-pair'><span class='gd-jp'>来る</span> → <span class='gd-jp'>来られる</span>（こられる）</span><br>「名詞＋する」的動詞也一樣，把する換成できる：<span class='gd-pair'><span class='gd-jp'>説明する</span> → <span class='gd-jp'>説明できる</span></span></div><div class='gd-h'>變好之後，再接著變</div><div class='gd-sec'>可能形變好之後，<b>本身就是一個第二類動詞</b>，要說「不會」「會了」就照第二類的規則繼續變：<br><span class='gd-pair'><span class='gd-jp'>書ける</span> → <span class='gd-jp'>書けます</span></span><span class='gd-pair'><span class='gd-jp'>書ける</span> → <span class='gd-jp'>書けない</span></span><span class='gd-pair'><span class='gd-jp'>書ける</span> → <span class='gd-jp'>書けた</span></span></div><div class='gd-ex-line'>・<span class='gd-jp'>朝、なかなか起きられない。</span>（早上老是爬不起來）</div><div class='gd-h'>助詞：を常常換成が</div><div class='gd-sec'>變成可能形後，原本的「を」通常換成「が」：<br><span class='gd-pair'><span class='gd-jp'>日本語を話す</span> → <span class='gd-jp'>日本語が話せる</span></span><br>日常對話裡也聽得到用を，但課本和考試以が為主，先記<b>が</b>最穩。</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・<span class='gd-jp'>帰る</span>、<span class='gd-jp'>入る</span>、<span class='gd-jp'>走る</span>長得像第二類，其實是第一類：是<span class='gd-jp'>帰れる</span>，不是帰られる。<br>・来る的可能形念<b>こられる</b>，不是きられる。<br>・する的可能形要整個換成<span class='gd-jp'>できる</span>，不能自己照規則硬變。<br>・口語常聽到<span class='gd-jp'>食べれる</span>、<span class='gd-jp'>見れる</span>、<span class='gd-jp'>来れる</span>（少了「ら」），日本人平常真的很常這樣講，但課本、考試、正式場合還是要用<span class='gd-jp'>食べられる</span>、<span class='gd-jp'>見られる</span>、<span class='gd-jp'>来られる</span>。<br>・「看得到、聽得到」如果是<b>自然就看到、聽到</b>，日文用<span class='gd-jp'>見える</span>、<span class='gd-jp'>聞こえる</span>：<span class='gd-jp'>ここから富士山が見える。</span>（從這裡看得到富士山）。<span class='gd-jp'>見られる</span>、<span class='gd-jp'>聞ける</span>是<b>有機會、有辦法去看、去聽</b>：<span class='gd-jp'>このアプリで映画が見られる。</span>（用這個 App 可以看電影）</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'>你之前學過的<span class='gd-jp'>〜ことができる</span>，意思跟可能形一樣：<br>・<span class='gd-jp'>日本語が話せます。</span>（我會講日文）<br>・<span class='gd-jp'>日本語を話すことができます。</span>（我能夠講日文）<br>差在長度和感覺：可能形比較短，日常聊天最常用；<span class='gd-jp'>ことができる</span>比較長、比較正式，說明書、公告、演講裡常看到。還有一點：<span class='gd-jp'>ことができる</span>前面的動詞不變形，助詞也維持「を」。</div><div class='gd-warn'>判斷小訣竅：平常講話用可能形；想講得正式、清楚一點，用ことができる。兩個意思一樣，用哪個都不算錯。</div><div class='gd-h'>學會之後可以接著學</div><div class='gd-sec'>後面加「ようになる」，就是「變得會～了」：<span class='gd-jp'>日本語が少し話せるようになりました。</span>（我變得會講一點日文了）</div>",
  "n4-53": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>命令形就是直接吼「<b>給我～！</b>」，禁止形就是「<b>不准～！</b>」。中文的「快跑！」「不准進來！」這種沒有任何客氣的口氣就是它們。日常對人講很兇，你在動漫、運動比賽、緊急場面最常聽到。</div><div class='gd-h'>什麼時候用</div><div class='gd-sec'><span class='gd-tag'>緊急、危險</span>來不及客氣的時候。</div><div class='gd-ex-line'>・<span class='gd-jp'>危ない！逃げろ！</span>（危險！快逃！）</div><div class='gd-sec'><span class='gd-tag'>加油打氣</span>比賽場邊喊，這時不算兇，男生女生都會喊。</div><div class='gd-ex-line'>・<span class='gd-jp'>頑張れ！負けるな！</span>（加油！別輸！）</div><div class='gd-sec'><span class='gd-tag'>轉述別人的話</span>後面加「と言われた」，說「某人叫我～」，這是你自己最常會用到的場合。</div><div class='gd-ex-line'>・<span class='gd-jp'>医者にお酒を飲むなと言われた。</span>（醫生叫我不要喝酒）</div><div class='gd-ex-line'>・<span class='gd-jp'>父に早く寝ろと言われた。</span>（爸爸叫我早點睡）</div><div class='gd-sec'><span class='gd-tag'>標誌、上對下</span>路上寫的「<span class='gd-jp'>止まれ</span>」（停）就是命令形。另外就是吵架、教練罵選手這種場面。</div><div class='gd-h'>怎麼變：先看動詞是哪一類</div><div class='gd-sec'><b>命令形</b><br><b>第一類（五段動詞）</b>：最後一個音換成同一行的「え」段音。<br><span class='gd-pair'><span class='gd-jp'>行く</span> → く換成け → <span class='gd-jp'>行け</span></span><br><span class='gd-pair'><span class='gd-jp'>走る</span> → <span class='gd-jp'>走れ</span></span><span class='gd-pair'><span class='gd-jp'>飲む</span> → <span class='gd-jp'>飲め</span></span><span class='gd-pair'><span class='gd-jp'>待つ</span> → <span class='gd-jp'>待て</span></span><span class='gd-pair'><span class='gd-jp'>急ぐ</span> → <span class='gd-jp'>急げ</span></span></div><div class='gd-sec'><b>第二類（一段動詞）</b>：把最後的「る」拿掉，加「ろ」。<br><span class='gd-pair'><span class='gd-jp'>食べる</span> → <span class='gd-jp'>食べろ</span></span><span class='gd-pair'><span class='gd-jp'>起きる</span> → <span class='gd-jp'>起きろ</span></span><span class='gd-pair'><span class='gd-jp'>見る</span> → <span class='gd-jp'>見ろ</span></span></div><div class='gd-sec'><b>第三類（只有兩個，直接背）</b>：<span class='gd-pair'><span class='gd-jp'>する</span> → <span class='gd-jp'>しろ</span></span><span class='gd-pair'><span class='gd-jp'>来る</span> → <span class='gd-jp'>来い</span>（こい）</span></div><div class='gd-sec'><b>禁止形</b>簡單很多，不分哪一類，<b>辭書形直接加「な」</b>就好。<br><span class='gd-pair'><span class='gd-jp'>行く</span> → <span class='gd-jp'>行くな</span></span><span class='gd-pair'><span class='gd-jp'>食べる</span> → <span class='gd-jp'>食べるな</span></span><span class='gd-pair'><span class='gd-jp'>する</span> → <span class='gd-jp'>するな</span></span><span class='gd-pair'><span class='gd-jp'>来る</span> → <span class='gd-jp'>来るな</span>（くるな）</span></div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・對老師、上司、客人用命令形非常失禮。看動漫學來的「<span class='gd-jp'>待て！</span>」「<span class='gd-jp'>見ろ！</span>」不要拿去對真人講。<br>・<span class='gd-jp'>帰る</span>、<span class='gd-jp'>入る</span>、<span class='gd-jp'>走る</span>是第一類，所以是<span class='gd-jp'>帰れ</span>、<span class='gd-jp'>入れ</span>，不是帰ろ、入ろ。<br>・<span class='gd-jp'>来い</span>念<b>こい</b>，可是<span class='gd-jp'>来るな</span>念<b>くるな</b>，兩個念法不一樣。<br>・命令形跟可能形長得很像：<span class='gd-jp'>読め</span>是「給我讀」，<span class='gd-jp'>読める</span>是「看得懂」，差在最後有沒有「る」。<br>・「な」前面一定要接辭書形：<span class='gd-jp'>行くな</span>是「不准去」。如果是把ます拿掉再加な，像<span class='gd-jp'>行きな</span>，反而是口語的「去吧」，意思整個相反。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'>同樣是叫小孩去睡覺：<br><span class='gd-jp'>早く寝ろ！</span>（快給我睡！）：最兇，直接吼。<br><span class='gd-jp'>早く寝なさい。</span>（快去睡。）：爸媽、老師對小孩的口氣，有上對下的感覺，但不算粗魯。<br><span class='gd-jp'>早く寝てね。</span>（早點睡喔。）：一般的請求，溫和。</div><div class='gd-sec'>同樣是不准進房間：<br><span class='gd-jp'>入るな！</span>（不准進來！）：最兇。<br><span class='gd-jp'>入ってはいけません。</span>（不可以進去。）：講規定、說明禁止，口氣比較正式。<br><span class='gd-jp'>入らないでください。</span>（請不要進去。）：客氣地拜託。</div><div class='gd-warn'>判斷小訣竅：吼出來的是命令形、禁止形；大人管小孩是なさい；講規則是てはいけません；拜託別人用てください、ないでください。</div><div class='gd-h'>學會之後可以接著學</div><div class='gd-sec'><span class='gd-jp'>くれる</span>的命令形是<span class='gd-jp'>くれ</span>，不是くれろ。男生常說<span class='gd-jp'>ちょっと待ってくれ。</span>（等我一下），比單講「待て」柔和一點。</div>",
  "n4-57": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>這個「と」就是中文的<b>「一～就～」</b>。只要A發生，B<b>每次都會</b>跟著發生，不會例外，就像「一按開關，燈就亮」。所以它最常用在大自然的規律、機器怎麼操作、指路，還有每次都固定會做的習慣。</div><div class='gd-h'>什麼時候用</div><div class='gd-sec'><span class='gd-tag'>自然規律</span>本來就會這樣，誰都改變不了。</div><div class='gd-ex-line'>・<span class='gd-jp'>春になると、桜が咲きます。</span>（一到春天，櫻花就會開）</div><div class='gd-ex-line'>・<span class='gd-jp'>夜になると、街の灯りがつきます。</span>（一到晚上，街燈就亮了）</div><div class='gd-sec'><span class='gd-tag'>機器操作</span>做了這個動作，機器就會有反應。</div><div class='gd-ex-line'>・<span class='gd-jp'>このボタンを押すと、ドアが開きます。</span>（一按這個按鈕，門就會開）</div><div class='gd-ex-line'>・<span class='gd-jp'>この鍵を回すと、金庫が開きます。</span>（轉這把鑰匙，保險箱就會開）</div><div class='gd-sec'><span class='gd-tag'>指路</span>在日本問路，常常會聽到這種說法。</div><div class='gd-ex-line'>・<span class='gd-jp'>まっすぐ行くと、右に駅があります。</span>（直直走，右邊就是車站）</div><div class='gd-sec'><span class='gd-tag'>固定習慣</span>每次做了A，都一定會接著做B。</div><div class='gd-ex-line'>・<span class='gd-jp'>父は家に帰ると、すぐテレビをつけます。</span>（我爸一回到家就馬上開電視）</div><div class='gd-h'>怎麼接</div><div class='gd-sec'>「と」前面放<b>沒有ます、也沒有過去式的普通說法</b>。動詞最常用辭書形，要說「不～」就用ない形。<br>動詞辭書形：<span class='gd-pair'><span class='gd-jp'>押す</span> → <span class='gd-jp'>押すと</span></span><br>動詞ない形：<span class='gd-pair'><span class='gd-jp'>急がない</span> → <span class='gd-jp'>急がないと</span></span><br>い形容詞直接接：<span class='gd-pair'><span class='gd-jp'>寒い</span> → <span class='gd-jp'>寒いと</span></span><br>な形容詞、名詞要先加だ：<span class='gd-pair'><span class='gd-jp'>雨</span> → <span class='gd-jp'>雨だと</span></span></div><div class='gd-ex-line'>・<span class='gd-jp'>急がないと、遅れるよ。</span>（不快一點的話，會遲到喔）</div><div class='gd-ex-line'>・<span class='gd-jp'>寒いと、手が冷たくなります。</span>（天氣一冷，手就會變冰）</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・「と」後面<b>不能接</b>拜託、命令、邀約，也不能接「我要～」這種自己的打算。因為「と」講的是自然就會發生的結果，不是你想做的事。<br>　×<span class='gd-jp'>駅に着くと、電話してください。</span><br>　○<span class='gd-jp'>駅に着いたら、電話してください。</span>（到車站的話，請打電話給我）<br>・「と」前面固定用<b>非過去的形（辭書形或ない形）</b>，就算講的是過去的事也一樣，過去式只放在句子最後：<span class='gd-jp'>子どものころ、冬になると、よく雪が降りました。</span>（小時候一到冬天就常下雪）。不能說「押したと」。<br>・「と」還有「和」（<span class='gd-jp'>友達と</span>）、「說」（<span class='gd-jp'>と言います</span>）的意思。前面是一個動作或一句話，後面又接著另一件事，才是這個「一～就～」。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'><b>と</b>＝一A就B，每次都這樣，後面只放「會發生的事」：<span class='gd-jp'>春になると、桜が咲きます。</span>（一到春天櫻花就開）<br><b>たら</b>＝A之後再做B，後面可以接拜託、邀約、自己的打算：<span class='gd-jp'>春になったら、花見に行こう。</span>（到了春天，我們去賞花吧）<br><b>ば</b>＝強調「只要有A這個條件」：<span class='gd-jp'>このボタンを押せば、ドアが開きます。</span>（只要按這個按鈕，門就會開）<br><b>なら</b>＝接著對方說的話給建議：<span class='gd-jp'>京都へ行くなら、春がいいですよ。</span>（如果你要去京都，春天比較好喔）</div><div class='gd-warn'>判斷小訣竅：後面想說「請～」「一起～吧」「我要～」，就用たら；後面是「一定會這樣」的結果，就用と。</div><div class='gd-h'>學會之後可以接著學</div><div class='gd-sec'>「と」也能接在「いい」前面表示希望：<span class='gd-jp'>明日、晴れるといいですね。</span>（明天要是放晴就好了）這個用法在 n4-58 會講到。</div>",
  "n4-58": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>這個句型就是中文的<b>「～就好了」</b>。用在兩種情況：一種是<b>給建議</b>（「你問老師就好了啊」），一種是<b>許願</b>（「明天放晴就好了」，也就是「希望明天放晴」）。前面可以用たら、ば、と三種條件說法，後面接いい。</div><div class='gd-h'>什麼時候用</div><div class='gd-sec'><span class='gd-tag'>給建議</span>告訴對方「這樣做就可以解決」，語氣輕鬆，常配「よ」。</div><div class='gd-ex-line'>・<span class='gd-jp'>医者に相談したらいいですよ。</span>（找醫生談談就好了啊）</div><div class='gd-ex-line'>・<span class='gd-jp'>分からなかったら、先生に聞けばいいよ。</span>（不懂的話，問老師就好了）</div><div class='gd-ex-line'>・<span class='gd-jp'>疲れたときは、少し休むといいですよ。</span>（累的時候，稍微休息一下會比較好喔）</div><div class='gd-sec'><span class='gd-tag'>問怎麼辦</span>改成問句，就是「該怎麼做才好？」。這時幾乎都用たら或ば，非常常用。</div><div class='gd-ex-line'>・<span class='gd-jp'>駅までどう行けばいいですか。</span>（到車站要怎麼走才好？）</div><div class='gd-ex-line'>・<span class='gd-jp'>何を持っていったらいいですか。</span>（要帶什麼去比較好？）</div><div class='gd-sec'><span class='gd-tag'>許願</span>希望某件事發生，通常是自己控制不了的事，常配「ね」（跟對方說）或「なあ」（自言自語）。這種用法「といい」特別常見。</div><div class='gd-ex-line'>・<span class='gd-jp'>明日、晴れるといいですね。</span>（希望明天會放晴）</div><div class='gd-ex-line'>・<span class='gd-jp'>雨が降らないといいね。</span>（希望不要下雨）</div><div class='gd-ex-line'>・<span class='gd-jp'>試験に合格できたらいいなあ。</span>（要是能考上就好了）</div><div class='gd-h'>怎麼接</div><div class='gd-sec'><b>たら</b>：先變成た形，再加ら。<br><span class='gd-pair'><span class='gd-jp'>行く</span> → <span class='gd-jp'>行った</span> → <span class='gd-jp'>行ったら</span></span><span class='gd-pair'><span class='gd-jp'>食べる</span> → <span class='gd-jp'>食べた</span> → <span class='gd-jp'>食べたら</span></span></div><div class='gd-sec'><b>ば</b>：變成ば形。<br>第一類（五段動詞）：最後一個音換成同一行的「え」段音，加ば。<span class='gd-pair'><span class='gd-jp'>行く</span> → く換成け → <span class='gd-jp'>行けば</span></span><br>第二類（一段動詞）：把る拿掉，加れば。<span class='gd-pair'><span class='gd-jp'>食べる</span> → <span class='gd-jp'>食べれば</span></span><br>第三類（する・来る）：<span class='gd-pair'><span class='gd-jp'>する</span> → <span class='gd-jp'>すれば</span></span><span class='gd-pair'><span class='gd-jp'>来る</span> → <span class='gd-jp'>来れば</span>（くれば）</span></div><div class='gd-sec'><b>と</b>：前面用<b>非過去的普通形</b>，也就是辭書形或ない形；な形容詞、名詞要加だ。<br><span class='gd-pair'><span class='gd-jp'>晴れる</span> → <span class='gd-jp'>晴れるといい</span></span><span class='gd-pair'><span class='gd-jp'>降らない</span> → <span class='gd-jp'>降らないといい</span></span><span class='gd-pair'><span class='gd-jp'>元気</span> → <span class='gd-jp'>元気だといい</span></span></div><div class='gd-h'>加上のに：可惜沒那樣</div><div class='gd-sec'>句尾變成「ばいいのに」「たらいいのに」，意思是「要是～就好了，偏偏不是」，帶著可惜或不滿。</div><div class='gd-ex-line'>・<span class='gd-jp'>早く春が来ればいいのに。</span>（春天快點來就好了，偏偏還沒來）</div><div class='gd-ex-line'>・<span class='gd-jp'>早く言えばいいのに。</span>（早點講不就好了）</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・「と」前面不能用た形：<span class='gd-jp'>飲むといい</span>、<span class='gd-jp'>降らないといい</span>是對的，<span class='gd-jp'>飲んだといい</span>是錯的。<br>・「～たらいいですよ」有「我教你」的感覺，對老師、主管講會有點不客氣，改用<span class='gd-jp'>〜たらいかがですか</span>比較禮貌。<br>・「～ばいいのに」對別人講常帶抱怨，像<span class='gd-jp'>早く言えばいいのに</span>是在念對方，不要對長輩用。<br>・中文「希望明天放晴」不要直翻成「希望します」，日本人日常就說<span class='gd-jp'>明日晴れるといいですね</span>。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'>三個都以「いい」結尾，但意思不同：<br><span class='gd-jp'>薬を飲んだほうがいいですよ。</span>（你最好吃藥）→ <b>ほうがいい</b>是忠告，暗示「不吃不好」，語氣較強。<br><span class='gd-jp'>薬を飲んだらいいですよ。</span>（吃個藥就好了啊）→ <b>たらいい</b>是輕鬆給一個辦法。<br><span class='gd-jp'>薬を飲んでもいいですよ。</span>（你可以吃藥喔）→ <b>てもいい</b>是允許，沒有在建議。</div><div class='gd-warn'>判斷小訣竅：「最好～」用ほうがいい，「～就好了」用たらいい，「可以～」用てもいい。</div><div class='gd-h'>學會之後可以接著學</div><div class='gd-sec'>過去式<span class='gd-jp'>〜ばよかった</span>是「當初～就好了」，用來表達後悔：<span class='gd-jp'>もっと勉強すればよかった。</span>（當初多讀一點書就好了）</div>",
  "n4-64": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「〜させていただきます」就是中文的<b>「請容我～」「那我就～了」</b>。說的是<b>自己</b>要做的事，但口氣放得很低，好像是「承蒙您允許，我才做」。開會、上台、跟主管或客人講話時很常聽到。</div><div class='gd-h'>什麼時候用</div><div class='gd-sec'><span class='gd-tag'>上台、正式場合</span>要開始說明、自我介紹、發表時，先講一句。</div><div class='gd-ex-line'>・<span class='gd-jp'>では、説明させていただきます。</span>（那麼，請容我來說明）</div><div class='gd-ex-line'>・<span class='gd-jp'>自己紹介させていただきます。</span>（請容我自我介紹）</div><div class='gd-sec'><span class='gd-tag'>影響到對方的事</span>請假、早退、用別人的東西這種會影響到對方的事，用它講得比較客氣。</div><div class='gd-ex-line'>・<span class='gd-jp'>明日は休ませていただきます。</span>（明天請容我休假）</div><div class='gd-sec'><span class='gd-tag'>店家公告</span>店門口貼的告示也很常見。</div><div class='gd-ex-line'>・<span class='gd-jp'>本日は休ませていただきます。</span>（本日公休）</div><div class='gd-h'>怎麼接</div><div class='gd-sec'>先把動詞變成「讓～做」的使役形，再變成て形「〜させて／〜せて」，後面加<span class='gd-jp'>いただきます</span>。</div><div class='gd-h'>怎麼變：先看動詞是哪一類</div><div class='gd-sec'><b>第一類（五段動詞）</b>：最後一個音換成同一行的「あ」段音，加「せて」，再加いただきます。<br><span class='gd-pair'><span class='gd-jp'>休む</span> → む換成ま → <span class='gd-jp'>休ませていただきます</span></span><br><span class='gd-pair'><span class='gd-jp'>帰る</span> → <span class='gd-jp'>帰らせていただきます</span></span><br>結尾是「う」的要特別注意，「う」是換成「わ」：<span class='gd-pair'><span class='gd-jp'>使う</span> → <span class='gd-jp'>使わせていただきます</span></span></div><div class='gd-sec'><b>第二類（一段動詞）</b>：把最後的「る」拿掉，加「させて」，再加いただきます。<br><span class='gd-pair'><span class='gd-jp'>考える</span> → <span class='gd-jp'>考えさせていただきます</span></span></div><div class='gd-sec'><b>第三類（只有兩個，直接背）</b>：<br><span class='gd-pair'><span class='gd-jp'>する</span> → <span class='gd-jp'>させていただきます</span></span>（<span class='gd-jp'>説明する</span>就是<span class='gd-jp'>説明させていただきます</span>）<br><span class='gd-pair'><span class='gd-jp'>来る</span> → <span class='gd-jp'>来させていただきます</span>（こさせて）</span>，這個比較少用。</div><div class='gd-sec'>整理一下：<b>只有第二類和第三類（する → させて、来る → 来させて）才有「さ」</b>，第一類是直接「あ段＋せて」。</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・第一類不要多加「さ」：是<span class='gd-jp'>休ませていただきます</span>，不是休まさせていただきます；是<span class='gd-jp'>読ませていただきます</span>，不是読まさせて。這個錯連日本人都常犯，但考試算錯。<br>・<span class='gd-jp'>使う</span>變<span class='gd-jp'>使わせて</span>，不是使あせて。<br>・它講的永遠是<b>自己</b>要做的事，不能拿來講別人。<br>・它其實不太是在「問」，比較像客氣地<b>告知</b>「我要這樣做了」。真的想徵求同意，要用下面的「〜させていただけませんか」。<br>・不要什麼都套：跟對方沒關係、也不需要誰同意的事，一直講「させていただきます」會顯得很繞，用普通的「〜ます」就好。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'>同樣是「今天想早點下班」，跟主管講有三種說法：<br><b>させていただきます</b>＝客氣地告知，幾乎是已經決定了：<br><span class='gd-jp'>今日は早く帰らせていただきます。</span>（今天請容我先早點走）<br><b>させてください</b>＝拜託對方讓你做，比較直接：<br><span class='gd-jp'>今日は早く帰らせてください。</span>（今天請讓我早點走）<br><b>させていただけませんか</b>＝真的在問，對方可以拒絕，最客氣：<br><span class='gd-jp'>今日は早く帰らせていただけませんか。</span>（今天可以讓我早點走嗎）</div><div class='gd-warn'>判斷小訣竅：結尾是「ます」是在<b>告知</b>，「ください」是在<b>拜託</b>，「ませんか」才是真的在<b>問</b>。還沒拿到同意之前，用「〜させていただけませんか」最保險。</div><div class='gd-h'>學會之後可以接著學</div><div class='gd-sec'>接著看「謙讓語」，像<span class='gd-jp'>参ります</span>、<span class='gd-jp'>申します</span>這種把自己放低的專用說法，跟「させていただきます」常常一起出現。</div>",
  "n4-65": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>中文會把「你叫什麼名字」說成「請問<b>您的大名</b>」，日文也有類似的做法：在名詞前面加<b>お</b>或<b>ご</b>，聽起來就比較客氣、比較好聽。<br>「<span class='gd-jp'>ございます</span>」則是<span class='gd-jp'>あります</span>的<b>店員、飯店版</b>，意思一樣是「有、在」，只是更有禮貌。</div><div class='gd-h'>お・ご什麼時候用</div><div class='gd-sec'><span class='gd-tag'>對方的東西</span>講到對方的名字、家人、地址，加上お・ご表示尊重。</div><div class='gd-ex-line'>・<span class='gd-jp'>お名前をお願いします。</span>（麻煩告訴我您的名字）</div><div class='gd-ex-line'>・<span class='gd-jp'>ご家族はお元気ですか。</span>（您的家人都好嗎）</div><div class='gd-sec'><span class='gd-tag'>讓話好聽</span>有些詞加了お・ご只是比較文雅，講自己的事也可以用，日常生活非常常見。</div><div class='gd-ex-line'>・<span class='gd-jp'>お茶を飲みませんか。</span>（要不要喝杯茶）</div><div class='gd-ex-line'>・<span class='gd-jp'>もうご飯を食べました。</span>（我已經吃過飯了）</div><div class='gd-h'>怎麼接：お還是ご？</div><div class='gd-sec'><b>日本原本就有的詞</b>（漢字念日式念法，或本來就是平假名的詞），多半加<b>お</b>：<br><span class='gd-jp'>お名前</span>、<span class='gd-jp'>お店</span>、<span class='gd-jp'>お水</span>、<span class='gd-jp'>お手紙</span></div><div class='gd-sec'><b>從中文來的漢字詞</b>（念起來有點像中文，常常是兩個漢字），多半加<b>ご</b>：<br><span class='gd-jp'>ご住所</span>、<span class='gd-jp'>ご家族</span>、<span class='gd-jp'>ご予約</span>、<span class='gd-jp'>ご連絡</span></div><div class='gd-sec'>不過<b>例外不少</b>，像<span class='gd-jp'>お電話</span>、<span class='gd-jp'>お時間</span>、<span class='gd-jp'>お食事</span>都是漢字詞，卻固定加お。遇到就一個一個記，不用硬套規則。<br>片假名的外來語通常不加：說<span class='gd-jp'>コーヒー</span>就好。</div><div class='gd-h'>ございます：あります的客氣版</div><div class='gd-sec'><span class='gd-pair'><span class='gd-jp'>あります</span> → <span class='gd-jp'>ございます</span></span><span class='gd-pair'><span class='gd-jp'>ありません</span> → <span class='gd-jp'>ございません</span></span><span class='gd-pair'><span class='gd-jp'>ありました</span> → <span class='gd-jp'>ございました</span></span><br>你其實早就會講了：<span class='gd-jp'>ありがとうございます</span>、<span class='gd-jp'>おはようございます</span>裡的就是它。</div><div class='gd-ex-line'>・<span class='gd-jp'>お手洗いはあちらにございます。</span>（洗手間在那邊）</div><div class='gd-ex-line'>・<span class='gd-jp'>赤いのもございますよ。</span>（也有紅色的喔）</div><div class='gd-ex-line'>・<span class='gd-jp'>申し訳ございません。</span>（非常抱歉）</div><div class='gd-sec'>另外，<b>でございます</b>＝<span class='gd-jp'>です</span>的客氣版，店員介紹東西很常用：</div><div class='gd-ex-line'>・<span class='gd-jp'>こちらがメニューでございます。</span>（這是菜單）</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・表示尊重的お・ご<b>不能放在自己身上</b>：自我介紹說<span class='gd-jp'>私の名前は</span>，不能說「私のお名前は」。只有<span class='gd-jp'>お茶</span>、<span class='gd-jp'>ご飯</span>這種「讓話好聽」的詞，自己也能用。<br>・<span class='gd-jp'>ございます</span>只用在<b>東西、事情</b>，不能用在人身上。「人在不在」要用下面的<span class='gd-jp'>おります</span>或<span class='gd-jp'>いらっしゃいます</span>。<br>・「でございます」不能拿來說對方：問「您是田中先生嗎」要說<span class='gd-jp'>田中様でいらっしゃいますか</span>，不是「田中様でございますか」。<br>・お・ご不是加越多越好，加在不習慣加的詞上反而怪。課本、店員常講的那些先學起來就夠用。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'>同樣在一家店裡，講「有、在」：<br><b>あります</b>（一般客氣）：<span class='gd-jp'>トイレはあちらにあります。</span>（廁所在那邊）<br><b>ございます</b>（更客氣，講東西）：<span class='gd-jp'>お手洗いはあちらにございます。</span>（洗手間在那邊）<br><b>おります</b>（講自己這邊的人，壓低自己）：<span class='gd-jp'>店長は事務所におります。</span>（店長在辦公室）<br><b>いらっしゃいます</b>（講對方或客人，抬高對方）：<span class='gd-jp'>田中様はいらっしゃいますか。</span>（請問田中先生在嗎）</div><div class='gd-warn'>判斷小訣竅：講<b>東西</b>用ございます；講<b>人</b>，自己人用おります，對方用いらっしゃいます。</div><div class='gd-h'>學會之後可以接著學</div><div class='gd-sec'>お・ご也能加在動詞上，變成尊敬或謙虛的說法，例如<span class='gd-jp'>少々お待ちください。</span>（請稍等一下），可以接著看「尊敬語」「謙譲語」。</div>",
  "n4-66": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>縮約表現就是日文的<b>講快了黏在一起</b>。就像中文「這樣子」講快會變成「醬」，日本人聊天時也會把<span class='gd-jp'>見ている</span>講成<span class='gd-jp'>見てる</span>。意思完全一樣，只是比較口語、比較隨興。</div><div class='gd-h'>什麼時候用</div><div class='gd-sec'><span class='gd-tag'>日常聊天</span>跟朋友、家人講話，日劇、動畫、漫畫裡幾乎都是這種說法。</div><div class='gd-sec'><span class='gd-tag'>不要用</span>寫報告、寄信給主管、面試這種正式場合，要用完整的形。</div><div class='gd-h'>最常聽到的四種</div><div class='gd-sec'><b>1. ている → てる</b>：把中間的「い」拿掉。<br><span class='gd-pair'><span class='gd-jp'>見ている</span> → い拿掉 → <span class='gd-jp'>見てる</span></span><br>原本是「でいる」就變「でる」：<span class='gd-pair'><span class='gd-jp'>読んでいる</span> → <span class='gd-jp'>読んでる</span></span></div><div class='gd-ex-line'>・<span class='gd-jp'>何してるの？</span>（你在幹嘛？）</div><div class='gd-sec'><b>2. ておく → とく</b>：「て」和「お」黏成一個「と」。<br><span class='gd-pair'><span class='gd-jp'>買っておく</span> → <span class='gd-jp'>買っとく</span></span><br>原本是「でおく」就變「どく」：<span class='gd-pair'><span class='gd-jp'>読んでおく</span> → <span class='gd-jp'>読んどく</span></span></div><div class='gd-ex-line'>・<span class='gd-jp'>飲み物、買っとくね。</span>（飲料我先買好喔）</div><div class='gd-sec'><b>3. てしまう → ちゃう</b>：「てしま」縮成「ちゃ」。<br><span class='gd-pair'><span class='gd-jp'>食べてしまう</span> → <span class='gd-jp'>食べちゃう</span></span><br>原本是「でしまう」就變「じゃう」：<span class='gd-pair'><span class='gd-jp'>飲んでしまう</span> → <span class='gd-jp'>飲んじゃう</span></span></div><div class='gd-ex-line'>・<span class='gd-jp'>ケーキ、全部食べちゃった。</span>（蛋糕我全部吃掉了）</div><div class='gd-sec'><b>4. では → じゃ</b>：<span class='gd-pair'><span class='gd-jp'>学生ではない</span> → <span class='gd-jp'>学生じゃない</span></span></div><div class='gd-h'>縮完之後還是可以變</div><div class='gd-sec'>縮好的樣子可以照常變過去、否定、て形：<br><span class='gd-pair'><span class='gd-jp'>見てる</span> → <span class='gd-jp'>見てた</span>／<span class='gd-jp'>見てない</span></span><br><span class='gd-pair'><span class='gd-jp'>買っとく</span> → <span class='gd-jp'>買っといた</span>／<span class='gd-jp'>買っといて</span></span><br><span class='gd-pair'><span class='gd-jp'>食べちゃう</span> → <span class='gd-jp'>食べちゃった</span></span></div><div class='gd-ex-line'>・<span class='gd-jp'>宿題、まだ終わってない。</span>（作業還沒寫完）</div><div class='gd-ex-line'>・<span class='gd-jp'>明日までに読んどいて。</span>（明天之前先讀好喔）</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・原本是「で」的，縮完也要變濁音：是<span class='gd-jp'>飲んじゃう</span>，不是飲んちゃう；是<span class='gd-jp'>読んどく</span>，不是読んとく。<br>・<span class='gd-jp'>見てる</span>（正在看）和<span class='gd-jp'>見とく</span>（先看好）聽起來很像，意思卻完全不同，聽的時候要注意。<br>・<span class='gd-jp'>見てます</span>這種「縮約＋ます」在店裡、同事之間講話很常聽到，但寫文件、寫信還是要寫<span class='gd-jp'>見ています</span>。<br>・縮約只是講法變輕鬆，意思沒變：<span class='gd-jp'>ちゃう</span>一樣可以是「做完」，也可以是「不小心、糟糕」。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'><span class='gd-jp'>ては</span>也會縮成<span class='gd-jp'>ちゃ</span>，跟<span class='gd-jp'>ちゃう</span>只差一點，意思卻差很多：<br><span class='gd-jp'>食べちゃった。</span>（吃掉了）＝<span class='gd-jp'>食べてしまった</span><br><span class='gd-jp'>食べちゃだめ。</span>（不可以吃）＝<span class='gd-jp'>食べてはだめ</span></div><div class='gd-warn'>判斷小訣竅：後面是「う」「った」，就是てしまう；後面接「だめ」「いけない」，就是ては。</div><div class='gd-h'>學會之後可以接著學</div><div class='gd-sec'>「なければ」口語會縮成「なきゃ」：<span class='gd-jp'>もう帰らなきゃ。</span>（我得回家了）</div>",
  "n4-67": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「何、誰、どこ、いつ」這些平常拿來問問題的字，後面加上「でも」，就變成中文的<b>「什麼都～」「誰都～」「哪裡都～」「隨時都～」</b>。意思是全部都可以，沒有例外。</div><div class='gd-h'>最常聽到的樣子</div><div class='gd-sec'><span class='gd-jp'>何でも</span>＝什麼都<br><span class='gd-jp'>誰でも</span>＝誰都<br><span class='gd-jp'>どこでも</span>＝哪裡都<br><span class='gd-jp'>いつでも</span>＝隨時、什麼時候都<br><span class='gd-jp'>どれでも</span>＝哪一個都（三個以上選）<br><span class='gd-jp'>どちらでも</span>＝哪一邊都（兩個選一個）<br><span class='gd-jp'>どんな</span>＋名詞＋<span class='gd-jp'>でも</span>＝不管什麼樣的～都</div><div class='gd-ex-line'>・<span class='gd-jp'>私は何でも食べます。</span>（我什麼都吃）</div><div class='gd-ex-line'>・<span class='gd-jp'>この問題は誰でもできます。</span>（這題誰都會）</div><div class='gd-ex-line'>・<span class='gd-jp'>いつでも連絡してください。</span>（隨時都可以聯絡我）</div><div class='gd-ex-line'>・<span class='gd-jp'>どんな仕事でも頑張ります。</span>（不管什麼工作我都會努力）</div><div class='gd-sec'><span class='gd-tag'>回答「都可以」</span>後面接「いいです」，就是生活中超常用的「都可以」。</div><div class='gd-ex-line'>・<span class='gd-jp'>A：いつがいいですか。　B：いつでもいいですよ。</span>（A：什麼時候好？　B：什麼時候都可以喔）</div><div class='gd-ex-line'>・<span class='gd-jp'>赤と青、どちらでもいいです。</span>（紅的藍的，哪個都可以）</div><div class='gd-h'>原本的助詞怎麼辦</div><div class='gd-sec'><b>が、を</b>：直接消失，不用留。<br><span class='gd-pair'><span class='gd-jp'>何を食べますか</span> → <span class='gd-jp'>何でも食べます</span></span>（不會說何をでも）<br><b>に、と、へ</b>這類：要留下來，放在でも前面。</div><div class='gd-ex-line'>・<span class='gd-jp'>彼は誰にでも優しいです。</span>（他對誰都很溫柔）</div><div class='gd-ex-line'>・<span class='gd-jp'>妹は誰とでもすぐ友だちになれます。</span>（我妹妹跟誰都能馬上變成朋友）</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・<span class='gd-jp'>何でも</span>念<b>なんでも</b>，不是なにでも。<br>・想說「什麼都<b>不</b>～」不能用でも，要用「も」再加否定：<span class='gd-jp'>何も食べません</span>（什麼都不吃）。<span class='gd-jp'>何でも食べません</span>不是「什麼都不吃」的意思，不要這樣講。<br>・朋友認真問你「想吃什麼？」，如果只平平地回<span class='gd-jp'>何でもいいです</span>，聽起來可能有點像「隨便啦」。可以說<span class='gd-jp'>何でも好きです</span>（我什麼都喜歡），或乾脆提一個。<br>・前面不是疑問詞的話，でも是別的意思：<span class='gd-jp'>子どもでもわかります</span>是「連小孩都懂」。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'>同一個「何」，後面接的字不一樣，意思差很多：<br><span class='gd-jp'>何でも食べます。</span>（什麼都吃：全部OK）<br><span class='gd-jp'>何も食べません。</span>（什麼都不吃：一個都沒有）<br><span class='gd-jp'>何か食べます。</span>（吃點什麼：某個東西，還沒決定是什麼）<br><br>換成「誰」也一樣：<br><span class='gd-jp'>誰でも知っています。</span>（誰都知道）<br><span class='gd-jp'>誰も知りません。</span>（沒有人知道）<br><span class='gd-jp'>誰か知っていますか。</span>（有沒有人知道？）</div><div class='gd-warn'>判斷小訣竅：「全部都OK」用<b>でも</b>；「一個都沒有」用<b>も</b>，後面接否定；「某一個，但不確定是哪個」用<b>か</b>。</div><div class='gd-h'>學會之後可以接著學</div><div class='gd-sec'>疑問詞後面接動詞的「ても」，就是「不管做什麼都～」：<span class='gd-jp'>何を言っても、彼は聞きません。</span>（不管說什麼，他都不聽）</div>",
  "n4-68": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「とか」就是中文聊天時講的<b>「～啊～啊之類的」「像是～之類的」</b>。隨口舉幾個例子，意思是「不只這些，還有別的」。比「や」更口語，朋友之間最常聽到。</div><div class='gd-h'>什麼時候用</div><div class='gd-sec'><span class='gd-tag'>隨口舉例</span>舉兩三個例子，表示還有其他的。</div><div class='gd-ex-line'>・<span class='gd-jp'>コンビニでパンとかおにぎりとか買った。</span>（在便利商店買了麵包啊飯糰之類的）</div><div class='gd-sec'><span class='gd-tag'>只舉一個，讓口氣軟一點</span>約人、給建議時，只說一個也可以，聽起來比較不強迫，像中文「要不要去吃個飯什麼的」。</div><div class='gd-ex-line'>・<span class='gd-jp'>今度、ご飯とか行かない？</span>（下次要不要去吃個飯之類的？）</div><div class='gd-ex-line'>・<span class='gd-jp'>疲れたら、少し寝るとかしたほうがいいよ。</span>（累的話，最好小睡一下什麼的）</div><div class='gd-sec'><span class='gd-tag'>轉述聽來的話</span>「～とか言ってた」＝「好像說～」，表示你記得大概，不是很確定。</div><div class='gd-ex-line'>・<span class='gd-jp'>田中さん、来週休むとか言ってたよ。</span>（田中好像說下週要請假）</div><div class='gd-h'>怎麼接</div><div class='gd-sec'><b>名詞</b>：直接加とか。<span class='gd-pair'><span class='gd-jp'>パン</span> → <span class='gd-jp'>パンとかおにぎりとか</span></span><br><b>動詞</b>：用沒有ます的普通說法（辭書形）再加とか。<span class='gd-pair'><span class='gd-jp'>寝ます</span> → <span class='gd-jp'>寝るとか</span></span><br>最後一個とか後面可以再接「を」「に」「が」，但聊天時「を」常常直接省掉：<span class='gd-jp'>お茶とかお菓子とか買ってきた。</span>（買了茶啊點心之類的回來）</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・とか很口語。寫報告、跟主管或客人講話時，名詞用「や」，做的事用「〜たり〜たりする」比較穩。<br>・最常見的是每個都加とか（<span class='gd-jp'>AとかBとか</span>），只加在第一個也會聽到，但「とか」一出現，就代表還有別的，不是全部。<br>・「とか」跟「と」只差一個字，意思差很多：<span class='gd-jp'>と</span>是「就這些」，<span class='gd-jp'>とか</span>是「舉幾個例子」。<br>・有些人講話每句都夾とか，聽起來會有點含糊、不夠肯定，正式場合不要一直用。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'>同樣講冰箱裡有什麼：<br><b>と</b>＝全部列出來，就這些：<span class='gd-jp'>冷蔵庫に牛乳と卵があります。</span>（冰箱裡有牛奶和蛋）<br><b>や</b>＝舉例，還有別的，一般講法：<span class='gd-jp'>冷蔵庫に牛乳や卵があります。</span>（冰箱裡有牛奶、蛋等等）<br><b>とか</b>＝舉例，還有別的，聊天口氣：<span class='gd-jp'>冷蔵庫に牛乳とか卵とかあるよ。</span>（冰箱裡有牛奶啊蛋之類的喔）</div><div class='gd-sec'>另外，「や」只能接名詞。想列舉「做的事」，一般用<b>「〜たり〜たりする」</b>；聊天時也可以用とか，但比較口語。<br><span class='gd-jp'>週末は本を読んだり、音楽を聞いたりします。</span>（週末會看看書、聽聽音樂：一般說法）<br><span class='gd-jp'>週末は本を読むとか、音楽を聞くとかしてる。</span>（週末就看看書啊、聽聽音樂之類的：聊天口氣）</div><div class='gd-warn'>判斷小訣竅：全部就這些用「と」；舉例的名詞，正式一點用「や」、聊天用「とか」；舉例做的事，一般用「たり」、聊天也可以用「とか」。</div><div class='gd-h'>學會之後可以接著學</div><div class='gd-sec'>同樣是「一個一個列出來」，助詞<span class='gd-jp'>し</span>是用來列舉<b>理由</b>：<span class='gd-jp'>安いし、おいしいし、よくこの店に来る。</span>（又便宜又好吃，所以常來這家店）</div>",
  "n4-69": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「〜ずに」就是「〜ないで」的<b>正式版</b>，意思是「沒～就～」「不～而～」。就像中文口語說「沒講一聲就走了」，寫文章會寫「不告而別」，意思一樣，只是比較書面、比較文雅。</div><div class='gd-h'>什麼時候用</div><div class='gd-sec'><span class='gd-tag'>沒做A就做B</span>本來該做的事沒做，就直接做下一件事。</div><div class='gd-ex-line'>・<span class='gd-jp'>朝ご飯を食べずに出かけた。</span>（沒吃早餐就出門了）</div><div class='gd-ex-line'>・<span class='gd-jp'>誰にも言わずに会社を辞めた。</span>（沒跟任何人說就辭職了）</div><div class='gd-sec'><span class='gd-tag'>不用A，改用B</span>放棄一種做法，換另一種。</div><div class='gd-ex-line'>・<span class='gd-jp'>バスに乗らずに、歩いて帰った。</span>（沒搭公車，走路回家）</div><div class='gd-h'>怎麼變：先看動詞是哪一類</div><div class='gd-sec'>先把動詞變成ない形，再把「ない」拿掉，換成「ず」或「ずに」。</div><div class='gd-sec'><b>第一類（五段動詞）</b>：<br><span class='gd-pair'><span class='gd-jp'>行く</span> → <span class='gd-jp'>行かない</span> → <span class='gd-jp'>行かず</span></span><br><span class='gd-pair'><span class='gd-jp'>言う</span> → <span class='gd-jp'>言わず</span></span><br><span class='gd-pair'><span class='gd-jp'>持つ</span> → <span class='gd-jp'>持たず</span></span></div><div class='gd-sec'><b>第二類（一段動詞）</b>：<br><span class='gd-pair'><span class='gd-jp'>食べる</span> → <span class='gd-jp'>食べない</span> → <span class='gd-jp'>食べず</span></span><br><span class='gd-pair'><span class='gd-jp'>見る</span> → <span class='gd-jp'>見ず</span></span></div><div class='gd-sec'><b>第三類（只有兩個，直接背）</b>：<br><span class='gd-pair'><span class='gd-jp'>する</span> → <span class='gd-jp'>せず</span></span>（不是しず）<br><span class='gd-pair'><span class='gd-jp'>来る</span> → <span class='gd-jp'>来ず</span>（こず）</span></div><div class='gd-h'>最常聽到的樣子</div><div class='gd-sec'>雖然整體偏書面，但有幾個講法日本人平常說話也很常用，可以直接整句背：</div><div class='gd-ex-line'>・<span class='gd-jp'>遠慮せずに食べてください。</span>（別客氣，請吃）</div><div class='gd-ex-line'>・<span class='gd-jp'>気にせずに休んでね。</span>（別在意，好好休息喔）</div><div class='gd-ex-line'>・<span class='gd-jp'>思わず笑ってしまった。</span>（忍不住笑了出來）</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・<b>する要變せず</b>，不是しず：<span class='gd-jp'>勉強せずに</span>。<br>・「う」結尾的第一類，ない形是「わ」：<span class='gd-jp'>言わず</span>、<span class='gd-jp'>買わず</span>，不是言あず。<br>・<span class='gd-jp'>来ず</span>念<b>こず</b>，不是きず。<br>・不能拿來拜託別人：「請不要～」只能說<span class='gd-jp'>食べないでください</span>，沒有「食べずにください」這種說法。<br>・跟朋友聊天時，一般動詞多半用「ないで」，整篇都用「ずに」會有點像在念稿；上面那幾個固定說法例外。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'><b>ないで</b>＝口語版：<span class='gd-jp'>傘を持たないで出かけた。</span>（沒帶傘就出門了）<br><b>ずに</b>＝正式、書面版，意思完全一樣：<span class='gd-jp'>傘を持たずに出かけた。</span>（沒帶傘就出門了）<br>另外在文章裡，常看到「ず」後面直接接逗號，這時候常常是「因為沒～」的意思，跟「なくて」很像：<span class='gd-jp'>バスが来ず、遅刻してしまった。</span>（公車沒來，結果遲到了）</div><div class='gd-warn'>判斷小訣竅：看到「ずに」，在腦中換成「ないで」就懂了；講話時拿不定主意，就用「ないで」最安全。</div>",
  "n4-70": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「こと」就是中文的<b>「～這件事」</b>。中文可以直接說「看書很好玩」，日文不行，動詞不能直接當主角，要先在後面加「こと」，把「看書」包裝成「看書這件事」，才能放進句子裡當主角或答案。</div><div class='gd-h'>什麼時候用</div><div class='gd-sec'><span class='gd-tag'>當句子的主角</span>放在「は」「が」前面，後面再說它怎麼樣。</div><div class='gd-ex-line'>・<span class='gd-jp'>毎日運動することは大切です。</span>（每天運動很重要）</div><div class='gd-ex-line'>・<span class='gd-jp'>遅刻しないことが大切です。</span>（不遲到很重要）</div><div class='gd-sec'><span class='gd-tag'>當答案</span>「我的興趣是～」「我的夢想是～」，後面的「～」是一個動作時，就用「～ことです」。</div><div class='gd-ex-line'>・<span class='gd-jp'>私の趣味は写真を撮ることです。</span>（我的興趣是拍照）</div><div class='gd-ex-line'>・<span class='gd-jp'>夢は日本で働くことです。</span>（我的夢想是在日本工作）</div><div class='gd-h'>怎麼接</div><div class='gd-sec'>動詞直接接，不用變形：<span class='gd-pair'><span class='gd-jp'>読む</span> → <span class='gd-jp'>読むこと</span></span><br>「不做」用ない形：<span class='gd-pair'><span class='gd-jp'>読まない</span> → <span class='gd-jp'>読まないこと</span></span><br>「做過」用た形：<span class='gd-pair'><span class='gd-jp'>読んだ</span> → <span class='gd-jp'>読んだこと</span></span><br>形容詞也可以接，這時候比較像「～的事」：<span class='gd-pair'><span class='gd-jp'>楽しい</span> → <span class='gd-jp'>楽しいこと</span></span>（開心的事）。な形容詞要記得加な：<span class='gd-pair'><span class='gd-jp'>好き</span> → <span class='gd-jp'>好きなこと</span></span>（喜歡的事）</div><div class='gd-sec'>其實你早就見過它了：<span class='gd-jp'>ことができます</span>、<span class='gd-jp'>たことがあります</span>、<span class='gd-jp'>ことにします</span>裡面的「こと」，都是這個「～這件事」。</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・照中文直覺，動詞直接拿來當主角：<span class='gd-jp'>本を読むが好きです</span>是錯的，中間一定要有<span class='gd-jp'>こと</span>或<span class='gd-jp'>の</span>：<span class='gd-jp'>本を読むことが好きです</span>。<br>・な形容詞忘了加な：要說<span class='gd-jp'>好きなこと</span>，不是好きこと，也不是好きだこと。<br>・「名詞＋のこと」是另一個意思，表示「關於～」：<span class='gd-jp'>彼のことが好きです</span>是「我喜歡他（這個人）」，跟這裡把動作變成名詞的用法不一樣，不要混在一起。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'>「の」也可以把動作變成「～這件事」，很多時候兩個都能用，但<b>有些位置只能用其中一個</b>，不是單純「こと比較書面」而已。</div><div class='gd-sec'><span class='gd-tag'>兩個都行</span>前面是「好き」「大切」「難しい」這類評價時。</div><div class='gd-ex-line'>・<span class='gd-jp'>本を読むのが好きです。</span>（我喜歡看書：聊天比較常用）</div><div class='gd-ex-line'>・<span class='gd-jp'>本を読むことが好きです。</span>（我喜歡看書：稍微正式一點）</div><div class='gd-sec'><span class='gd-tag'>只能用こと</span>句尾「～は～ことです」，還有ことができます這類固定句型。</div><div class='gd-ex-line'>・<span class='gd-jp'>趣味は本を読むことです。</span>（我的興趣是看書）</div><div class='gd-sec'>換成「のです」就不對了，這裡的「の」會被聽成解釋語氣的「のです」，句子很不自然，所以句尾一定要用「ことです」。同樣，<span class='gd-jp'>日本語を話すことができます</span>也不能換成の。</div><div class='gd-sec'><span class='gd-tag'>只能用の</span>親眼看到、親耳聽到某個動作正在發生。</div><div class='gd-ex-line'>・<span class='gd-jp'>犬が走るのを見ました。</span>（我看到狗在跑）</div><div class='gd-ex-line'>・<span class='gd-jp'>隣の部屋で誰かが歌っているのが聞こえます。</span>（聽得到隔壁房間有人在唱歌）</div><div class='gd-sec'>這裡說<span class='gd-jp'>走ることを見ました</span>、<span class='gd-jp'>歌っていることが聞こえます</span>都不行。</div><div class='gd-warn'>判斷小訣竅：句尾「～です」前面、還有ことができる這種固定句型用<b>こと</b>；看到、聽到眼前的動作用<b>の</b>；「好き」「大切」這種兩個都行，聊天時用の比較順口。</div>",
  "n4-71": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>中文說「有一股香味」「傳來奇怪的聲音」，日文不用「有（ある）」，而是用<b>「名詞＋がする」</b>。意思是有聲音、味道、氣味自己冒出來，被你感覺到了。客氣一點說就是「がします」。</div><div class='gd-h'>怎麼接</div><div class='gd-sec'>感覺到的東西（名詞）＋が＋します（朋友之間說する）。<br>前面通常會加一個形容詞，說明是什麼樣的聲音或味道：<br><span class='gd-pair'><span class='gd-jp'>匂い</span> → <span class='gd-jp'>いい匂いがします</span></span>（有香味）<br><span class='gd-pair'><span class='gd-jp'>音</span> → <span class='gd-jp'>変な音がします</span></span>（有奇怪的聲音）</div><div class='gd-h'>最常聽到的樣子</div><div class='gd-sec'><span class='gd-tag'>聲音</span><span class='gd-jp'>音</span>（東西的聲音）、<span class='gd-jp'>声</span>（人或動物的聲音）</div><div class='gd-ex-line'>・<span class='gd-jp'>外で変な音がします。</span>（外面有奇怪的聲音）</div><div class='gd-ex-line'>・<span class='gd-jp'>隣の部屋から子どもの声がする。</span>（隔壁房間傳來小孩的聲音）</div><div class='gd-sec'><span class='gd-tag'>氣味</span><span class='gd-jp'>匂い</span>、<span class='gd-jp'>香り</span>（香味，比較好聽的說法）</div><div class='gd-ex-line'>・<span class='gd-jp'>台所からいい匂いがする。</span>（廚房飄來香味）</div><div class='gd-sec'><span class='gd-tag'>味道</span>吃東西時嘗到的<span class='gd-jp'>味</span></div><div class='gd-ex-line'>・<span class='gd-jp'>このお茶、レモンの味がする。</span>（這個茶有檸檬的味道）</div><div class='gd-sec'><span class='gd-tag'>感覺</span><span class='gd-jp'>感じがする</span>是「給人～的感覺」，<span class='gd-jp'>気がする</span>是「我總覺得～」。<span class='gd-jp'>気がする</span>前面可以直接放一整句話（動詞用普通形，也就是沒有ます的樣子）。</div><div class='gd-ex-line'>・<span class='gd-jp'>あの人は優しい感じがします。</span>（那個人給人很溫柔的感覺）</div><div class='gd-ex-line'>・<span class='gd-jp'>前に会った気がします。</span>（我覺得以前好像見過你）</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・助詞用<b>が</b>，不是を：要說<span class='gd-jp'>音がする</span>，不能說「音をする」。<br>・說「現在聞到、聽到」的時候用がする，一般不會說「いい匂いがあります」。<br>・中文習慣說「<b>我</b>聞到香味」，日文的主角是<b>味道本身</b>，不說「私はいい匂いがします」。要講哪裡有味道，就說<span class='gd-jp'>この部屋は変な匂いがします</span>（這個房間有怪味）。<br>・<b>眼睛看到的不用がする</b>：顏色、形狀不能這樣講，不能說「きれいな色がします」。<br>・前面一定要是名詞：不能說「甘いがします」，要說<span class='gd-jp'>甘い匂いがします</span>或<span class='gd-jp'>甘い味がします</span>。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'><b>音がする vs 聞こえる</b><br><span class='gd-jp'>外で音がする。</span>（外面有聲音）：重點是<b>有聲音出現</b>。<br><span class='gd-jp'>外の音が聞こえる。</span>（聽得到外面的聲音）：重點是<b>聽不聽得到</b>，所以常用在<span class='gd-jp'>よく聞こえない</span>（聽不太清楚）這種情況。</div><div class='gd-sec'><b>気がする vs と思う</b><br><span class='gd-jp'>彼は来ないと思います。</span>（我認為他不會來）：比較明確的想法或判斷。<br><span class='gd-jp'>彼は来ない気がします。</span>（我總覺得他不會來）：說不太上來，是一種直覺，口氣比較不肯定。</div><div class='gd-warn'>判斷小訣竅：「有聲音、有味道」用がする，「聽不聽得到」用聞こえる；有把握的想法用と思う，只是一種直覺就用気がする。</div>",
  "n4-72": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「〜さ」就是把形容詞變成<b>名詞</b>，很像中文把「高」變成「高度」、把「重要」變成「重要性」。<span class='gd-jp'>高い</span>是「很高」，<span class='gd-jp'>高さ</span>就是「高度」。用來講某個東西<b>有多～</b>，或是它<b>～的那種感覺</b>。</div><div class='gd-h'>怎麼接</div><div class='gd-sec'><b>い形容詞</b>：把最後的「い」拿掉，加「さ」。<br><span class='gd-pair'><span class='gd-jp'>高い</span> → い拿掉 → <span class='gd-jp'>高さ</span></span>（高度）<br><span class='gd-pair'><span class='gd-jp'>深い</span> → <span class='gd-jp'>深さ</span></span>（深度）<span class='gd-pair'><span class='gd-jp'>重い</span> → <span class='gd-jp'>重さ</span></span>（重量）<span class='gd-pair'><span class='gd-jp'>寒い</span> → <span class='gd-jp'>寒さ</span></span>（寒冷）<span class='gd-pair'><span class='gd-jp'>大きい</span> → <span class='gd-jp'>大きさ</span></span>（大小）</div><div class='gd-sec'><b>な形容詞</b>：直接加「さ」，中間不用放な。<br><span class='gd-pair'><span class='gd-jp'>便利</span> → <span class='gd-jp'>便利さ</span></span>（方便）<span class='gd-pair'><span class='gd-jp'>親切</span> → <span class='gd-jp'>親切さ</span></span>（親切）<span class='gd-pair'><span class='gd-jp'>大切</span> → <span class='gd-jp'>大切さ</span></span>（重要性）</div><div class='gd-sec'><b>要特別背的</b>：<br><span class='gd-pair'><span class='gd-jp'>いい</span> → <span class='gd-jp'>よさ</span></span>（優點、好處。因為<span class='gd-jp'>いい</span>本來就是<span class='gd-jp'>よい</span>變來的，不說いいさ）<br><span class='gd-pair'><span class='gd-jp'>静か</span> → <span class='gd-jp'>静けさ</span></span>（寧靜。一般不說静かさ）</div><div class='gd-h'>什麼時候用</div><div class='gd-sec'><span class='gd-tag'>講數字、尺寸</span>高度、長度、重量這種可以量的東西，後面常接數字或「どのくらい」。</div><div class='gd-ex-line'>・<span class='gd-jp'>富士山の高さは3776メートルです。</span>（富士山的高度是3776公尺）</div><div class='gd-ex-line'>・<span class='gd-jp'>この部屋の広さはどのくらいですか。</span>（這個房間大概多大？）</div><div class='gd-sec'><span class='gd-tag'>講感受、特質</span>講某個東西給人的感覺有多強，或它的好處、特點。</div><div class='gd-ex-line'>・<span class='gd-jp'>北海道の冬の寒さにびっくりしました。</span>（北海道冬天的冷讓我嚇一跳）</div><div class='gd-ex-line'>・<span class='gd-jp'>病気になって、健康の大切さが分かりました。</span>（生病之後，我才懂健康有多重要）</div><div class='gd-ex-line'>・<span class='gd-jp'>この店のよさは安いところです。</span>（這家店的優點是便宜）</div><div class='gd-ex-line'>・<span class='gd-jp'>夜の静けさが好きです。</span>（我喜歡夜晚的寧靜）</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・い要拿掉：是<span class='gd-jp'>高さ</span>，不是高いさ。<br>・な形容詞不用加な：是<span class='gd-jp'>便利さ</span>，不是便利なさ。<br>・加了さ就是名詞了，前面用「の」接，後面接「は・が・を・に」：<span class='gd-jp'>冬の寒さ</span>，不是冬は寒さ。<br>・「高さ」「重さ」「大きさ」是<b>中性的量尺</b>，跟中文「高度」一樣。山再矮，問的時候還是說<span class='gd-jp'>高さ</span>，不會改說低さ。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'>你早就學過<span class='gd-jp'>楽しみ</span>，它跟<span class='gd-jp'>楽しさ</span>都從<span class='gd-jp'>楽しい</span>來，意思卻不一樣。<br><b>楽しさ</b>＝有多好玩、那份樂趣：<span class='gd-jp'>日本語の楽しさが分かりました。</span>（我懂了學日文的樂趣）<br><b>楽しみ</b>＝期待、盼望：<span class='gd-jp'>旅行を楽しみにしています。</span>（我很期待這趟旅行）</div><div class='gd-warn'>判斷小訣竅：講「多好玩、多冷、多重要」這種程度，用さ；講「很期待」，用<span class='gd-jp'>楽しみ</span>。</div><div class='gd-h'>學會之後可以接著學</div><div class='gd-sec'>問尺寸時很好用的句型：<span class='gd-jp'>〜の長さはどのくらいですか。</span>（～的長度大概多少？）把長さ換成<span class='gd-jp'>重さ</span>、<span class='gd-jp'>大きさ</span>、<span class='gd-jp'>深さ</span>就能問各種東西。</div>",
  "n4-73": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「〜ことがあります」就是中文的<b>「有時候會～」</b>。意思是這件事<b>不是每次都發生，但偶爾會發生</b>。就像捷運廣播或網購頁面上寫的「可能會有延誤」，在提醒你「這種情況是有可能遇到的」。</div><div class='gd-h'>怎麼接</div><div class='gd-sec'>有時候<b>會</b>做：辭書形＋ことがあります<br><span class='gd-pair'><span class='gd-jp'>遅れる</span> → <span class='gd-jp'>遅れることがあります</span></span>（有時候會遲到、誤點）<br>有時候<b>不</b>做：ない形＋ことがあります<br><span class='gd-pair'><span class='gd-jp'>食べない</span> → <span class='gd-jp'>食べないことがあります</span></span>（有時候不吃）<br>跟朋友講就用普通形<span class='gd-jp'>ことがある</span>，意思一樣。</div><div class='gd-h'>什麼時候用</div><div class='gd-sec'><span class='gd-tag'>講自己的習慣</span>不是天天這樣，偶爾會。常跟<span class='gd-jp'>ときどき</span>（有時）、<span class='gd-jp'>たまに</span>（偶爾）一起出現。</div><div class='gd-ex-line'>・<span class='gd-jp'>忙しいとき、朝ご飯を食べないことがあります。</span>（忙的時候，我有時候不吃早餐）</div><div class='gd-ex-line'>・<span class='gd-jp'>たまに電車で寝てしまうことがある。</span>（我偶爾會在電車上睡著）</div><div class='gd-sec'><span class='gd-tag'>提醒、公告</span>店家、車站、商品說明很愛用，先跟你講「這種事可能會發生喔」。</div><div class='gd-ex-line'>・<span class='gd-jp'>雨の日は、バスが遅れることがあります。</span>（下雨天公車有時候會誤點）</div><div class='gd-ex-line'>・<span class='gd-jp'>商品の色が写真と違うことがあります。</span>（商品顏色有時候會跟照片不一樣）</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・<b>每天、一定、總是</b>會發生的事不能用。<span class='gd-jp'>毎日コーヒーを飲むことがあります</span>是錯的，每天喝就直接說<span class='gd-jp'>毎日コーヒーを飲みます</span>。<br>・中文的「會」有很多意思，不是每個「會」都能換成ことがあります。「我會說日文」是<span class='gd-jp'>日本語が話せます</span>；「明天會下雨」是<span class='gd-jp'>明日は雨が降るでしょう</span>。只有「<b>有時候會</b>」才用ことがあります。<br>・前面一定要用辭書形或ない形。只要寫成た形，意思就完全變了，下面會講。<br>・常聽到<span class='gd-jp'>遅れることもあります</span>，把が換成も，語氣變成「<b>也是有可能會</b>～」，比較委婉，公告很常用。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'><b>辭書形＋ことがある</b>＝有時候會（講現在的傾向）<br><span class='gd-jp'>この電車は遅れることがあります。</span>（這班電車有時候會誤點）<br><b>た形＋ことがある</b>＝曾經～過（講過去的經驗）<br><span class='gd-jp'>この電車は遅れたことがあります。</span>（這班電車曾經誤點過）<br>只差一個字，前面是「平常偶爾會這樣」，後面是「以前發生過一次（以上）」。</div><div class='gd-sec'><b>かもしれません</b>＝猜<b>某一次</b>會不會發生<br><span class='gd-jp'>明日は電車が遅れるかもしれません。</span>（明天電車可能會誤點）<br><b>ことがあります</b>＝講<b>平常</b>的狀況，偶爾就會遇到<br><span class='gd-jp'>雪の日は電車が遅れることがあります。</span>（下雪天電車有時候會誤點）</div><div class='gd-warn'>判斷小訣竅：「曾經～過」用た形＋ことがある；「平常有時候會～」用辭書形＋ことがある；「這次可能會～」用かもしれません。</div><div class='gd-h'>學會之後可以接著學</div><div class='gd-sec'>名詞也可以用，在名詞後面加<span class='gd-jp'>の</span>：<span class='gd-jp'>この時間は満席のことがあります。</span>（這個時段有時候會客滿）</div>",
  "n4-74": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>中文要對長輩客氣，會把「你」換成「您」。日文有一招很像：<b>把長輩、上司、客人做的動作，換成「れる・られる」的樣子</b>，就有尊敬的感覺了。<br>例如「社長回去了」，一般說<span class='gd-jp'>帰りました</span>，尊敬一點就說<span class='gd-jp'>帰られました</span>。它是敬語裡最好上手的入門款，客氣程度比較輕。</div><div class='gd-h'>什麼時候用</div><div class='gd-sec'><span class='gd-tag'>講長輩的動作</span>跟別人聊到老師、主管做了什麼。</div><div class='gd-ex-line'>・<span class='gd-jp'>部長はもう帰られました。</span>（部長已經回去了）</div><div class='gd-ex-line'>・<span class='gd-jp'>社長は来週、大阪に出張されます。</span>（社長下週要去大阪出差）</div><div class='gd-sec'><span class='gd-tag'>當面問對方</span>直接問老師、客人要做什麼。</div><div class='gd-ex-line'>・<span class='gd-jp'>先生はいつ日本へ行かれますか。</span>（老師您什麼時候要去日本？）</div><div class='gd-ex-line'>・<span class='gd-jp'>何を飲まれますか。</span>（您要喝什麼？）</div><div class='gd-h'>怎麼變：先看動詞是哪一類</div><div class='gd-sec'>好消息：它的長相跟<b>受身形（被動形）一模一樣</b>，會了被動形就等於會了這個。</div><div class='gd-sec'><b>第一類（五段動詞）</b>：最後一個音換成同一行的「あ」段音，再加「れる」。<br><span class='gd-pair'><span class='gd-jp'>行く</span> → く換成か → <span class='gd-jp'>行かれる</span></span><br><span class='gd-pair'><span class='gd-jp'>読む</span> → <span class='gd-jp'>読まれる</span></span><span class='gd-pair'><span class='gd-jp'>話す</span> → <span class='gd-jp'>話される</span></span><span class='gd-pair'><span class='gd-jp'>帰る</span> → <span class='gd-jp'>帰られる</span></span><br>「う」結尾的要換成<b>わ</b>，不是あ：<span class='gd-pair'><span class='gd-jp'>会う</span> → <span class='gd-jp'>会われる</span></span></div><div class='gd-sec'><b>第二類（一段動詞）</b>：把最後的「る」拿掉，加「られる」。<br><span class='gd-pair'><span class='gd-jp'>出かける</span> → <span class='gd-jp'>出かけられる</span></span><span class='gd-pair'><span class='gd-jp'>始める</span> → <span class='gd-jp'>始められる</span></span></div><div class='gd-sec'><b>第三類（只有兩個，直接背）</b>：<span class='gd-pair'><span class='gd-jp'>する</span> → <span class='gd-jp'>される</span></span>（<span class='gd-pair'><span class='gd-jp'>出発する</span> → <span class='gd-jp'>出発される</span></span>）、<span class='gd-pair'><span class='gd-jp'>来る</span> → <span class='gd-jp'>来られる</span>（こられる）</span></div><div class='gd-sec'>實際講話時，通常再接成ます形：<span class='gd-pair'><span class='gd-jp'>行かれる</span> → <span class='gd-jp'>行かれます</span></span>、過去就是<span class='gd-jp'>行かれました</span>。</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・只能用在<b>別人</b>身上。講自己的動作用尊敬形很奇怪，<span class='gd-jp'>私は明日行かれます</span>是錯的，要說<span class='gd-jp'>私は明日行きます</span>。<br>・跟外人聊到<b>自己家人</b>時也不用，不能說<span class='gd-jp'>父は帰られました</span>，說<span class='gd-jp'>父は帰りました</span>就好。<br>・<span class='gd-jp'>会う</span>是<span class='gd-jp'>会われる</span>，不是「あれる」。<br>・第二類和<span class='gd-jp'>来る</span>的尊敬形，剛好也跟「可能形（能～）」長一樣：<span class='gd-jp'>来られます</span>可能是「您會來」也可能是「能來」。怕被誤會時，日本人常改用專用的尊敬說法，像<span class='gd-jp'>来る</span>改用<span class='gd-jp'>いらっしゃる</span>、<span class='gd-jp'>食べる</span>改用<span class='gd-jp'>召し上がる</span>、<span class='gd-jp'>見る</span>改用<span class='gd-jp'>ご覧になる</span>。<br>・不要把兩種敬語疊在一起，<span class='gd-jp'>お帰りになられる</span>雖然常聽到，但算是用過頭的錯誤說法，選一種就好。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'><b>尊敬形</b>＝長輩<b>自己</b>做這件事，句子裡沒有誰「被」怎樣：<br><span class='gd-jp'>部長が帰られました。</span>（部長回去了）<br><b>受身形</b>＝有人<b>「被」</b>做了什麼，做動作的人前面常用「に」：<br><span class='gd-jp'>部長に怒られました。</span>（我被部長罵了）<br><b>可能形</b>＝問<b>「能不能」</b>：<br><span class='gd-jp'>先生は刺身が食べられますか。</span>（老師敢吃生魚片嗎？）<br>同樣是「られます」，意思要看上下文決定。</div><div class='gd-warn'>判斷小訣竅：主詞是長輩、他自己在做、沒有「被」也沒有「能不能」的意思，就是尊敬形。</div><div class='gd-h'>學會之後可以接著學</div><div class='gd-sec'>更客氣的說法是「お＋ます形去掉ます＋になる」：<span class='gd-jp'>社長はお帰りになりました。</span>（社長回去了），比<span class='gd-jp'>帰られました</span>更有禮貌，可以接著看「尊敬語」那一課。</div>",
  "n4-75": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>中文說「喝、不喝、能喝、被喝、讓他喝」，是在「喝」的前後加字。日文是<b>改動詞的尾巴</b>，尾巴怎麼改，要看這個動詞是哪一類。所以不管學哪一種變化，<b>第一步都是先分類</b>。分對了，後面就是套規則。</div><div class='gd-h'>第一步：判斷動詞是哪一類</div><div class='gd-sec'>看動詞的辭書形（字典查得到、還沒變化的原形，例如<span class='gd-jp'>飲む</span>、<span class='gd-jp'>食べる</span>），照順序問自己三個問題：<br><b>1. 是不是する或来る？</b>是的話就是<b>第三類（する・来る）</b>。<span class='gd-jp'>勉強する</span>、<span class='gd-jp'>掃除する</span>這種「名詞＋する」也算這一類。<br><b>2. 最後一個字不是る？</b>像<span class='gd-jp'>飲む</span>、<span class='gd-jp'>書く</span>、<span class='gd-jp'>買う</span>、<span class='gd-jp'>話す</span>，一律是<b>第一類（五段動詞）</b>。<br><b>3. 最後是る的話，聽る前面那個音：</b><br>前面是「i」或「e」的音，大多是<b>第二類（一段動詞）</b>：<span class='gd-jp'>食べる</span>（べ是 be）、<span class='gd-jp'>起きる</span>（き是 ki）、<span class='gd-jp'>見る</span>（み是 mi）。<br>前面是「a、u、o」的音，就是<b>第一類</b>：<span class='gd-jp'>わかる</span>、<span class='gd-jp'>作る</span>、<span class='gd-jp'>乗る</span>。<br>第 3 步有幾個例外，<span class='gd-jp'>帰る</span>、<span class='gd-jp'>入る</span>、<span class='gd-jp'>走る</span>、<span class='gd-jp'>知る</span>、<span class='gd-jp'>切る</span>、<span class='gd-jp'>要る</span>看起來像第二類，其實是<b>第一類</b>，要直接背起來。</div><div class='gd-h'>同一個動詞，最常用的六種樣子</div><div class='gd-sec'><b>第一類：以<span class='gd-jp'>飲む</span>為例</b>。做法是把最後的「む」換成同一行的其他音：<br>む換成み，加ます：<span class='gd-pair'><span class='gd-jp'>飲む</span> → <span class='gd-jp'>飲みます</span></span>（喝，禮貌說法）<br>む換成ま，加ない：<span class='gd-pair'><span class='gd-jp'>飲む</span> → <span class='gd-jp'>飲まない</span></span>（不喝）<br>む換成め，加る：<span class='gd-pair'><span class='gd-jp'>飲む</span> → <span class='gd-jp'>飲める</span></span>（能喝，可能形）<br>む換成ま，加れる：<span class='gd-pair'><span class='gd-jp'>飲む</span> → <span class='gd-jp'>飲まれる</span></span>（被喝，受身形）<br>む換成ま，加せる：<span class='gd-pair'><span class='gd-jp'>飲む</span> → <span class='gd-jp'>飲ませる</span></span>（讓人喝，使役形）</div><div class='gd-sec'><b>第一類的て形</b>另有一套規則，看最後一個字決定：<br>う・つ・る → って：<span class='gd-pair'><span class='gd-jp'>買う</span> → <span class='gd-jp'>買って</span></span><span class='gd-pair'><span class='gd-jp'>待つ</span> → <span class='gd-jp'>待って</span></span><span class='gd-pair'><span class='gd-jp'>帰る</span> → <span class='gd-jp'>帰って</span></span><br>む・ぶ・ぬ → んで：<span class='gd-pair'><span class='gd-jp'>飲む</span> → <span class='gd-jp'>飲んで</span></span><span class='gd-pair'><span class='gd-jp'>遊ぶ</span> → <span class='gd-jp'>遊んで</span></span><br>く → いて：<span class='gd-pair'><span class='gd-jp'>書く</span> → <span class='gd-jp'>書いて</span></span>　ぐ → いで：<span class='gd-pair'><span class='gd-jp'>泳ぐ</span> → <span class='gd-jp'>泳いで</span></span><br>す → して：<span class='gd-pair'><span class='gd-jp'>話す</span> → <span class='gd-jp'>話して</span></span></div><div class='gd-sec'><b>第二類：以<span class='gd-jp'>食べる</span>為例</b>，這一類最簡單，一律把る拿掉，再加上後面的部分：<br><span class='gd-jp'>食べます</span>、<span class='gd-jp'>食べない</span>、<span class='gd-jp'>食べて</span>、<span class='gd-jp'>食べられる</span>（能吃）、<span class='gd-jp'>食べられる</span>（被吃）、<span class='gd-jp'>食べさせる</span>（讓人吃）<br>第二類的可能形跟受身形<b>長得一模一樣</b>，只能靠前後文判斷是哪一個。</div><div class='gd-sec'><b>第三類：只有兩個，直接背</b><br><span class='gd-jp'>する</span>：<span class='gd-jp'>します</span>、<span class='gd-jp'>しない</span>、<span class='gd-jp'>して</span>、<span class='gd-jp'>できる</span>（能做）、<span class='gd-jp'>される</span>（被做）、<span class='gd-jp'>させる</span>（讓人做）<br><span class='gd-jp'>来る</span>：<span class='gd-jp'>来ます</span>、<span class='gd-jp'>来ない</span>、<span class='gd-jp'>来て</span>、<span class='gd-jp'>来られる</span>（能來，受身形也是這個樣子）、<span class='gd-jp'>来させる</span>（讓人來）<br>来る的漢字不變，但是念法會跟著變：<br>辭書形、ば形念く（くる、くれば）；<br>ます形、て形、た形念き（きます、きて、きた）；<br>ない形、可能形、受身形、使役形念こ（こない、こられる、こさせる）。</div><div class='gd-h'>「順序」不是一個接一個變</div><div class='gd-sec'>上面這些形，<b>每一個都是從辭書形直接變出來的</b>。不需要先變成ます形才能變て形，也不需要先變成可能形才能變受身形。<br>有一個很好用的規律：可能形、受身形、使役形最後都是「〜る」，<b>變出來以後就是一個新的第二類動詞</b>，可以再照第二類的規則變下去：<br><span class='gd-pair'><span class='gd-jp'>飲める</span> → <span class='gd-jp'>飲めます</span></span><span class='gd-pair'><span class='gd-jp'>飲める</span> → <span class='gd-jp'>飲めない</span></span></div><div class='gd-ex-line'>・<span class='gd-jp'>日本語の新聞が読めます。</span>（我看得懂日文報紙）</div><div class='gd-ex-line'>・<span class='gd-jp'>漢字はまだあまり書けない。</span>（漢字我還不太會寫）</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・<span class='gd-jp'>帰る</span>這類例外是第一類，所以要說<span class='gd-jp'>帰ります</span>、<span class='gd-jp'>帰らない</span>、<span class='gd-jp'>帰って</span>，不能說帰ます、帰ない、帰て。<br>・最後是う的動詞，變ない形、受身形、使役形時，う要換成<b>わ</b>，不是あ：<span class='gd-jp'>買わない</span>、<span class='gd-jp'>買われる</span>、<span class='gd-jp'>買わせる</span>。<br>・<span class='gd-jp'>行く</span>的て形是<span class='gd-jp'>行って</span>，不照「く → いて」的規則，不能說行いて。<br>・「名詞＋する」的可能形，是把する換成<span class='gd-jp'>できる</span>：<span class='gd-jp'>勉強できる</span>（能讀書）。<span class='gd-jp'>勉強される</span>是受身形，意思不一樣。<br>・日常口語常聽到<span class='gd-jp'>食べれる</span>、<span class='gd-jp'>見れる</span>（少了ら），講話時很普遍，但考試和正式文章要用<span class='gd-jp'>食べられる</span>、<span class='gd-jp'>見られる</span>。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'>同樣是<span class='gd-jp'>飲む</span>，可能形、受身形、使役形只差一兩個音，意思完全不同：<br><b>能</b>：可能形</div><div class='gd-ex-line'>・<span class='gd-jp'>少しならお酒が飲める。</span>（喝一點酒的話我還可以）</div><div class='gd-sec'><b>被</b>：受身形</div><div class='gd-ex-line'>・<span class='gd-jp'>弟に私のジュースを飲まれた。</span>（我的果汁被弟弟喝掉了）</div><div class='gd-sec'><b>讓</b>：使役形</div><div class='gd-ex-line'>・<span class='gd-jp'>子どもに薬を飲ませる。</span>（讓小孩吃藥）</div><div class='gd-warn'>判斷小訣竅：第一類看尾巴，「え段音＋る」是能，「あ段音＋れる」是被，「あ段音＋せる」是讓。第二類的「られる」可能是能也可能是被，要看前後文；「させる」就是讓。</div><div class='gd-h'>學會之後可以接著學</div><div class='gd-sec'>分類熟了，可以一個一個深入學：意向形（<span class='gd-jp'>飲もう</span>）、可能形、ば形（<span class='gd-jp'>飲めば</span>）、受身形、使役形。最後再學把使役和受身疊在一起的使役受身形（<span class='gd-jp'>飲ませられる</span>／<span class='gd-jp'>飲まされる</span>，被逼著喝）。</div>"
});
(window.GRAMMAR_DETAIL_LV = window.GRAMMAR_DETAIL_LV || {}).n4 = true;
